        }
    } else {
        // Prefer bins with below-average residual (tighter bins) for small items.
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item would fit the post residual exactly, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
