    // Non-linear coupling: wasted-space penalty shaped by stream progress.
    // Early on, large residuals are tolerable (bins will fill later);
    // late in the stream, dead space is costly.
    let waste_penalty = post_norm.powf(2.0 + 3.0 * progress) * cap * (0.5 + progress);
    score += waste_penalty;

    // Smooth reward for near-perfect fits: subtract a Gaussian-like bump
    // around post_residual == 0, sharper as the stream progresses.
    let tightness = (-post_norm * post_norm * (8.0 + 12.0 * progress)).exp();
    score -= 12.0 * tightness;

