    // to avoid opening a new bin (smoothly weighted by stream progress).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }

    // Slight penalty for spreading across many bins when residuals are plentiful:
    // encourages consolidation when mean residual is high.
