}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality depends on which
    // "usable slot" class the leftover belongs to.
    // Class 0: post_residual == 0            -> perfect fit, huge reward
    // Class 1: post_residual in 1..=10       -> tiny dead space, strong reward
    // Class 2: post_residual in 11..=30      -> still usable by small items
    // Class 3: post_residual in 31..=60      -> mediocre
    // Class 4: post_residual in 61..=100     -> large gap, penalize mildly
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 8.0;
    } else if pr <= 60 {
        score += 4.0;
    } else {
        score += 10.0;
    }

    // Integer-division thresholds: leftover divisible by common small-item
    // sizes (10, 20, 25, 50) is more likely to be filled later.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            // next item won't fit here; leftover risk scales with gap
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (post_residual as f64).min(20.0) * 0.3;
    }

    // New-bin candidate: opening a fresh bin is attractive early in the
    // stream (many future items to fill it), less so near the end.
    if bin_residual == bin_capacity {
