        let fresh_bonus = 18.0 * (1.0 - progress) + 5.0;
        score -= fresh_bonus;
        // If item is large relative to capacity, filling a fresh bin wastes
        // its flexibility; small items in a fresh bin are fine.
        if item_size > bin_capacity / 2 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is far from the mean (tight bins first):
    // placing into a bin tighter than average keeps many loose bins open.
    score -= (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.3;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
