    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer division thresholds on post_residual: dead-space classes.
    // Residuals < 10 are nearly unusable (min item size historically 10, but be safe with 1..100).
    if post_residual == 0 {
        score -= 40.0; // perfect fit is best
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Modulo arithmetic on post_residual vs common item-size classes (multiples of 5/10).
    let post_mod10 = post_residual % 10;
    let post_mod5 = post_residual % 5;
    if post_mod10 == 0 {
        score -= 6.0; // residual aligned to decade: likely reusable by next items
    } else if post_mod5 == 0 {
        score -= 3.0;
    } else {
        score += (post_mod5 as f64) * 0.8; // ragged residual penalized
    }

    // Coupling with next item: can the next item exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // guaranteed chain fit
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item divides residual into a clean class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
            let new_post = post_residual - next_item_size;
            if new_post < 10 {
                score -= 5.0; // lookahead leads to near-dead space, still acceptable
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use this residual: residual risk increases
            score += frac * 8.0;
        }
    }

    // Large post_residual means wasted space in a used bin -> mild penalty relative to new bin.
    score += frac * frac * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline with slight openness early,
    // penalized late when consolidating is better.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 20.0 - (mean_residual / cap) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host the larger upcoming item too
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Mild pressure to reduce open bin count fragmentation.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "usable" if the next item can fit into it; otherwise it is
    // dead space whose penalty grows super-linearly as it shrinks.
    let pr = post_residual as f64;
    if next_item_size > 0 && post_residual >= next_item_size {
        // Gap is usable by lookahead: reward proportionally to tightness.
        let tightness = (post_residual as f64 - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - tightness / bin_capacity as f64);
    } else if post_residual > 0 {
        // Dead space: quadratic penalty, worst for tiny gaps (1..10).
        let dead = if pr < 10.0 { 60.0 + (10.0 - pr) * 8.0 } else { pr * pr / (bin_capacity as f64) };
        score += dead;
    }

    // Perfect fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    let bin_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure and by how many alternatives exist.
        score += 25.0 + bin_pressure + (fitting_bins_count as f64) * 4.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid waste.
        score -= 20.0;
    }

    // Mean residual coupling: if this bin's post-residual deviates badly from
    // the fleet mean, nudge score to keep residuals homogeneous (easy to fill).
    score += 0.3 * (pr - mean_residual).abs();

    // Late-stream consolidation: as the stream progresses, avoid leaving many
    // fragmented bins; reward placements that leave large residuals early,
    // tight fits late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * pr * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 0.5;

    // 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        let next_fits = (post_residual as i64 - next_item_size as i64) as f64;
        if next_fits == 0.0 {
            // Perfect 2-item packing: huge reward.
            score -= 1000.0;
        } else if next_fits > 0.0 {
            // Next item fits too: reward proportionally to tightness.
            score -= 200.0 - next_fits * 0.8;
        } else {
            // Next item won't fit here: penalize leftover dead space
            // that is too small to be useful (waste).
            let waste = -next_fits;
            if waste < 10.0 {
                score += 50.0; // tiny unusable sliver
            } else {
                score += waste * 0.3;
            }
        }
    }

    // Coupling with mean residual: bins already tighter than average
    // are better to consume first.
    let tightness = mean_residual - post_residual as f64;
    score += tightness * 0.4;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the
    // penalty late in the stream or when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 300.0 - 150.0 * progress;
        if open_bins_count == 0 {
            penalty = -50.0; // must open a bin
        }
        // If next item is large and post_residual small, new bin is fine.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) < 0
            && post_residual < 10 {
            penalty -= 100.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0; // dead space below min item size is nearly useless
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // If next item cannot fit anywhere after this placement, penalize leaving a big hole.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64;
        // Prefer opening new bins when few bins are open (early / low fragmentation).
        let load = open_bins_count as f64;
        score -= 20.0 / (1.0 + load * 0.3);
        // If no open bin fits well, opening a new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Global state: if mean residual is high, prefer bins that reduce fragmentation
    // (i.e., prefer bins with residual far below mean being filled).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.03 * dev;

    // Mild preference for fuller bins when many bins are open.
    score -= 0.02 * (bin_capacity as f64 - bin_residual as f64) * (open_bins_count.min(50) as f64) / 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let coupling = norm_post * norm_post * (0.5 + progress) * cap;
    score += 0.35 * coupling;

    // Reward tight fits (small post_residual) increasingly over time
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress) * 8.0;

    // Penalize dead space that cannot fit a plausible next item (smooth sigmoid-like gate)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (post - next) / cap;
        let gate = 1.0 / (1.0 + (-6.0 * gap).exp());
        score += 6.0 * gate * (0.5 + progress);
    }

    // Last-chance bonus: smooth function of fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 4.0 * scarcity * (1.0 - norm_post);

    // Mild penalty for bin fragmentation relative to mean residual
    let frag = (post - mean_residual).abs() / cap;
    score += 2.0 * frag * frag;

    // Prefer larger item consumption early (fill bins densely)
    score -= norm_item * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (capacity fractions) ---
    // Class 0: post_residual <= 10  (near-perfect fill, almost dead space)
    // Class 1: 10 < post_residual <= 25
    // Class 2: 25 < post_residual <= 50
    // Class 3: post_residual > 50   (bin still half-open, valuable)
    let post_class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward tight fits strongly (subtract), penalize large leftover mildly.
    score -= match post_class {
        0 => 60.0,
        1 => 35.0,
        2 => 12.0,
        3 => 0.0,
        _ => 0.0,
    };

    // --- Integer-division thresholds: how many "typical" items (>=10) still fit? ---
    let slots_left = post_residual / 10; // items of min size that could still fit
    score -= (slots_left as f64) * 4.0;  // residual that can host future items is useful

    // --- Modulo arithmetic on post_residual: dead-space classes ---
    // Residuals that are NOT expressible as sums of small common items (mod 10 != 0)
    // tend to become dead space; penalize non-round residuals.
    if post_residual % 10 != 0 {
        score += 6.0;
        if post_residual % 5 != 0 { score += 4.0; }
    }
    // Extremely awkward small residuals (1..=9) are dead space if no tiny items exist.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-wasted bin, but keep slight preference over overflow
    }

    // --- Lookahead coupling: does the next item fit into the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: big reward for chaining placements.
            let slack = post_residual - next_item_size;
            score -= 30.0 - (slack as f64).min(20.0); // tighter chain = better
            // Harmonic bonus: next item exactly fills a capacity fraction.
            if post_residual == next_item_size { score -= 20.0; }
            if post_residual % next_item_size.max(1) == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here; if this bin would then be stranded, penalize.
            if post_residual < 10 { score += 10.0; }
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that would be best-utilized.
        score += (fitting_bins_count as f64) * 1.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; encourage it only when current bins are crowded
        // or the item fits no open bin well (fitting_bins_count == 0 handled implicitly
        // since only this call exists then).
        score = post_residual as f64; // = capacity
        if open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if open_bins_count > 0 {
            // Opening a new bin is only attractive if existing residuals are small
            // relative to the item (mean residual can't host future items well).
            let mean_frac = mean_residual / cap;
            if mean_frac < (item_size as f64) / cap * 0.5 {
                score -= 15.0;
            } else {
                score += 25.0; // prefer filling existing bins
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // --- Mean-residual context: spread awareness ---
    // If this bin's residual deviates strongly below the mean, it's a "garbage bin";
    // filling garbage bins is good (cleans up the pool).
    let resid_frac = bin_residual as f64 / cap;
    if resid_frac < mean_residual / cap - 0.15 {
        score -= 8.0;
    }

    // Mild preference to fill older/crowded pools: more open bins -> tighter packing needed.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to host any
    // typical future item are heavily penalized (non-linearly).
    let dead_zone = 20.0; // gaps <= 20 are nearly unusable for items in 10..80
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward filling a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins; opening new bins gets progressively more expensive.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin wastes (capacity - item).
    // Penalize it proportionally, more so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (bin_capacity - item_size) as f64 * (1.0 + progress);
        // But if no existing bin fits at all, soften the penalty.
        if fitting_bins_count == 0 {
            score -= (bin_capacity - item_size) as f64 * 1.2;
        }
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward the placement (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if post_residual is too small for the next item but nonzero.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Slight preference toward bins with below-average residual (denser bins),
    // keeping emptier bins flexible for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes full after next item
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // penalize by leftover after the lookahead item
            score += next_post as f64 * 0.8;
            // extra reward for tight two-step packing
            if next_post <= 10 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.5;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (below mean = tighter bin)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last chance: only one bin fits the item, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        let tight_fit = (post_residual as f64) <= 5.0;
        if !tight_fit {
            score += 35.0;
        } else {
            score += 10.0;
        }
    }

    // Late in the stream: consolidate, avoid opening extra bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual is good, but amplify it).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 80 {
        // residual that could host a typical item is fine; bias toward "nice" residuals
        score -= 4.0;
    } else {
        // large residual after a small item: wasteful if bin was nearly full
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 14.0 * chain_quality;
    } else if next_item_size > 0 {
        // next item won't chain here: mild penalty, worse late in the stream
        score += 5.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with below-mean residual (balancing load).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Discourage opening new bins early; allow it late when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual == bin_residual { 0.0 } else { 1.0 };
        let new_bin_bias = 30.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bias * (1.0 - poor_fit) + new_bin_bias * poor_fit;
        // extra penalty if any open bin could fit
        if fitting_bins_count > 0 {
            score += 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, smoothly squashed.
    let base = (pr / cap).powi(3) * 100.0;

    // Tight-fit reward: smooth bump when post_residual is small relative to item size.
    let item = item_size as f64;
    let tight = -(item / cap) * (1.0 - (pr / cap)).powi(2) * 30.0;

    // Dead-space penalty: penalize residuals too small to fit typical future items,
    // smooth via sigmoid of (usable threshold - pr).
    let dead = if pr > 0.0 {
        20.0 * (1.0 - pr / (0.25 * cap)) / (1.0 + (-(pr / (0.25 * cap) - 1.0) * 2.0).exp())
    } else {
        0.0
    };

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    let next = next_item_size as f64;
    let lookahead = if next > 0.0 {
        let fits = (pr >= next) as i32 as f64;
        let margin = ((pr - next) / cap).abs();
        -fits * (1.0 - margin.min(1.0)) * 15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer using the only fitting bin, scaled by progress.
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -25.0 * (0.5 + 0.5 * progress)
    } else {
        0.0
    };

    // New-bin candidate: mildly penalize opening new bins early, allow late in stream
    // or when residuals across bins are fragmented.
    let new_bin_penalty = if bin_residual == bin_capacity {
        35.0 * (1.0 - progress).powi(2) + 10.0 * (open_bins_count as f64 / (mean_residual / cap + 1.0)).min(10.0) * 0.1
    } else {
        0.0
    };

    // Fragmentation coupling: prefer bins whose residual deviates from mean favorably.
    let dev = (pr - mean_residual) / cap;
    let dev_term = 5.0 * dev * dev - 5.0 * dev;

    base + tight + dead + lookahead + last_chance + new_bin_penalty + dev_term
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into classes of 10.
    // Residuals that are "harmonically useful" (multiples of 10) are rewarded.
    let pr = post_residual;
    let class = pr / 10;                       // integer division class 0..10
    let class_mod = pr % 10;                   // offset within class
    score -= (10 - class_mod) as f64 * 0.35;   // prefer residuals close to a clean class boundary
    score += (class as f64).powi(2) * 0.15;    // quadratic penalty on class depth (large dead space)

    // Perfect fit or tiny residual is excellent.
    if pr == 0 {
        score -= 40.0;
    } else if pr < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement enables a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // harmonic class match between post-residual and next item
            let nclass = next_item_size / 10;
            if nclass == class {
                score -= 8.0;
            }
            score += 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: opening a bin wastes capacity when the item
    // could go somewhere reasonable; make empty bin attractive only for large items.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // large items (>60% of capacity) justify a fresh bin; small items should reuse
        score -= 30.0 * (frac - 0.5).max(0.0);
        score += 25.0 * (0.5 - frac).max(0.0);
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        score += 1.5 * open_bins_count as f64;
    } else {
        // reward reusing open bins, slightly more when many are open
        score -= 0.05 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (tight bins get emptied first).
    score += 0.10 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is the worst outcome
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginal gap, only usable by small items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill, best possible outcome
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Reward bins whose residual was already small (consolidating waste).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open-bin pressure: penalize using a bin when many are open,
    // but relax when this is the last fitting bin.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if fitting_bins_count > 1 {
        score += 20.0 * pressure;
    } else {
        score -= 30.0; // last-chance bin: strongly prefer filling it
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would leave an even smaller dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 && next_gap > 0 {
            score += 12.0;
        }
    }

    // Mild preference to keep mean residual high (avoid fragmenting many bins).
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64 / (open_bins_count as f64 + 2.0)) * (mean_residual / bin_capacity as f64);
        score += 45.0 * (1.0 - crowded);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward only if the leftover after the next item stays small
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here after placement: penalize mildly
            score += 8.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins already fit well.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // but a new bin is acceptable if it enables a perfect 2-step chain
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: heavily discount small post-residual.
    score -= 60.0 / (1.0 + post_residual as f64);

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let t = step_index as f64 / (total_items as f64 + 1.0);
        let look = next_item_size as f64;
        if (post_residual as f64) < look {
            // wasted space relative to lookahead, amplified over time
            score += 0.35 * (look - post_residual as f64) * (0.4 + t);
        } else {
            // bonus if lookahead also fits (chained packing)
            score -= 0.30 * (post_residual as f64 - look).min(20.0) * (1.0 - t);
        }
        // strongly reward bins where both current and next item chain well
        if (bin_residual as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 45.0;
        }
    } else {
        // last item: pure tightness matters most
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it before opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - fit_quality);
    }

    // New-bin candidate: penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + 4.0 * pressure;
        // early in stream, opening bins is cheaper; late stream, avoid sprawl
        let t = step_index as f64 / (total_items as f64 + 1.0);
        score -= 20.0 * (1.0 - t);
    }

    // Mild preference for fuller bins relative to fleet mean residual.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Reward using bins that are nearly full (avoid stranding them).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    // Slight penalty for very large item into nearly-empty large bin (waste).
    if item_size >= 70 && bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified as stream progresses
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth cubic coupling of post_residual with progress
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (cap - pr) * 0.15 * (1.0 + progress);

    // Penalize deviation from mean residual (prefer balanced bins early, divergent late)
    let dev = pr - mean_residual;
    score += dev * (0.1 - 0.25 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - norm_pr) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        let waste = norm_pr * norm_pr;
        score += 15.0 + 35.0 * (1.0 - progress) - 10.0 * waste * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let post_frac = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - post_frac).powi(6);

    // Harmonic class of post_residual: residual mod 10 classes.
    // Residuals that are multiples of 10 are "harmonic" — easier to fill later.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 2 || class >= 8 {
        score += 3.0; // awkward slivers
    }

    // Integer-division thresholds: post_residual buckets by /10.
    let bucket = post_residual / 10;
    score += match bucket {
        0 => -4.0,          // near-perfect fill
        1..=3 => 0.0,
        4..=6 => 2.0,       // half-empty bin wasted
        _ => 4.0,           // mostly empty: prefer other bins
    };

    // Lookahead coupling: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / cap).powi(3);
            // harmonic chain: both multiples of 10
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here; penalize leaving dead space it can't use
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement
    // would create large dead space and stream is early (many items remain).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // fresh bin base score: its post_residual = cap - item_size
        let fresh_post = (bin_capacity - item_size) as f64;
        let waste_here = post_residual as f64;
        if waste_here > 0.5 * cap && progress < 0.85 {
            score = fresh_post - 30.0; // open new bin for big items
        } else {
            score = fresh_post + 20.0; // prefer existing bins generally
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * post_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }
    // Penalize gaps too small for the smallest plausible item (1..100 range: gap < next item or < ~15 is risky)
    if post_residual > 0 && (post_residual as u32) < next_item_size.max(15) {
        score += 40.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open bins pressure: discourage opening new bins when stream is early/mid
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 50.0 * (1.0 - progress);
    } else {
        score -= 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-mean residual (keep big gaps for big future items)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mild pressure from number of open bins
    score += open_bins_count as f64 * 0.5 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: reward tight fits.
    score -= (bin_capacity as f64 - post_residual as f64) * 2.0;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but with slack: mild reward proportional to tightness.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item will not fit here: penalize leaving awkward gaps,
            // especially small unusable gaps.
            if post_residual < 10 {
                score += 25.0; // dead space, next item can't use it anyway
            } else {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below average
    // (concentrate filling), penalize bins far above mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as u32 {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when the current fit is poor
    // (empty bin has neutral post_residual == capacity, so add a mild penalty
    // that tight fits can overcome).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late-stream: be more conservative with new bins as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is always excellent
    } else {
        // Penalize dead space relative to capacity, non-linearly.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * waste_ratio * 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 + 0.3 * slack; // next item chains nicely
        } else {
            // Next item won't fit here; penalize proportionally to leftover gap.
            score += 0.2 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item, or late in the stream
    // with many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Opening a new bin costs ~capacity of unused space; compare to mean residual.
        let new_bin_cost = 60.0 + 40.0 * (1.0 - pressure) - 30.0 * progress;
        score += new_bin_cost;
        // If item is large, filling a fresh bin is more acceptable.
        score -= 0.15 * item_size as f64;
    }

    // Global state: when many bins are open, discourage fragmentation by
    // penalizing placements that leave residuals far from the mean.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (open_bins_count as f64).sqrt();
    }

    // Time horizon: early in the stream, be conservative (slightly prefer
    // keeping bins balanced); late in the stream, aggressively close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (0.5 + progress);

    // Tight fit reward: penalize small post_residual less as stream progresses
    let tight = -2.0 * (1.0 - norm_pr) * (0.5 + progress);

    // Dead-space penalty grows non-linearly late in the stream
    let dead = 4.0 * norm_pr * norm_pr * progress;

    // Lookahead coupling: bonus if next item fits post-residual
    let look = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -1.5 * (1.0 - progress)
    } else {
        0.5 * norm_pr
    };

    // Last-chance bin reward
    let last = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // Mean residual interaction: prefer bins deviating from mean early
    let dev = (pr - mean_residual) / cap;
    let dev_term = (1.0 - progress) * dev * dev * 3.0 - 0.5 * dev;

    score = pr + poly * cap + tight + dead + look + last + dev_term;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by small divisors is "reusable"
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else { score += 4.0; }
    }

    // Dead-space penalty: residuals too small for the minimum item class
    let min_item = 1u32;
    if pr > 0 && pr < min_item {
        score += 500.0;
    }

    // Modulo-class coupling with next item: reward residuals in the same
    // integer-division band as the upcoming item size
    if next_item_size > 0 {
        let nq = next_item_size / 10;   // decile class of next item
        let pq = pr / 10;               // decile class of residual
        if pr >= next_item_size {
            // next item fits: reward closeness of classes
            let class_gap = (pq as i32 - nq as i32).abs();
            score -= (8.0 - class_gap as f64).max(0.0) * 2.0;
            // exact modulo match bonus
            if pr % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize small leftover more
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // an awkward non-harmonic residue
    if bin_residual == bin_capacity {
        let awkward = pr > 0 && (pr % 10 != 0) && (pr < 10 * 2);
        if awkward {
            score -= 20.0;
        } else {
            // prefer existing bins generally
            score += 25.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += mean_residual * 0.05 + open_bins_count as f64 * 0.3;

    // Late-stream tightening: waste matters more toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 9 {
        // Unusable small gap: hard penalty (dead space archetype).
        score += 45.0;
    } else if post_residual <= 20 {
        // Marginal gap: mild penalty.
        score += 12.0;
    } else if post_residual <= 40 {
        score -= 5.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual stays usable for the next item.
            score -= 15.0;
        } else {
            // This placement strands the lookahead item.
            score += 8.0;
        }
    }

    // --- Last-chance bin pressure ---
    // If this is the only open bin that fits, using it avoids opening a new bin,
    // but only if the fit isn't dead-space-producing (dead-space term already applied).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Open-bins pressure ---
    // Mildly penalize placements that waste space when many bins are open,
    // scaled by how full the bin already is.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin competes with existing fits: penalize when many
        // bins are open or mean residual is high (space is being wasted).
        score += 30.0 * (open_bins_count as f64).sqrt() + 0.5 * mean_residual;
        // If no open bin can fit the item, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, fresh bins are cheap and keep flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect chain: item now, next item fills remainder
        } else if post_residual as f64 > nxt {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportional to wasted gap
            score += 6.0 * (diff / bin_capacity as f64);
        }
        // bonus if chain also leaves room for a third small item
        if post_residual as u32 >= next_item_size + 10 {
            score -= 3.0;
        }
    } else {
        // last item: purely minimize waste
        score -= 5.0;
    }

    // Tight fit reward relative to mean residual of open bins
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.35 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when the stream is early and consolidation is cheap
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
        score -= 4.0 * progress; // late in stream, fresh bins are fine
        // discourage new bin if this bin's residual would be very usable
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score += 8.0;
        }
    }

    // Dead-space penalty: residuals too small for any item (min size 1..10 typical)
    if post_residual < 10 && post_residual > 0 {
        score += 7.0;
    }

    // Slight preference to keep many bins' residuals balanced
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect/near-perfect fit bonus.
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that no future item (min size 1..10) can realistically use.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 60 {
        score += 0.5 * (post_residual as f64 - 60.0);
    }

    // Lookahead: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: opening a new bin is fine early or when
    // current fit is loose; penalize opening new bins when many bins exist
    // and the current fit is decent.
    if bin_residual == bin_capacity {
        let avg_load_pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + 10.0 * open_bins_count as f64 * (1.0 - progress);
        // If existing bins have large residuals (fragmented), opening fresh is less bad.
        score -= 10.0 * avg_load_pressure;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Prefer filling bins with below-average residual (balance consolidation).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late in stream: push toward closing out bins tightly.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let npr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress = t * t * (3.0 - 2.0 * t); // smoothstep
    score += progress * (npr * npr * npr) * cap * 0.8;   // penalize large dead space more as stream advances
    score -= (1.0 - progress) * (npr * npr) * cap * 0.4; // early on, tight fills are slightly less critical

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit * fit * 12.0;

    // Smooth lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).abs();
        let coupling = (1.0 - slack / cap).max(0.0);
        score -= coupling * coupling * 8.0 * (1.0 - progress + 0.3);
    }

    // Last-chance bin bonus, scaled smoothly by scarcity of fitting bins.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - npr);
    }

    // Mild penalty when this bin's residual deviates from mean residual (smooth dispersion term).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Slight pressure toward consolidating into fewer bins late in the stream.
    score += (open_bins_count as f64).ln() * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left after placement

    // Integer-division thresholds: classify post_residual into harmonic buckets.
    // Leftovers < 20 are "dead space" (most items >= 10, but small items are rare);
    // leftovers in [20, 50) can host medium items; >= 50 are highly reusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 30.0; // unusable dead space: penalize heavily
    } else if post_residual < 20 {
        score += 12.0; // only fits very small items
    } else if post_residual < 35 {
        score += 3.0; // moderately reusable
    } else if post_residual < 50 {
        score -= 4.0; // good reusable band
    } else {
        score -= 10.0; // half-empty bin: very flexible
    }

    // Modulo-arithmetic harmonic class: leftover mod 10 tells how many item-size
    // classes (sizes are multiples of 1, but granularity 10 is common) can nest.
    let harmony = (post_residual % 10) as f64;
    score += harmony * 0.8; // ragged leftovers slightly penalized

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportional to tightness of the future fit
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - tight.min(20.0);
        } else {
            // next item cannot use this leftover: penalize proportionally to wasted potential
            score += ((next_item_size - post_residual) as f64).min(25.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // but if leftover would be dead space, soften the bonus
        if post_residual < 10 && post_residual > 0 {
            score += 18.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early in the stream or when many bins are open;
        // penalize it late to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 25.0 * progress;
        // If no open bin gives a decent fit (this call context: many fitting bins means
        // open bins are fine), discourage new bins more.
        if fitting_bins_count > 0 && post_residual >= 50 {
            score += 15.0;
        }
        // A fresh bin wastes the whole capacity minus the item: mild constant penalty
        // scaled by how full the item fills it.
        score += (cap - item_size as f64) * 0.15;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean.
    // Placing into a bin with residual well above mean reduces fragmentation elsewhere.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev.max(0.0) * 0.1;
    score += (-dev).max(0.0) * 0.05;

    // Tight-fit reward: how snugly the item fits this bin relative to capacity.
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1..100 unknown, but small gaps < ~15 are risky)
    // are heavily penalized — they are effectively wasted capacity.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't chain here; penalize proportionally to wasted gap
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins dilute residual capacity; prefer
    // filling existing bins when bin count is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.8;

    // New-bin candidate: penalize mildly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    // Prefer bins whose residual is close to the item (best-fit character).
    score += ((bin_residual - item_size) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0 + 0.25 * (item_size as f64);
    }

    // Near-perfect match (small slack after the lookahead item).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 20.0 - 1.5 * slack;
        }
    }

    // Penalize unusable dead space: post_residual too small for the smallest item (1).
    // Here any residual >= 1 is usable, but tiny residuals relative to mean residual are waste.
    if (post_residual as f64) < mean_residual * 0.35 {
        score += 6.0;
    }

    // Reward filling bins tightly (post_residual near zero).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer only if this bin would leave a large awkward residual
    // and the next item could pair with the current item in a fresh bin.
    if bin_residual == bin_capacity {
        let pairing_bonus = if next_item_size > 0 {
            (item_size + next_item_size <= bin_capacity) as i32 as f64
        } else {
            0.0
        };
        // Base cost of opening a new bin; discounted when items pair well.
        score += 18.0 - 12.0 * pairing_bonus
            + 0.05 * open_bins_count as f64
            - (post_residual as f64) * 0.1;
    }

    // Late in the stream, be more conservative: keep residuals usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fits are strongly favored.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (-tight * 12.0).exp();

    // Dead-space penalty: small residual (<10, unusable by any item) is great; mid-range waste is bad.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward; penalize near-miss blocking.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 15 {
            score += 12.0; // next item barely misses: leave this bin for it? penalize
        }
    }

    // Time horizon: early in stream, be conservative with new bins; late, consolidate.
    let t = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (18.0 - 30.0 * t) * (1.0 - (open_bins_count as f64).min(10.0) / 12.0);

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins among ties.
    score -= 0.2 * item_size as f64;

    // Many open bins: discourage opening more, encourage filling.
    if open_bins_count > 5 {
        score += new_bin * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (low post-residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, leftover space becomes costlier (less future to fill it).
    let progress_coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) * cap;
    score += progress_coupling;

    // Smooth interaction: penalize post-residual that can't fit the lookahead item
    // (wasted dead space relative to next demand), smoothly via squared gap.
    let gap = (pr - next_item_size as f64).max(0.0) as f64;
    score += 0.6 * gap * gap / cap;

    // Reward bins whose residual exactly accommodates the next item (smoothly):
    let fit_next = (norm_pr - norm_next).abs();
    score -= 8.0 * (1.0 - fit_next.min(1.0)) * (1.0 - fit_next.min(1.0)) * (1.0 - progress);

    // Last-chance bin: strongly favor using it (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty when this bin's residual deviates from mean residual
    // (encourage balanced residual distribution, smoothed by open bin count).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate (bin_residual == bin_capacity): penalize so it's only
    // chosen when no open bin offers a decent fit; relax slightly late in stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.4 * progress) + 10.0 * norm_item;
    }

    // Mild reward for filling bins that are nearly full (smooth saturation term)
    let fullness = 1.0 - norm_pr;
    score -= 5.0 * fullness * fullness * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: reward residuals that are
    // "harmonious" with common item sizes (multiples of small units) ----
    let pr = post_residual;
    // Modulo-10 harmony: residual divisible by 10 is reusable by typical items
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }
    // Integer-division threshold classes on post_residual
    let pr_class = pr / 20; // coarse class 0..5
    score += pr_class as f64 * 1.5;

    // ---- Perfect-fit harmonic bonus ----
    if pr == 0 {
        score -= 40.0;
    }

    // ---- Lookahead coupling: can next item fit into post_residual? ----
    if next_item_size > 0 && pr >= next_item_size {
        // next item fits: strongly reward, more if harmonic fit
        score -= 8.0;
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
        // fractional capacity coupling
        let frac = (pr - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - frac).abs().min(0.5);
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space proportionally
        score += (pr as f64) * 0.35;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0; // strongly prefer using the only bin that fits
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: neutral baseline; penalize slightly so it is
        // chosen only when open bins look truly bad, unless stream is early
        // or many bins already open.
        score = bin_capacity as f64 * 0.9;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        if open_bins_count > 4 {
            score += (open_bins_count as f64 - 4.0) * 1.2;
        }
        // If next item is large and current item small, opening fresh bin
        // can be good (reserve space logic).
        if next_item_size > 60 && item_size <= 30 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // ---- Mean residual coupling: prefer bins far from the mean when mean
    // is high (consolidate waste), near mean when mean is low ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > bin_capacity as f64 * 0.5 {
        score += dev * 0.15;
    } else {
        score -= dev * 0.05;
    }

    // ---- Modulo harmony between item and residual (integer division) ----
    let harmony = (bin_residual / item_size.max(1)) % 4;
    score -= harmony as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill (shouldn't happen, but reward anyway)
    }

    // Penalize small unusable gaps much more than large usable gaps (super-linear).
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        score += 60.0 * (10.0 - pr); // dead space in the worst range
    } else if pr > 10.0 && pr < 20.0 {
        score += 15.0 * (20.0 - pr) / 10.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - pr / (item_size as f64 + pr);
        score -= 30.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (full residual) gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the item would leave a big usable gap in an existing bin anyway,
        // opening a fresh bin is less bad when mean residual is already fragmented.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Favor bins whose residual is close to what we consume.
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score -= 10.0 / (1.0 + fit_gap);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item can still fit afterwards
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // next item won't fit in the leftover tiny gap -> penalize
        score += 20.0;
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: lookahead matters more early/mid stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let lookahead_weight = 1.0 - 0.5 * progress;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0 * lookahead_weight;
        }
        // Near match: next item can still fit tightly with small slack.
        else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0 * lookahead_weight;
            } else {
                // Partial credit decaying with slack.
                score -= (25.0 * lookahead_weight) * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot fit in the leftover: leftover is likely dead space.
            // Penalize small unusable leftovers more than large usable ones.
            if post_residual < 10 {
                score += 15.0; // tiny dead space
            }
            // Reward keeping residual near the mean (balanced packing).
            score += 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    } else {
        // Last item: pure tightness fit is best.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (pristine bin): base its score on the space it leaves,
    // slightly favored so it wins only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Discourage hoarding bins when many are already open with room.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect fit for the lookahead item: strongly favor leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a residual that is a "dead zone": too small for any item but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (creates huge dead space).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 40 {
            score += 20.0; // poor fit in the sole bin: soften the reward
        }
    }

    // Reward filling bins that are already below the mean residual (consolidation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.5 * (mean_residual - residual_f);
    } else {
        score += 0.25 * (residual_f - mean_residual);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic penalty.
        score += new_bin_penalty;
        // If the current item is huge relative to capacity, opening a fresh bin is fine.
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If many bins are open and mean residual is small, prefer existing bins.
        score += 0.3 * open_bins_count as f64;
    } else {
        // Existing bin: discount grows with progress (urgency to close bins).
        score -= 5.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item cannot fit in post_residual, this bin
    // placement is more "final" — reward if post_residual is small, penalize waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item.
        score += 0.2 * post_residual as f64;
    }

    // Mild preference for bins with larger residuals when few bins fit the item
    // (preserve tight bins for tighter items later).
    if fitting_bins_count > 1 {
        score += 0.1 * residual_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Tight fits get rewarded more strongly as stream progresses.
    let tight = (item_size as f64 / bin_residual.max(1) as f64).powi(3);
    score -= 12.0 * tight * (0.4 + 0.6 * progress);

    // Penalize residual that is dead space: small post_residual unusable by typical next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let usable = (pr / nxt.max(1.0)).min(1.0);
        score -= 6.0 * usable * usable;
        score += 4.0 * (1.0 - usable) * (1.0 - usable);
    }

    // Non-linear coupling: normalized residual vs mean residual divergence.
    let norm = pr / cap;
    let dev = norm - mean_residual / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Last-chance bin bonus (smooth).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Discourage hoarding many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress * norm;

    // New-bin candidate: mildly penalize opening fresh bins unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (mean_residual / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod-10 classes) ---
    // Residuals in low classes (0..=9) are "dead" — nearly impossible to refill.
    let dead = (post_residual < 10) as i32;
    score += if dead { -30.0 } else { 0.0 };

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Small residual that the lookahead item can exactly fill: pair bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // Lookahead item fits into the post residual: mild pair bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Lookahead item cannot use the post residual: penalize wasted space,
    // scaled by how "odd" the residual class is (mod 10 distance from 0).
    if next_item_size > 0 && next_item_size > post_residual {
        let cls = post_residual % 10;
        score += (cls as f64) * 0.8;
    }

    // Integer-division thresholds on post_residual: usable windows.
    if post_residual >= 50 { score -= 10.0; }        // roomy bin stays flexible
    else if post_residual >= 30 { score -= 5.0; }
    else if post_residual >= 20 { score += 3.0; }
    else if post_residual >= 10 { score += 8.0; }    // awkward window

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }
    // Many competing bins: prefer tighter fits (classic best-fit sharpening).
    if fitting_bins_count > 2 {
        score -= (fitting_bins_count.min(10) as f64) * 1.5;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is generally bad unless it enables a perfect fit
        // (item fills it exactly) or nothing else fits well.
        score = 45.0;
        if item_size == bin_capacity { score -= 200.0; }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity { score -= 80.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
        // Early in the stream, fresh bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty proportional to global slack: keep mean residual low.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 unknown,
    // so treat gaps < ~15 as near-dead, and scale penalty for gaps below the mean item size).
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Dead-space penalty: sharp non-linear blow-up for tiny gaps.
        if gap < 15.0 {
            score += 40.0 * (15.0 - gap) / 15.0;
        } else if gap < 30.0 {
            score += 8.0 * (30.0 - gap) / 30.0;
        }
        // Perfect fit bonus: exact fill is the best possible outcome.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer opening a new bin when all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open
        // (open-bin pressure: many open bins -> discourage opening more).
        score = bin_capacity as f64 + 10.0 * open_bins_count as f64;
        // If there are other fitting bins, opening new is wasteful unless their gaps are dead.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Early in the stream, having a fresh bin is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
        score += 1.5 * open_bins_count as f64;
        // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let perfect_next = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - perfect_next / bin_capacity as f64);
        }
        // Penalize bins whose residual deviates far above the mean (hoarded space).
        score += 0.5 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward post_residual that exactly (or nearly) matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 60.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            score -= (nxt / (diff + 1.0)) * 8.0;
        } else {
            // leftover smaller than next item: dead space unless tiny
            score += diff * 0.5;
        }
        // penalize leaving residue that no plausible item (>=1) can use well
        if post_residual < 10 {
            score -= 5.0; // near-perfect fill is good
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // stranded sliver
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // relative to mean residual: prefer bins with less residual (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // new empty bin candidate: neutral baseline, slightly penalized so we prefer
    // existing bins unless they leave big dead space
    if bin_residual == bin_capacity {
        score += 15.0;
        // open a new bin if next item is huge and no open bin would chain well
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 60.0 * fit_ratio;
    }

    // Penalize large dead space quadratically, but only for existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
        // Reward bins whose residual is a "useful" size for future items.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 12.0;
        }
    } else {
        // New-bin candidate: baseline cost of opening a bin.
        score += 35.0;
        // Open fewer bins early when mean residual is high (bins still roomy).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * mean_residual * 0.6;
        // If many bins can already fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 8.0;
        // Late in stream, prefer consolidating: penalize new bins more.
        score += progress * 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: avoid leaving a residual that barely fails the next item
    // (wasted space that can't be used immediately).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins below the mean residual (denser bins) mildly.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for reusing bins as open-bin count grows.
    if !is_new_bin {
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream (t small): keep scores low for bins with moderate residuals (flexibility).
    // Late in the stream (t near 1): reward tight fits more aggressively (post_residual penalized quadratically).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Polynomial progress weights: w(t) = a + b*t + c*t^2 + d*t^3 (smooth, no piecewise constants)
    let w_tight = 1.5 + 2.0 * t + 3.0 * t * t + 2.5 * t * t * t;
    let w_flex = 1.2 - 0.8 * t + 0.4 * t * t - 0.2 * t * t * t;

    // Quadratic dead-space penalty coupled with progress
    score += w_tight * pr_norm * pr_norm * cap * 0.5;

    // Smooth reward for filling the bin well, stronger as stream advances
    let fill = 1.0 - pr_norm;
    score -= w_tight * fill * fill * fill * cap * 0.4;

    // Flexibility term: mildly favor bins whose residual stays near mean_residual early on
    let dev = (pr - mean_residual).abs() / cap;
    score += w_flex * dev * dev * cap * 0.6;

    // Lookahead coupling: smooth polynomial interaction between post_residual and next item size.
    // If the next item fits the post residual, reward (subtract); otherwise penalize quadratically.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap <= 0.0 {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= w_tight * fit_quality * fit_quality * nx * 0.35;
        } else {
            score += w_tight * (gap / cap) * (gap / cap) * cap * 0.5;
        }
    }

    // Last-chance bin: smooth urgency bonus scaled by progress polynomial
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * t + 8.0 * t * t;
    }

    // Crowd penalty: mildly discourage scattering across many bins, smoothed with progress
    let crowd = open_bins_count as f64;
    score += (crowd / (1.0 + crowd)) * (1.0 - t) * 2.0;

    // New-bin candidate: penalize opening a new bin, especially as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * t + 6.0 * t * t * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), small dead zones, and
    // "harmonic" residuals that are nice sums of common item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // classify residual into harmonic classes via integer division thresholds
        let class = pr / 10; // 0..10 classes of width 10
        let harmonic_bonus: f64 = match class {
            0 => 25.0,          // 1..9: nearly unusable dead space
            1 => 12.0,          // 10..19: fits only tiny items
            2 => 2.0,           // 20..29: marginal
            3 => -8.0,          // 30..39: decent
            4 => -12.0,         // 40..49: good
            5 => -15.0,         // 50..59: half-bin sweet spot
            6 => -13.0,         // 60..69
            7 => -9.0,          // 70..79
            8 => -4.0,          // 80..89
            _ => 3.0,           // 90+: nearly empty bin, wasteful placement
        };
        score += harmonic_bonus;

        // modulo texture: residuals divisible by 10/20 pair well with typical sizes
        if pr % 20 == 0 {
            score -= 6.0;
        } else if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.0;
        }
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 5.0; // next item won't fit here, dead end likely
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it unattractive unless all open bins are bad fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins relative to the fleet mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight penalty per open bin to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful are heavily penalized. Threshold: smallest item is 1, but a gap
    // below ~10 is nearly unusable; below ~5 it is pure waste.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongest reward.
        score -= 60.0;
    } else if post_residual < 5 {
        score += 25.0; // unusable sliver
    } else if post_residual < 10 {
        score += 12.0; // near-dead space
    } else {
        // Usable gap: mild reward proportional to how well the next item fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Reward filling large chunks of the bin (tight fit coupling).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize bins whose residual deviates far from the mean (keep fleet balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // compacting into existing bins and avoid opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 8.0 + pressure;
    } else {
        score -= 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (zero-waste) placement.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement chains perfectly -> heavy reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    }
    // Next item fits inside post-residual: partial chain reward,
    // scaled by how well it fills (tighter = better).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 200.0 * fill;
    }
    // Next item cannot use the post-residual: penalize large dead space
    // that nothing coming next can consume.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 0.5 * (post_residual as f64).min(next_item_size as f64);
    }

    // Relative tightness against mean residual across open bins:
    // prefer bins whose post-residual is well below the mean
    // (we are concentrating waste efficiently).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 20.0 * rel;
    }

    // Last-chance bin: if this is the ONLY bin that fits the item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize using a fresh empty bin when the item is small
    // (wasting a full bin on a small item is bad unless unavoidable).
    if bin_residual == bin_capacity {
        score += 120.0 + 1.5 * (item_size as f64);
        // But if no open bin fits, the new bin is the fallback;
        // fitting_bins_count==0 marks that case implicitly by comparison.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead can justify opening a fresh bin: if the next item
        // would combine with the current one into a near-full bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let combo_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if combo_fill > 0.9 {
                score -= 300.0 * combo_fill;
            }
        }
    }

    // Late in the stream, be greedier about closing bins tightly
    // (fewer chances remain to consolidate residual space).
    let progress = step_index as f64 / total_items as f64;
    score -= 30.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Mild penalty for leaving awkward residuals in the classic
    // "hard-to-fill" zone (just above half capacity).
    if pr > 50 && pr < 90 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (min size 1) can use well.
    if post_residual > 0 && post_residual < item_size {
        score += 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, competition sharpens preference for tight fits.
        score += 1.5 * (fitting_bins_count as f64).ln() * (1.0 - fit_ratio);
    }

    // Global state: many open bins with large mean residual -> consolidate, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there is slack capacity in the system.
        let slack = mean_residual * open_bins_count as f64;
        score += 30.0 + 0.3 * slack + 20.0 * (1.0 - progress);
        // But if nothing fits anywhere, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: slight reward when system is congested.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * progress;
        if item_size as f64 > mean_residual {
            score += 2.0; // item larger than average residual: this bin is precious
        }
    }

    // Mild time-horizon shaping: early on, be flexible; late, prefer compacting.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_coupling = norm_pr * (0.5 + 2.0 * progress * (1.0 - progress) * 2.0);

    // Penalize large dead space non-linearly
    let dead_space_penalty = norm_pr * norm_pr * 40.0;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight_fit_reward = -(1.0 - norm_pr).powi(3) * 20.0 * (0.5 + progress);

    // Lookahead: reward leaving space compatible with next item
    let lookahead_term = if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            -8.0 * (1.0 - ((pr - n) / cap).abs())
        } else {
            6.0 * (n - pr) / cap
        }
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only bin that fits
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Congestion: when many bins are open, prefer consolidation
    let congestion = (open_bins_count as f64).ln() * norm_pr * 5.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let balance = ((pr - mean_residual) / cap).powi(2) * 10.0;

    let score = pr + progress_coupling * 10.0 + dead_space_penalty + tight_fit_reward + lookahead_term + last_chance + congestion + balance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes are valuable.
    let pr = post_residual;
    let usable = |r: u32| -> f64 {
        if r == 0 { return -50.0; } // perfect fill: huge reward
        let mut v = 0.0;
        if r % 10 == 0 { v -= 6.0; }
        if r % 20 == 0 { v -= 4.0; }
        if r % 25 == 0 { v -= 3.0; }
        if r % 50 == 0 { v -= 5.0; }
        // small dead-space penalty for awkward slivers
        if r < 10 { v += 12.0; }
        else if r < 20 { v += 5.0; }
        v
    };
    score += usable(pr);

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            if next_item_size == pr {
                score -= 15.0; // perfect chain
            } else if pr - next_item_size < 10 {
                score -= 8.0; // near-perfect chain
            } else {
                score -= 3.0;
            }
        } else {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, reward tighter fits harder
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base penalty to discourage wasting bins
        let mut nb = 25.0;
        // if mean residual across open bins can't hold item, opening is fine
        if (mean_residual as u32) < item_size {
            nb -= 20.0;
        }
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * progress;
        // if many bins open, avoid spreading
        nb += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // perfect modulo alignment of item with capacity is fine in a new bin
        if item_size % 25 == 0 || item_size % 50 == 0 {
            nb -= 5.0;
        }
        score += nb;
    }

    // Mild penalty for very loose fits (large post_residual relative to mean)
    if pr as f64 > mean_residual * 1.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1, practically >=10 in classic streams)
    // can ever use are pure waste. Penalize small-but-nonzero post residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity (waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Dead-space danger: residual left behind is only useful if a future item fits it.
    // If the next item won't fit into the post residual, the gap is likely stranded.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            score += 25.0;
        } else if post_residual >= next_item_size {
            score -= 15.0; // the leftover can serve the lookahead item
        }
    }

    // Open-bins pressure: discourage scattering across many open bins; favor filling
    // existing bins more strongly as the count grows.
    score += 3.0 * open_bins_count as f64;

    // Mean residual coupling: when open bins are already loose on average,
    // prefer the bin that keeps residuals aligned (avoid extreme outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit would create severe dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 50.0;
    } else if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        // last chance but creates dead space: moderate penalty, new bin may be better
        score += 20.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it less
    // attractive than a decent fit in an open bin, but more attractive than a
    // dead-space-creating fit (handled above).
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening a bin is riskier (fewer chances to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next item still fits well
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: only care about current fit
        score -= 10.0;
    }

    // Reward tightness relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating dead space below the minimum item size (unusable residual)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins
        score = bin_capacity as f64 + 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // new bin leaves room for the (larger) next item: mild discount
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            // an existing bin is a last chance: make new bin less attractive
            score += 35.0;
        }
    }

    // Slight stream-progression pressure: later in the stream, consolidate more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty reduction for small residuals.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * 60.0;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post residual, reward heavily;
    // if post residual is too small for the next item, penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.35 * mean_residual.min(60.0);
    }

    // Penalize new-bin candidate when open bins with slack exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let slack_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 + 40.0 * slack_pressure + 25.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 120.0; // no open bin fits -> open new bin
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual < bin_capacity {
        score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Small bonus for exact or near-exact fills.
    if post_residual <= 3 && post_residual > 0 {
        score -= 30.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: penalize large residuals more as stream progresses
    score += 8.0 * progress * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits more strongly later in the stream
    score -= 6.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Dead-space penalty: residual too small for typical future items
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 3.0 * (1.0 - dead) * (norm_pr.max(0.01));

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Slight preference for consolidating into fewer bins early
    score -= 0.5 * (open_bins_count as f64).recip();

    // New-bin candidate: make empty bins mildly unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create dead-space classes.
    let class = post_residual % 10;
    // Penalize awkward residuals (1..9) more than clean multiples of 10.
    if class > 0 {
        let awkwardness = match class {
            1 => 12.0,
            2 => 9.0,
            3 => 7.0,
            4 => 6.0,
            5 => 4.0,
            6 => 6.0,
            7 => 7.0,
            8 => 9.0,
            _ => 12.0,
        };
        score += awkwardness;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits the resulting residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward bins where the next item leaves a class-aligned remainder.
        let next_left = post_residual - next_item_size;
        if next_left % 10 == 0 {
            score -= 15.0;
        }
        score -= (next_item_size as f64) * 0.1;
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize wasting a large residual.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // Prefer new bin only when residuals across open bins are small (poor fits everywhere)
        // or when the item is large and open bins are crowded.
        let crowded = (open_bins_count as f64) > 0.0 && mean_residual < (bin_capacity as f64) * 0.2;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if crowded && waste < 60.0 {
            score -= 10.0;
        }
        // Late in stream, prefer reusing bins: penalize new bins more.
        score += waste * (0.5 + 0.5 * progress);
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Small reward for filling more of the bin now.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: dead space that no item (min size 1) may ever use well.
            score += 60.0 * (11.0 - pr) / 10.0;
        } else if post_residual < 20 {
            // Marginal gap: only tiny items fit; partial penalty.
            score += 25.0 * (20.0 - pr) / 10.0;
        }
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly since it adds a bin).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize mildly.
        score += 10.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // filling it is good (it was likely to become dead space anyway).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 5.0 * (dev / bin_capacity as f64).min(1.0);
    }

    // New-bin candidate adjustment: an empty bin should only win when open bins
    // would create severe dead space. Give the empty bin a moderate base cost.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * (open_bins_count as f64).sqrt();
        // If no existing bin fits tightly, allow the new bin more readily late in stream.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: exact match of post_residual with next item size is perfect.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let rem2 = post_residual - next_item_size;
            // penalize leftover after hypothetically placing next item
            score += rem2 as f64 * 0.5;
            if rem2 <= 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item cannot follow here; dead space risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: any residual is waste
        score += 5.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(50.0) * 0.2;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // but allow new bin if it enables a perfect next-item fit
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Small residuals are hard to fill later: nonlinear penalty
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 25.0;
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 30.0 * (fitting_bins_count as f64).sqrt();
        }
        // Small items should almost never trigger a new bin.
        if item_size < 30 {
            score += 50.0;
        }
        // Late in the stream, avoid spawning bins that end nearly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 25.0;
        } else if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Next item could pair into a bin that fits current item too.
            score += 15.0;
        }
    } else {
        // Lookahead pairing: if next item exactly fills post_residual, big bonus.
        if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
            score -= 45.0;
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Next item can still use leftover space; mild reward.
            score -= 8.0;
        } else if next_item_size > 0 {
            // Next item won't fit here: dead-space risk proportional to gap.
            let gap = post_residual as f64 - (next_item_size.min(post_residual) as f64);
            score += gap * 0.15;
        }
    }

    // Prefer bins with residuals below the mean (compact bins first),
    // keeping high-residual bins flexible for future items.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Slight preference for fewer open bins overall (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    // Early stream: be slightly more exploratory with new bins.
    let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
    score -= early * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr as f64;

    // Smooth non-linear coupling: prefer small post_residual, weighted by progress
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Polynomial interaction between item fill fraction and progress
    let fill = norm_item;
    score -= 8.0 * fill * fill * (1.0 - fill) * (1.0 + progress);

    // Penalize post_residual that neither fits the lookahead item well nor is near zero
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 6.0 * gap * gap * (1.0 - progress);
        // Reward exact lookahead fit smoothly
        let fit_quality = 1.0 - (gap / (norm_next + 0.05)).min(1.0);
        score -= 5.0 * fit_quality * fit_quality;
    } else {
        // Last item: strongly prefer tight fits
        score += 15.0 * norm_pr * norm_pr;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 7.0 * scarcity * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins deviating from mean in a useful way
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev * (1.0 - progress) - 1.5 * dev * dev;

    // New-bin candidate: penalize mildly unless open bins are scarce or fit is tight
    let is_new = (bin_residual as u32 == bin_capacity) as f64;
    score += is_new * (10.0 + 8.0 * (1.0 - fill) - 5.0 * scarcity);

    // Mild penalty for opening many bins late
    score += is_new * 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (modulo arithmetic) ---
    // Residuals divisible by common item granularities are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // perfectly aligned residual: highly reusable
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 2 == 0 {
            score -= 1.0;
        } else {
            score += 2.0; // odd residual: awkward for even-sized items
        }
        // Dead-zone penalty: tiny unusable slivers
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    } else {
        score -= 12.0; // perfect fit: strong reward
    }

    // --- Harmonic coupling with the lookahead item ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly or with a nice remainder
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional waste
            score += (next_item_size - pr) as f64 * 0.3;
        }
        // Reward exact two-item closure: item + next fills bin exactly
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // --- Integer-division threshold classes on post_residual ---
    let class = pr / 10; // 0..=10 harmonic band
    score += match class {
        0 => 6.0,           // 0..9: nearly dead
        1 => 0.0,           // 10..19: marginal
        2 | 3 => -1.5,      // 20..39: useful for small items
        4 | 5 => -3.0,      // 40..59: mid-range useful
        6..=8 => -4.5,      // 60..89: very useful
        _ => -5.0,          // 90+: almost fresh
    };

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper late in stream or when
        // open bins are crowded, costlier when bins are slack.
        score = 25.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 4.0;
        score += (open_bins_count as f64).min(10.0) * 0.5;
        if mean_residual > item_size as f64 * 1.5 {
            score += 6.0; // open bins have plenty of room: discourage new bin
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 5.0; // nothing open will hold the next item anyway
        }
        // A fresh bin gives a perfect harmonic residual of 100 (mod 10 == 0)
        score -= 3.0;
    }

    // --- Mean-residual harmonization: prefer bins near the mean (balance) ---
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no item (min size 10) can use are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable gap -> heavy penalty
    } else if post_residual < 20 {
        // small gaps are risky: only large items (rare) could use them
        score += 12.0;
    } else if post_residual == 0 {
        // perfect fit reward
        score -= 80.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0;
        } else if post_residual == next_item_size {
            score -= 40.0; // lookahead perfect fit
        }
    }

    // Open-bin pressure: discourage spreading across many bins when fit is easy
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 1.5;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean (better consolidation)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: opening a bin is only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (minimal dead space)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 200.0 - slack * 10.0;
            } else {
                score -= (50.0 / slack).min(50.0);
            }
        } else {
            // next item cannot fit here; penalize proportional to mismatch
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer tight fits relative to residual
    score -= fit_ratio * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
        score += 120.0 - 60.0 * poor_fit;
        // Early in stream, opening bins is cheap; later, discourage
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 70.0;
        }
    }

    // Mild penalty proportional to wasted fraction of capacity
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (tighter residual = better).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: penalize if the next item CANNOT fit into the post residual
    // (we'd strand the bin with unusable dead space), reward if it CAN fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Bonus for perfect two-item packing.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable fragments (< 10 cannot hold any item).
    if post_residual < 10 {
        score += 8.0;
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack elsewhere; slightly prefer opening fresh bins over
    // fragmenting, and vice versa when mean residual is low.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late in the stream, favor closing bins tightly (waste matters more).
    if progress > 0.8 {
        score += post_residual as f64 * 0.3 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (many fitting bins means reuse is better).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 12.0; // must open a new bin
        } else {
            // Cost of a fresh bin grows with number of open bins and progress.
            score += 10.0 + open_bins_count as f64 * 0.5 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 12.0 * poly * (0.5 + progress);

    // Penalize large post-residual late in the stream (dead space)
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits via smooth decay of item fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.35 * gap;
        score -= 6.0 * (-gap / 15.0) * (-gap / 15.0);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Slight preference to spread load when many bins open
    score += 0.02 * (open_bins_count as f64 - mean_residual / 10.0);

    // New-bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 4.0 + 20.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity-fraction buckets.
    // Small post-residuals (tight fits) are excellent; mid-range residuals are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class index via harmonic division: 0:(0,1/8] 1:(1/8,1/4] 2:(1/4,1/2] 3:(1/2,1]
    let class = if frac <= 0.125 { 0 } else if frac <= 0.25 { 1 } else if frac <= 0.5 { 2 } else { 3 };
    score -= match class { 0 => 30.0, 1 => 12.0, 2 => 0.0, _ => 0.0 };

    // Harmonic penalty on mid-class residuals: proportional to wasted fraction squared
    score += (frac * frac) * 20.0;

    // Lookahead coupling: does next item fit into the post-residual?
    let ni = next_item_size as f64;
    if ni > 0.0 {
        if pr >= ni {
            // Next item can also go here: reward proportional to how well it fills
            let fill_after = 1.0 - (pr - ni) / cap;
            score -= 10.0 + 15.0 * fill_after;
        } else {
            // Next item won't fit: post-residual becomes dead space for the lookahead
            // Penalize more if the dead residual is in the useless mid-range
            let dead = pr / cap;
            score += 8.0 + 20.0 * dead * (1.0 - dead);
        }
    } else {
        // Last item: any residual is fine, strongly favor tightest fit
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let penalty = if ni > 0.0 {
            // Opening a bin whose residual can host next item is decent
            if (cap - ni) >= item_size as f64 { 5.0 } else { 12.0 }
        } else { 10.0 };
        // Base cost of a new bin, softened when open bins are crowded (low mean residual)
        score = 55.0 + penalty - (mean_residual / cap) * 40.0;
        // Late in stream, prefer reusing bins
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    // Slight preference to keep bins balanced: penalize bins far below mean residual
    let dev = mean_residual - pr;
    if dev > 0.0 { score += dev * 0.05; }

    // Integer-division threshold nudge: post_residual exactly divisible by common
    // class sizes (10, 20, 25, 50) is more reusable
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
