    // Encourage filling tight bins when item nearly matches residual.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 20.0 * tightness * tightness;

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one;
    // the new-bin candidate (residual == capacity) gets a rising penalty.
