        }
    } else {
        // Prefer bins with below-average residual (tighter bins) for small items.
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item would fit the post residual exactly, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large post_residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size as u32 <= post_residual {
            let fill = nxt / pr.max(1.0);
            score -= 25.0 * fill * fill; // next item fits well
        } else {
            // next item won't fit here; penalize wasted residual
            score += 8.0 + 0.15 * (nxt - pr);
        }
    } else {
        // last item: minimize final residual
        score -= 40.0;
    }

    // Compare post_residual against mean residual: avoid leaving more than average.
    let dev = pr - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let tight_exists = next_item_size > 0 && post_residual == bin_residual; // always true for new bin; use fit count
        let _ = tight_exists;
        if fitting_bins_count > 1 {
            score += 70.0; // other bins exist; discourage opening new one
        } else {
            score += 20.0; // mild penalty; only open if open bins fit poorly
        }
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins among many options.
    score -= 0.1 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize leaving small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * next_fit;
        if post_residual == next_item_size {
            score -= 80.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting a versatile bin.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 25.0 * fit_ratio;
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer consolidating into
    // already-open bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score -= 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // New-bin candidate: only attractive when existing bins would leave big dead space
    // or when the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (mean_residual / bin_capacity as f64);
        // Open a new bin if placing here would waste a lot and open bins are mostly full.
        score += 90.0 - 70.0 * pressure - 0.3 * waste_elsewhere;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with a non-linear polynomial shaping in progress.
    // Early on, prefer tight fits strongly; later, tolerate residual more.
    let mut score = pr;

    // Smooth coupling: residual^2 scaled by progress creates a non-linear
    // interaction that penalizes large residuals more as stream advances
    // (consolidation pressure grows over time).
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * progress);

    // Reward filling the bin well: negative cubic term in utilization.
    let util = 1.0 - norm_pr;
    score -= cap * util * util * util * (0.3 + 0.7 * progress);

    // Perfect fit bonus (smooth, no hard threshold): zero post-residual.
    score -= if pr == 0.0 { 8.0 } else { 0.0 };

    // Lookahead: if the next item would fit exactly into the post residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - gap / cap).max(0.0) * (pr >= next_item_size as f64) as u8 as f64;
    }

    // Last-chance bin: strong penalty for opening new bins when only this
    // bin fits, unless the fit is poor.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: prefer it only when it beats typical residuals;
    // penalize slightly so consolidation is preferred by default.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress);
    }

    // Dead-space penalty relative to mean residual: bins whose post residual
    // deviates far above the mean waste capacity.
    score += 0.5 * ((pr - mean_residual) / cap).max(0.0) * cap * (0.5 + progress);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.2 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition [0,C] into coarse bands
    // using integer division. Classes near 0 are excellent (tight fit),
    // classes near C are wasteful.
    let class_width = bin_capacity / 5; // 20 units per class
    let post_class = post_residual / class_width;
    let next_class = next_item_size / class_width;

    // Reward tight fits: deeper classes (small residual) get bigger bonuses.
    let class_bonus: [f64; 5] = [40.0, 25.0, 12.0, 5.0, 0.0];
    let idx = (post_class as usize).min(4);
    score -= class_bonus[idx];

    // Exact-fit harmonic bonus: post_residual divisible into nice chunks
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Coupling: if the lookahead item can exactly consume this bin's post
    // residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward scaled by how much it leaves again
        let next_post = post_residual - next_item_size;
        let next_idx = (next_post / class_width) as usize;
        score -= [6.0, 4.0, 2.0, 1.0, 0.0][next_idx.min(4)];
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space proportionally
        score += (post_residual as f64) * 0.3;
    }

    // Harmonic-class mismatch penalty: leaving a residual whose class rarely
    // matches typical item classes (small residuals are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // awkward sliver
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing existing bins unless this bin is a very poor fit
        // (large post_residual means we'd waste the new bin anyway).
        score += 35.0;
        // But if the item is huge relative to mean residual space, new bin ok
        if (item_size as f64) > mean_residual * 1.5 && open_bins_count > 0 {
            score -= 45.0;
        }
        // Late in the stream, keep bins consolidated
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure against proliferating many open bins with big residuals
    if open_bins_count > 3 && post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 range,
    // but small gaps < 10 are nearly unusable) are heavily penalized.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 30 {
        score += 30.0;
    }

    // Non-linear penalty: squared residual amplifies large wasted space moderately,
    // while exact fits (post_residual == 0) get a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Reward tight fits relative to the item itself.
    score += item_size as f64 * 0.05;

    // Open-bin pressure: when many bins are open, prefer using existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 50.0 + 8.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits (small miss), slight penalty for leaving a near-miss gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (consolidating space into fewer bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: later in the stream, be more conservative about
    // leaving small residuals (less future to recover them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item also fits here: strong reward, scaled by how snugly
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * next_fit;
        } else {
            // next item won't fit in leftover: penalize dead space that strands it
            let leftover = (post_residual as i64 - next_item_size as i64) as f64;
            score += 0.15 * (post_residual as f64 - leftover.abs().min(post_residual as f64));
            score += 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 10.0; // don't open a new bin if the pair could go together anyway elsewhere
        }
    }

    // Slight preference to fill bins more as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further residual
            let next_leftover = post_residual - next_item_size;
            score -= 15.0 - 0.3 * next_leftover as f64;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidating into fuller bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // Global residual context: bin far below mean residual is a poor target late in stream
    score += 0.05 * progress * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        // opening a new bin is cheap early, expensive late / when many bins open
        score = 40.0 + 30.0 * progress + 4.0 * (open_bins_count as f64) + 10.0 * scarcity.min(5.0);
        // but if item is large, a fresh bin is natural
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual, with a non-linear (quadratic) penalty
    // that grows super-linearly as leftover space increases.
    let mut score = pr + (pr * pr) / cap;

    // Smooth coupling with stream progress: late in the stream, tighten bins more
    // aggressively (waste matters more), early on be more tolerant.
    let tightness = 0.5 + 1.5 * progress;
    score *= tightness;

    // Reward good fits: interaction between fill ratio and item size.
    let fill = 1.0 - pr / cap;
    score -= 8.0 * fill * (it / cap) * (1.0 + progress);

    // Penalize bins whose residual is far above the mean (hoarding space),
    // smoothly via squared deviation.
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if the next item could exactly use the post_residual,
    // reward leaving this bin in that state.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if gap < 1.0 {
            score -= 12.0;
        } else {
            // smooth proximity reward for near-perfect next-item fit
            score -= 6.0 * (-gap / 20.0);
        }
    }

    // New-bin candidate handling: brand-new empty bin (bin_residual == bin_capacity).
    // Make it mildly unattractive so existing bins with decent fits win,
    // but attractive when existing fits are poor (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Penalize opening new bins more as stream progresses and bins exist.
        score = cap * (1.2 + 0.8 * progress) - (pr * pr) / cap;
        if open_bins_count > 0 {
            score += 5.0 + 10.0 * progress;
        } else {
            score -= 20.0; // must open the first bin
        }
        // If nothing fits well (this call only happens for the new bin when needed),
        // the base comparison with open bins' scores decides.
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are more reusable
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, ideal
    } else {
        let class = pr % 10;
        score += match class {
            0 => -12.0,           // round residual, highly reusable
            1 | 9 => 6.0,          // nearly-round slivers
            2 | 8 => 2.0,
            5 => 0.0,              // half-class
            _ => 4.0,              // awkward remainders
        } as f64;
    }

    // Integer-division thresholds on post_residual relative to typical item sizes
    if pr < 10 {
        score += 25.0; // dead space: below minimum item size
    } else if pr < 20 {
        score += 8.0;
    } else if pr >= 50 {
        score -= 5.0; // roomy residual still useful
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && next_item_size <= pr + 10 {
        score += 3.0; // near-miss, slight penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize spreading across many open bins; encourage filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // Prefer bins with residual below mean (fill tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate handling: only attractive when item is large or no good fits
    if bin_residual == bin_capacity {
        let big = item_size as f64 > 0.6 * bin_capacity as f64;
        if big || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            score += 18.0 + progress * 10.0;
        }
    }

    // Small harmonic bonus for item sizes sharing factors with residual
    if pr > 0 && item_size > 0 && pr % gcdish(item_size, pr % item_size.max(1)) == 0 && item_size <= pr {
        score -= 2.0;
    }

    score
}

// tiny inline gcd helper (no external deps)
fn gcdish(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcdish(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = residual too small to ever fit a future item (min size 1..100 unknown,
    // so treat gaps below a "useful threshold" as risky, scaled non-linearly).
    let useful_threshold = 20.0; // gaps below this are likely dead space
    if (post_residual as f64) < useful_threshold {
        score += (useful_threshold - post_residual as f64) * 2.5; // steep penalty for tiny gaps
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0; // near-perfect fit still strongly rewarded
    }

    // Open-bin pressure: favor filling existing bins when many are open,
    // penalize opening new bins when the pool is already large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += bin_pressure * 4.0;

    // New-bin candidate: penalize so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 25.0 + bin_pressure * 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post_residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // gap won't fit next item; mild penalty proportional to wasted potential
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
    }

    // Prefer bins tighter than the mean residual (compact placement).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual == next_item_size -> perfect fill
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual smaller than next item but still usable later: mild reward
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 1 {
        // dead space relative to lookahead item
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Post-residual larger than next item: leaves room for lookahead too
    if next_item_size > 0 && post_residual > next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.1;
    }

    // Compare against mean residual: prefer bins whose post residual is near/below mean
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin opening when the item fits an existing bin reasonably well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // only attractive if the best fit would be terrible (large post residual waste)
        score += 150.0 - post_residual as f64;
    }

    // Early stream: keep bins tight; late stream: consolidate
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional dead-space penalty: large post_residual is wasted capacity.
    let frac_dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac_dead * frac_dead;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly next item fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a large unusable gap
            score += 15.0 * frac_dead;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer the tightest fit relative to other bins (mean residual comparison).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 6.0;
    }

    // Time horizon: early in stream, be conservative about opening new bins
    // (penalize new bins); late in stream, allow opening bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that decays with progress.
        score += 20.0 * (1.0 - progress);
        // Opening a new bin is attractive if the item is huge relative to capacity.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open already, avoid spreading too thin.
        score += 2.0 * open_bins_count as f64;
    } else if post_residual == 0 {
        // Perfect fill: massive reward.
        score -= 100.0;
    }

    // Small coupling: reward using bins that are already quite full.
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used_frac * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core: minimize post residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr + 0.8 * (pr / cap) * pr;

    // Tight-fit reward: non-linear in fill ratio
    let fill = 1.0 - pr / cap;
    score -= 6.0 * fill * fill * fill;

    // Dead-space penalty: residuals too small to ever be useful (smooth bump)
    let useless = (-pr / 10.0).exp(); // near 1 when post_residual ~ 0
    score += 4.0 * useless * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalty proportional to number of competing fitting bins (prefer scarce fits less)
    score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);

    // Lookahead: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain_fit = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 3.0 * chain_fit * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by progress
        score += 1.5 * progress;
    }

    // Stream progress coupling: later in stream, favor consolidating into open bins
    score -= 4.0 * progress * fill;

    // New-bin candidate handling: discourage opening new bins unless current fits are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 6.0 * progress;
        // allow new bin if mean residual of open bins is very low (all nearly full)
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0) * (mean_residual / cap).powi(4);
        // if many bins fit, definitely don't open new one
        score += 2.0 * fitting_bins_count as f64;
    } else {
        // reward using existing bins, more so when many are open (consolidation)
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: if this bin's post residual deviates favorably from mean, reward
    let dev = mean_residual - pr;
    score += 0.05 * dev * dev * 0.0 - 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> overwhelming priority
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    // Small leftovers (<=10) are "dead" only if next item can't use them; reward small usable gaps.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits (post_residual small) more aggressively than linear
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= eighth {
        score -= 5.0;
    }

    // Penalize leftovers in "awkward" harmonic classes: residues that few item sizes can fill.
    // Modulo arithmetic on post_residual: leftovers ≡ 0 mod 10 are highly reusable (common sizes).
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // Non-round leftovers are harder to fill -> penalty grows with distance to next multiple of 5
        score += (5 - (pr % 5)) as f64 * 2.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: this placement chains with the next item
            score -= 10.0 + (next_item_size as f64) * 0.1;
            // Bonus if next item exactly fills the remainder (perfect chaining)
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            // Next item won't use this gap: penalize large wasted residues
            let waste = post_residual as f64 - 0.0;
            score += waste * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 30 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins with decent fits; only favor new bin when all fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scaled by how many bins are already open
        score += 20.0 + open_bins_count as f64 * 0.5;
        // If the new bin can chain perfectly with the next item, make it competitive
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: if mean residual is high, bins are loose; be pickier
    // (penalize mediocre fits more) to preserve tight-packing options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 30.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Late in stream, avoid opening new bins; squeeze into existing ones.
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // another item (assuming min item size 1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual as i32) as f64;
    }

    // Reward tight fits (small but usable leftovers are okay).
    score -= 0.8 * (bin_residual as f64 - post_residual as f64);

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones
    // as the number of open bins grows.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead synergy: if the next item fits the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if post residual is a near-miss trap for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or the fit here would be poor.
    if bin_residual == bin_capacity {
        score += 15.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 40.0; // discourage abandoning existing fitting bins
        } else {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Mild progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0).powi(6);
        // Perfect chain: this bin will be exactly filled next step.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is too small for the next item (dead space risk)
        // but only mildly; the next step can open a new bin.
        if next_item_size > post_residual {
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-empty dedicated bin's flexibility for tiny items.
    if item_size < 20 && post_residual > 60 {
        score += 6.0;
    }

    // Early stream: be slightly more conservative about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Never prefer a new bin over a reasonable existing fit unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no strong lookahead match exists in existing bins, opening fresh is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: how much of the bin's residual is consumed.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };

    // Reward tight fits more strongly as the stream progresses (conserve late-game).
    score -= 40.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small dead space is nearly a perfect fit; mildly reward.
        score -= 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            if next_waste < 10 {
                score -= 20.0 * (1.0 - next_waste as f64 / 10.0);
            } else {
                // Penalize leaving space that the next item can only poorly use.
                score += 0.15 * next_waste as f64;
            }
        } else {
            // Next item won't fit here regardless; post_residual becomes dead space.
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fit_ratio;
    }

    // Penalize placements into bins whose residual is far above the mean when the
    // fit is loose (keeps large residuals available for large future items).
    let loose_penalty = (mean_residual - bin_residual as f64).abs();
    score += 0.10 * loose_penalty * (1.0 - fit_ratio);

    // New-bin candidate handling: empty bin gets a baseline cost that grows with
    // the number of open bins and shrinks if the item is large (big items are
    // fine in fresh bins, small items should fill existing space).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score = 35.0 + 4.0 * openness - 0.3 * item_size as f64;
        // Late in the stream, opening bins is cheap since remaining items are few.
        score *= 1.0 - 0.4 * progress;
        // If no open bin fits well (item larger than mean residual), new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild global pressure: with many open bins, favor consolidation into existing bins.
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate loose fits (favor consolidation); late, demand tight packing.
    let tightness = 1.0 + 2.5 * progress * progress;
    score *= tightness;

    // Reward near-exact fits: quadratic bonus for small post_residual.
    let fit_frac = pr / cap;
    score -= 30.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Penalize residuals that are too small to ever be useful (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64 / cap;
        } else {
            // Reward residuals that can accommodate the lookahead item.
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage closing bins out).
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // in the direction of tighter packing.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev - 4.0 * dev;

    // New-bin candidate: make it attractive only when no good fit exists,
    // i.e. when this (empty) bin's post_residual is maximal but current fits are poor.
    if bin_residual == bin_capacity {
        score = cap + 10.0 * progress + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residue modulo capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fits are golden: post_residual in {0} or small residues divisible by common small sizes
    if post_residual == 0 {
        score -= 60.0; // exact fill
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect, dead space negligible
    } else if post_residual % 10 == 0 {
        // post residual is a harmonic multiple of 10 -> likely reusable by future items
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        // awkward residue classes: penalize non-decomposable dead space
        score += 8.0;
    }

    // Integer-division thresholds: classify residual into usable bands
    let band = post_residual / 10; // 0..10
    match band {
        0 => score -= 10.0,          // tiny leftover, fine
        1 => score -= 4.0,           // 10-19 leftover
        2 | 3 => score -= 2.0,       // 20-39: medium items fit
        4 | 5 => score += 0.0,       // neutral
        6 | 7 => score += 3.0,       // large slack: maybe wasteful bin choice
        _ => score += 5.0,           // huge slack: this bin was too empty
    }

    // Coupling with next item: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: strong reward, scaled by how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 - snug * 0.15;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over * 0.08).min(10.0);
        }
        // harmonic class match: next item and post residual share residue class mod 10
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // last item: just close bins tightly
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress and crowding
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 + 25.0 * progress;
        if open_bins_count == 0 {
            open_cost = -100.0; // must open
        }
        // if many open bins with big mean residual, opening new is less attractive
        open_cost += (mean_residual - post) * 0.1;
        score += open_cost;
    } else {
        // existing bin: reward keeping bins tight relative to mean residual
        score += (mean_residual - post) * 0.05;
    }

    // mild tie-break: prefer fuller bins (smaller residual) as stream progresses
    score += (bin_residual as f64 / cap) * (2.0 + 3.0 * (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) can use it well;
    // treat gaps below a tight threshold as wasted capacity.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (tighter than average) to consolidate space.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones; when few bins are open, opening is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + pressure;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would exactly fill post-residual, extra reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin costs more as more bins
    // are open; but a fresh bin is attractive when all fits would be terrible.
    if bin_residual == bin_capacity {
        score = 100.0 - pressure * 2.0;
        // If the new bin would leave a large residual with a small item,
        // it's a wasteful open; penalize slightly more.
        if (post_residual as f64) > 70.0 {
            score += 10.0;
        }
        // If this bin is the last chance, opening new is bad.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about
    // dead space (less room to recover from waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild non-linear bonus
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).sqrt() * 10.0;

    if next_item_size > 0 {
        // 2-step lookahead: does the residual after this placement fit the next item?
        let next_fits = post_residual >= next_item_size;
        if next_fits {
            // Slack after serving the next item too
            let slack_after_next = post_residual - next_item_size;
            // Reward exact chain fit strongly
            if slack_after_next == 0 {
                score -= 60.0;
            } else {
                // Reward small slack after the chain
                score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's residual: penalize proportionally
            let unusable = next_item_size - post_residual;
            score += 0.5 * unusable as f64;
        }

        // If next item fits EXACTLY into current residual (item + next == residual),
        // that's a perfect two-item chain: big reward.
        if item_size + next_item_size == bin_residual {
            score -= 45.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual of open bins: placing into a bin whose
    // residual is above mean helps rebalance; below mean creates fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit; make the empty bin moderately expensive so
    // it wins only when residuals are large/fragmented.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is less attractive (fewer future items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If next item is small, a fresh bin wastes capacity
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 15.0;
        }
    }

    // Slight preference to fill bins that are already mostly full (compactness)
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness of the fit: reward near-perfect fills strongly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 0.9 * (post_residual as f64);
    }

    // Lookahead synergy: bonus if the next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size as u32) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: open a fresh bin only when the fit is poor or
    // existing bins are nearly full anyway.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / cap;
        score += 14.0;                 // base reluctance to open new bins
        score += 30.0 * waste * waste; // very reluctant when item is tiny
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;       // late in stream, fresh bins pay off
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;              // pairing big item with next big item
        }
    }

    // Prefer spreading load when open bins are congested on average.
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Mild penalty for proliferating bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.4 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small relative to capacity.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - norm_post).powi(3) * 30.0;

    // Non-linear coupling of fit quality with stream progress:
    // late in the stream, tighten bins even more aggressively.
    score -= progress * (1.0 - norm_post).powi(2) * 25.0;

    // Penalize large leftover dead space with a quadratic term.
    score += norm_post * norm_post * 20.0;

    // Penalize bins whose residual is far from the mean (avoid fragmenting outliers),
    // with a smooth cubic coupling.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev.abs().powi(3) * 15.0;

    // Last-chance bonus: strongly favor the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward placements that leave room for the next item; penalize when they don't.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            score -= 10.0 * (1.0 - (post_residual as f64 - n) / bin_capacity as f64);
        } else {
            score += 8.0 + 4.0 * progress;
        }
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        score = 60.0 + norm_post * 0.0 + 10.0 * progress - 5.0 * (congestion.ln() + 1.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is the only option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands (dead space vs. reusable space).
    let pr = post_residual as f64;
    let quarter = cap * 0.25;
    let half = cap * 0.5;

    // Reward placements leaving residuals in "harmonic" reusable classes:
    // residuals near 0 are perfect fills; residuals that still fit common
    // item sizes (10..=50) are valuable; mid-band dead space is penalized.
    if pr == 0.0 {
        score -= 60.0; // perfect fill
    } else if pr < quarter {
        // small leftover: mildly good, but penalize by how close to dead zone
        score -= 10.0 * (1.0 - pr / quarter);
    } else if pr < half {
        // dead zone: leftover too big to waste, too small to be flexible
        score += 12.0;
    } else {
        // large leftover: reusable, reward proportionally
        score -= 6.0 * ((pr - half) / half);
    }

    // Integer-division harmonic class: post_residual mod 10 — residuals that
    // are multiples of 10 align with typical item granularity.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 4.0;
    } else {
        score += rem10 as f64 * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: value depends on leftover after next placement
            let after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - after_next / cap);
        } else {
            // next item won't fit here: slight penalty scaled by overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual or dead zone) or when the
    // stream is early and we have few bins.
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a perfect fit, better than
        // a dead-zone fit.
        score = cap * 0.35 + 12.0;
        if next_item_size > 0 {
            // a fresh bin can always take the next item
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress; // later in stream: prefer reusing open bins
        // if mean residual across open bins is large, opening new bins wastes
        // potential; penalize new bin accordingly.
        score += (mean_residual / cap).min(1.5) * 8.0;
    }

    // Mild tie-breaker: prefer bins with tighter residuals among equals.
    score += (bin_residual as f64 / cap) * 2.0;

    // Stream-phase modulation: early on, be greedy about consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure bonus
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // residual remains useful for next item
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.5 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far above mean residual wastes big space.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early in stream or when item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 40.0 * progress; // opening new bins gets worse as stream matures
        if item_size >= 70 {
            score -= 35.0; // big items are fine in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward exact or near-exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain (next item exactly fills the remainder) is heavily rewarded.
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress;
        } else {
            // Penalize gap between leftover and next item proportionally.
            score += gap * 0.35;
            // If next item cannot fit in the leftover, penalize dead space harder.
            if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }
    } else {
        // Last item: strongly prefer zero leftover.
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce space;
    // using them for a loose fit wastes them. Favor bins with residual near/above mean
    // when the fit is loose, but tight fits override this.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 0.7 {
            // Scarce small-residual bin: only attractive if fit is very tight.
            if post_residual as f64 > 0.35 * res {
                score += 12.0 * (0.7 - rel);
            } else {
                score -= 8.0 * (0.7 - rel);
            }
        } else if rel > 1.4 {
            // Roomy bin: mild penalty to avoid spreading items thinly.
            score += 3.0 * (rel - 1.4).min(2.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = post_residual as f64 / res.max(1.0);
        if tightness < 0.5 {
            score -= 25.0 * (1.0 - tightness);
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (post_residual small relative to capacity) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // Cost of a fresh bin is amortized: cheaper late in the stream is irrelevant,
        // but opening always costs ~a full bin of potential.
        score = bin_capacity as f64 * 0.85 + 15.0;
        // If the item fits poorly everywhere (post_residual large), opening looks better.
        let worst_fit = post_residual as f64 / bin_capacity as f64;
        if worst_fit > 0.6 {
            score -= 30.0 * (worst_fit - 0.6);
        }
        // Early stream with few bins: opening is fine.
        if progress < 0.3 && open_f < 4.0 {
            score -= 10.0;
        }
        // If next item is huge and would need a fresh bin anyway, opening now is good.
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: more open bins -> prefer reusing existing ones.
    score += open_bins_count as f64 * 0.15;

    // Small tie-breaker favoring fuller bins (smaller residual).
    score += res * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, prefer tightening existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space quadratically, scaled by capacity.
        let waste = (post_residual as f64 / bin_capacity as f64).powi(2) * 200.0;
        score += waste;

        // Lookahead: reward bins whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0 + 40.0 * progress;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Leftover too small for next item: mild penalty unless near-perfect fit.
            if post_residual > 0 && post_residual < 10 {
                score += 25.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Crowding effect: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 8.0;

    // Compare against mean residual: bins with more room than average are
    // better targets; tighter-than-average bins should be preserved.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= diff * 0.5;
    }

    // New-bin candidate: attractive early or when item barely fits nothing well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let _ = poor_fit;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = (item_size as f64 / bin_capacity as f64) > 0.8;
        let bonus = 120.0 * (1.0 - progress) + 200.0 * scarcity + if tight { 90.0 } else { 0.0 };
        score += 20.0 - bonus;
    }

    // Slight preference for bins that leave multiples of common small sizes.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post_residual, but with non-linear (quadratic) shrinkage
    // so small residuals are relatively cheap (good fits) vs medium ones.
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Smooth interaction: residual waste matters more as stream progresses.
    score *= 1.0 + 0.8 * progress * (1.0 - pr_norm);

    // Reward tight fits smoothly (non-linear decay of reward with residual).
    let tight = (-pr_norm * 6.0).exp();
    score -= 12.0 * tight;

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: bonus if next item fits the post-residual (smooth margin term).
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let margin = ((pr - next_item_size as f64) / cap).abs();
        score -= 8.0 * fits_next * (-margin * 4.0).exp();
    }

    // Slight preference to fill bins with larger mean residual (smooth coupling).
    score += 0.05 * (mean_residual - pr).abs();

    // Mild penalty for many open bins, growing smoothly with progress.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Residuals divisible by 10 pair well with typical item sizes (multiples of 10),
    // so reward them; odd/awkward classes get penalized.
    let r = post_residual;
    let r_mod10 = (r % 10) as f64;
    let r_mod5 = (r % 5) as f64;
    score -= 6.0 * (10.0 - r_mod10) / 10.0 * (r as f64 / bin_capacity as f64);
    if r_mod5 == 0.0 { score -= 4.0; }
    if r % 20 == 0 { score -= 3.0; }

    // Integer-division threshold: post_residual bucketed by what item classes fit.
    // Small dead space (<10) is nearly useless -> penalize heavily.
    if r < 10 {
        score += 25.0;
    } else if r < 20 {
        score += 8.0;
    } else if r < 35 {
        score += 2.0;
    } else if r >= 50 {
        score -= 5.0; // large residual keeps flexibility
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // this is a perfect harmonic pair -> strong reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let next_mod10 = (next_item_size % 10) as f64;
            // same harmonic class (both multiples of 10 or same remainder) pairs well
            if next_mod10 == r_mod10 {
                score -= 6.0;
            }
            score -= (r - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; residual becomes frozen until stream ends
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a good (tight or harmonic) fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // early in stream, keeping flexibility is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if many bins already open, discourage proliferation
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Tight fits are excellent regardless of class.
    if r == 0 {
        score -= 30.0;
    }

    // Slight preference toward bins whose residual is below the mean
    // (consolidating space) unless that creates tiny dead space.
    if (bin_residual as f64) < mean_residual && r >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (0 < post_residual < min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small residual that likely can't serve future items either
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    score += 3.0 * open_bins_count as f64;
    score += 0.5 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    // Lookahead: if next item fits the post_residual, reward leaving it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Stream progression: late in stream, be more conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus when post residual is at least the next item size (usable chain)
        if post_residual >= next_item_size {
            score -= 15.0;
        }
        // Penalize post residual slightly larger than next item (dead sliver after next placement)
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 20.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 25.0;
    }

    // Compare against mean residual: prefer bins that reduce dispersion
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        score += 10.0 * (rel - 1.0);
        score -= 8.0 / (1.0 + (rel - 1.0).abs());
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when other bins fit reasonably
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size >= 50 {
            score += 10.0; // big items: keep new-bin option mildly attractive
        } else {
            score += 30.0;
        }
    }

    // Early stream: be slightly greedy with tight fits; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Prefer fuller bins overall
    score -= 0.2 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    if tightness < 0.10 {
        score -= 12.0;
    } else if tightness < 0.25 {
        score -= 5.0;
    }

    // Penalize leaving residuals that no typical next item can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny dead space is bad
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 8.0;
        } else {
            score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit in the post_residual, mild penalty for wasting space now.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open and mean residual is still large (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0
            + 2.0 * (open_bins_count as f64).ln().max(0.0)
            + 10.0 * (mean_residual / bin_capacity as f64)
            + 5.0 * (1.0 - progress);
    } else {
        // Prefer fuller bins: reward low residual relative to mean.
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Slight preference for bins with residual close to item size (best-fit bias).
    score += 0.1 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling between post_residual and stream progress
    let poly = (norm_pr * norm_pr) * (0.5 + 1.5 * progress * (1.0 - progress) * 4.0);
    score += poly * cap;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item * (10.0 + 20.0 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can fit the next item (smooth sigmoid-like)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fits = (norm_pr - nxt).max(0.0);
        let coupling = fits * (1.0 - fits) * 4.0; // smooth bump peaking at exact fit
        score -= coupling * 8.0 * (0.5 + progress);
        // Penalize residual that is just barely too small for next item
        let miss = (nxt - norm_pr).max(0.0);
        score += miss * miss * cap * 0.5 * progress;
    }

    // Mild penalty for spreading across too many bins late in the stream
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Favor the new-bin candidate only when existing residuals are badly fragmented
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 5.0 - 10.0 * fragmentation * (1.0 - progress);
        score += 20.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space classes (mod 10) are penalized
    // more when the leftover residue is small and unusable.
    let r = post_residual % 10;
    let harmonic = (post_residual / 10) as f64;
    score += (r as f64) * 1.5; // small residues (<10) are nearly dead space

    // Reward post_residuals that form useful harmonic classes: multiples of 10,
    // especially those matching common item-size classes (10,20,...,80).
    if r == 0 && post_residual > 0 {
        score -= 12.0 * harmonic.sqrt();
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits, but how cleanly? penalize leftover after next item.
            let next_left = post_residual - next_item_size;
            score -= 40.0 - (next_left as f64) * 0.8;
        } else {
            // next item cannot use this bin's residual: residual likely dead.
            score += 10.0 + ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0 + 60.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
        // If the current item is large relative to capacity, new bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 70.0;
        }
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    // Small late-stream bonus for tight packing (fewer wasted partial bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are impossible,
    // but tiny gaps relative to plausible item sizes are dead weight. Penalize gaps that are
    // too small to be useful for the known next item or typical small items.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(30) } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        // Harsh penalty: this bin would become trash after placement.
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Exact match to next item's lookahead: placing item leaves room exactly for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, reward using it
    // (avoid opening a new bin unnecessarily) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // item would leave a large, useful residual AND open bins are congested. Otherwise
    // penalize the fresh bin so we keep filling existing ones.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // A new bin with a big item is fine early; late in the stream, prefer existing bins.
        score += 20.0 - 10.0 * progress;
        // If many bins already fit the item, definitely don't open a new one.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 6.0;
        }
        // If next item is large, a fresh bin has future value.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: when the average open bin still has lots of room,
    // mildly discourage this bin if it wastes more than the mean.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 5.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect chain: post_residual == next_item_size -> strong bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits: reward proportionally to how well it uses the leftover.
            let fill_ratio = nxt / post;
            score -= 40.0 * fill_ratio * fill_ratio;
        } else {
            // Next item cannot fit the leftover: penalize dead space that is too small.
            score += 0.5 * (nxt - post);
        }
        // Bonus if chain of two: item + next leaves near-zero residual.
        if post >= nxt {
            let chain_residual = post - nxt;
            if chain_residual < 10.0 {
                score -= 25.0 * (10.0 - chain_residual);
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.2 * post_residual as f64;
    }

    // Tight fit reward relative to current bin residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize bins whose residual deviates strongly below mean (likely fragmented).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins early; allow later when fragmentation is high.
        score += 55.0 - 20.0 * progress;
        if post_residual as f64 > 0.7 * bin_capacity as f64 {
            // Very large item in a fresh bin is fine.
            score -= 30.0;
        }
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 40.0; // fresh bin enables perfect 2-chain
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small waste relative to item).
    score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.3;

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be pickier (penalize waste); late, accept fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.25 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean; opening new bins is penalized implicitly
    // since a new bin has residual = capacity (far from mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    // New-bin candidate: only attractive when current bin is a bad fit or stream is early.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 60.0;
        if bad_fit && progress > 0.3 {
            score -= 8.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fits are good (low post_residual).
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small residuals are less critical; later, waste hurts more.
    let waste_curve = pr / cap;
    let progress_weight = 0.5 + 2.0 * progress * progress; // smooth acceleration
    score += 8.0 * waste_curve * waste_curve * progress_weight * cap * 0.1;

    // Reward near-perfect fits super-linearly.
    let tightness = 1.0 - waste_curve;
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize unless the item is large relative to capacity
    // and open bins are mostly full (mean_residual low) or fit is poor.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let crowding = 1.0 - (mean_residual / (open_bins_count.max(1) as f64 * cap)).min(1.0);
        let penalty = 20.0
            - 12.0 * item_frac
            - 10.0 * crowding * crowding
            - 5.0 * progress;
        score += penalty;
    }

    // Lookahead: if next item fits perfectly in the post-residual, reward this bin;
    // if post-residual is too small for the next item, mildly penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = (pr - ni) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 2.0 * ((ni - pr) / cap);
        }
    }

    // Mildly discourage scattering across many bins when residuals are similar.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * waste_curve;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold even the smallest item are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < item_size.min(20) {
        // Very small gap relative to the item: penalize heavily but less than absolute waste.
        score += 25.0;
    }

    // Perfect fit bonus: strongly reward leaving (near) zero residual.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item cannot use this residual: dead space likely.
            score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: discourage spreading across too many bins, but allow new bins
    // when this is the only fitting bin and the fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // still better to fill the bin than waste it entirely
        }
    }

    // New-bin candidate: make empty bins attractive only when open bins are crowded
    // or the residual structure is bad.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score = 35.0 + 10.0 * (1.0 - crowded.min(1.0));
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: opening a new bin is necessary
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean
    // (small residual = tight bin gets priority).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect match: next item fits tightly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // tight fit bonus decays with slack
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        // if next item would leave another perfect leftover after it, extra reward
        let second_post = post_residual - next_item_size;
        if second_post == 0 {
            score -= 300.0;
        }
    }

    // Penalize if next item does NOT fit into post_residual (dead space for lookahead)
    if next_item_size > post_residual && next_item_size > 0 {
        score += 80.0 + (next_item_size - post_residual) as f64;
    }

    // Reward filling a bin very full (small post_residual) relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 40.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 20.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize leaving awkward residual in a nearly empty bin when many bins are open
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 30.0;
    }

    // Late in the stream, prefer tight packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        score += (post_residual as f64).powf(1.25) * 0.15;
    }

    // Lookahead coupling: if next item fits into the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.25 * slack.min(30.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space penalty scaled by how much next item overshoots.
        score += 0.10 * ((next_item_size - post_residual) as f64).min(50.0);
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins with residual far below mean residual (consolidate large holes).
    score -= 0.20 * (mean_residual - bin_residual as f64).clamp(-50.0, 50.0);

    // Time horizon: late in stream, be frugal — discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 40.0 * progress;
        // Opening a new bin is acceptable only if current bin leaves big dead space.
        score -= (post_residual as f64) * 0.5;
    }

    // Prefer filling fuller bins when many bins are open.
    score += 0.05 * (open_bins_count as f64).min(20.0) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64;

    // Polynomial coupling of post_residual with stream progress:
    // early on, larger leftovers are more acceptable (they may absorb future items);
    // late in the stream, dead space is heavily penalized.
    let early_weight = (1.0 - progress) * (1.0 - progress);
    let late_weight = progress * progress;
    score += late_weight * 60.0 * x * x;          // quadratic dead-space penalty grows over time
    score -= early_weight * 15.0 * x * (1.0 - x); // reward mid-sized leftovers early

    // Cubic interaction: extreme tight fits (x near 0) are always good; extreme waste (x near 1) bad
    score += 20.0 * x * x * x * (0.5 + progress);

    // Mean-residual coupling: if this bin is much emptier than average, using it is cheap
    let dev = (mean_residual - pr) / cap;
    score -= 8.0 * dev * dev.abs().sqrt().signum() * dev.abs().sqrt() * dev.abs().sqrt();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_ratio = 1.0 - ((pr - nx) / cap).abs();
            score -= 18.0 * fit_ratio * (0.4 + 0.6 * progress);
        } else {
            // post residual too small for next item: mild penalty scaled by waste
            score += 6.0 * x * (1.0 - progress);
        }
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when all open bins fit poorly
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * progress - 10.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of post_residual: residuals near multiples of small
    // "harmonic" denominators (2,3,4,5 of capacity) are more reusable.
    let frac = pr / cap;
    let mut harmonic_bonus = 0.0;
    for &d in &[2.0f64, 3.0, 4.0, 5.0] {
        let target = 1.0 / d;
        let dist = (frac - target).abs();
        // reward closeness to harmonic fraction of capacity
        harmonic_bonus += (0.15 / (dist * dist + 0.002)) * (1.0 / d);
    }
    score -= harmonic_bonus;

    // Exact-fit reward: post_residual zero is perfect
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable residual (below min item size 1
    // is impossible, but tiny residuals relative to next item are dead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (post_residual as f64);
    }

    // If next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Modulo-10 class of post_residual: residuals that are multiples of 10
    // (harmonic grid) pair well with typical item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: classify residual into coarse buckets
    let bucket = post_residual / (bin_capacity / 5).max(1); // 0..=5
    score -= match bucket {
        0 => 8.0,           // near-full bin: good packing
        1 => 4.0,
        2 => 0.0,
        3 => 2.0,
        4 => 5.0,
        _ => 10.0,          // nearly empty open bin: discourage using it
    };

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (1.0 - mean_residual / cap);
        score += 18.0 - crowded.min(18.0);
        // If the next item is huge and mean residual is small, opening is fine
        if next_item_size > 70 && mean_residual < 30.0 {
            score -= 15.0;
        }
    }

    // Slight preference for tight fills overall
    score -= 0.05 * (item_size as f64);

    // Late-stream tightening: pack harder as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Tiny unusable gaps (1..9) are dead space: penalize proportionally to how useless they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Reward tight fill ratio (item size relative to available space).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 20.0;
    }

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can also land here: chain-friendly placement.
            score -= 8.0;
        } else if post_residual > 0 {
            // This placement strands space the next item cannot use.
            score += 2.0;
        }
    }

    // --- Open-bins pressure / last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can take the item: avoid opening a new bin.
        score -= 6.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is costly, especially with many bins already open.
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But allow a new bin for near-capacity items (would leave a useful large residual anyway).
        if (item_size as f64) > 0.9 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Prefer bins tighter than the current mean residual (consolidation pressure).
    score += (bin_residual as f64 - mean_residual) * 0.02;

    // Mild stream-progression term: late in the stream, waste matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post_residual as f64 * 0.05 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward bins that end nearly empty.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 800.0; // perfect two-item chain
        } else if gap <= 10.0 {
            score -= 300.0 - gap * 20.0; // near-chain bonus decaying with gap
        } else {
            score += gap * 0.5; // mild penalty for leaving awkward leftovers
        }
    }

    // Compare post_residual against mean residual: prefer bins that stay near/below mean.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by number of usable open bins.
        score += 50.0 + 30.0 * fitting_bins_count as f64;
        // But if next item is large and post_residual (= capacity - item) can chain, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight penalty for very small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Late-stream tie-breaker: prefer tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Dead-space penalty: post_residual too small to fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: penalize opening a new bin, more so
    // when open bins exist and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        score += 30.0 + 10.0 * open_pressure.sqrt() - 10.0 * progress;

        // Opening new bin is more attractive if mean residual is badly fragmented.
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 5.0;
        }
    } else {
        // Favor reusing bins with larger residuals when many bins are open.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: tight fit preferred, with smooth polynomial shaping of post_residual.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: later in the stream, dead space matters more.
    score += 12.0 * progress * norm_post * norm_post * cap * 0.1;

    // Interaction of post_residual with mean residual: avoid bins that leave
    // post_residual far below mean_residual (fragmenting useful space).
    let gap = (mean_residual - post).max(0.0);
    score += 0.05 * gap * gap / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (post - nx).abs();
        if nx <= post {
            score -= 15.0 * (1.0 - d / cap);
        } else {
            score += 0.02 * (nx - post) * (nx - post) / cap;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation early).
    score += 0.15 * open_bins_count as f64 * norm_post;

    // Slight reward for filling large fraction of the bin's residual.
    score -= 0.3 * (item_size as f64 / res.max(1.0)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by integer division
    // into capacity-fraction buckets. Small classes are "dead space" -> penalize.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let dead_class = post_residual / eighth; // 0..8 harmonic class
    match dead_class {
        0 => score -= 12.0,                      // near-perfect fit, reward heavily
        1 => score -= 6.0,                       // good fit
        2 => score -= 1.0,                       // decent (<= quarter left)
        3 => score += 3.0,                       // awkward gap
        4 => score += 6.0,                       // half bin wasted
        _ => score += 9.0,                       // mostly empty bin chosen poorly
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: leftover is reusable by next item.
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * (1.0 - ratio);        // tighter re-use rewarded more
            if post_residual % next_item_size == 0 {
                score -= 4.0;                    // exact harmonic division
            }
        } else {
            // Next item won't fit here; penalize proportionally to how much
            // the leftover is "unusable" for the lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly discouraged early when
    // many bins are open and mean residual is large; encouraged late when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - 15.0 * (1.0 - progress) * avg_fill;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin always fits the lookahead
        }
    }

    // Mild global pressure: with many open bins, favor consolidation into
    // existing bins (penalize new-bin tendency implicitly via above; here
    // reward tight fits scaled by congestion).
    score -= 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 20 && post_residual <= 30 {
        score -= 10.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    // Favor bins tighter than the mean residual (good packing density).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead: if next item fits the post-residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // (or near-exactly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong reward; near match => partial reward.
        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 25.0 - 4.0 * gap;
        } else {
            // Penalize leftovers that are too small for the next item (dead space)
            if (post_residual as f64) < next_item_size as f64 {
                score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
            }
        }
        // Bonus if after placing this item, the bin could also host the next one
        if post_residual >= next_item_size {
            score -= 10.0 + 0.05 * post_residual as f64;
        }
    } else {
        // Last item: just minimize leftover tightly.
        score -= 15.0;
    }

    // Perfect fit reward (no waste at all)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins first).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Prefer not to open new bins when many bins are already open and stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mildly penalize blocking bins with good residuals.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global residual context: if mean residual is large, we can afford looser fits;
    // if mean residual is small, prioritize preserving flexible large-residual bins.
    if bin_residual as f64 > mean_residual {
        score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) > 0.0 && (bin_residual as f64 - item_size as f64) < mean_residual;
        if desperate {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space matters more as stream progresses
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth coupling
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (spreading fill evenly)
    score += 0.3 * (post - mean_residual);

    // Lookahead coupling: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize slightly unless current residual unusable
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits get strong reward.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals that divide capacity cleanly (harmonic slots)
        // are reusable; odd fragments are penalized.
        let pr = post_residual;
        let harmonic = (bin_capacity % pr == 0) || (pr % 10 == 0);
        if harmonic {
            score -= 30.0;
        }
        // Dead-space penalty for tiny unusable fragments (1..10).
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Quarter/half capacity fraction thresholds: residual in [25,50] is a
        // "medium slot" that fits many mid-size items -> reward; [1,24] poor.
        if pr >= 25 && pr <= 50 {
            score -= 15.0;
        } else if pr < 25 {
            score += 20.0;
        }

        // Lookahead coupling: does the next item fit into the post residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 25.0;
                // Integer-division harmony: how many next-item copies fit.
                let copies = pr / next_item_size.max(1);
                score -= 5.0 * copies as f64;
            } else {
                score += 10.0;
            }
        } else {
            // Last item: just fill tightest.
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score += 40.0 - 60.0 * crowded;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        // Unusable sliver: nothing small can realistically use it later.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }
    // Penalize if the lookahead item cannot fit in the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, avoid spreading; prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 1.5;

    // Prefer bins with residual below the current mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., the item would leave a wasteful gap in every open bin).
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_residual - item_size) as f64;
        if waste_if_forced < 10.0 {
            // Item nearly fills a fresh bin anyway: opening is fine.
            score -= 5.0;
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // Opening a new bin while others fit: penalize proportionally to
            // how well the item would fit elsewhere.
            score += 35.0 + waste_if_forced * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward when next_item_size exactly matches post_residual.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if ni <= pr {
            let gap = pr - ni;
            // Perfect chaining: next item fills this bin exactly.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / pr.max(1.0));
            }
            // Penalize leaving residual that no future item can plausibly use
            // (residual smaller than min item size is dead space).
            if pr < 1.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here; residual is likely stranded.
            score += 15.0 + (ni - pr).min(50.0);
        }
    } else {
        // Last item: prefer zero waste.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Dead-space penalty: residual below typical minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Compare against mean residual: prefer bins with residual close to item size
    // relative to the fleet average (avoid wasting large-residual bins on small items).
    let mr = mean_residual.max(1.0);
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    if ratio > 0.7 {
        score -= 12.0 * ratio;
    }
    if (bin_residual as f64) > mr * 1.5 && ratio < 0.4 {
        score += 10.0; // don't burn large bins on small items
    }

    // Mild preference to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    // New-bin candidate: only attractive when the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (next_item_size as f64) >= (bin_capacity as f64 * 0.6) {
            score -= 20.0; // save empty bin for a big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead: reward bins whose post-residual can host the next item.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }

    // Near-perfect fit: strongly reward tiny dead space.
    if !is_new_bin && post_residual < 10 {
        score -= 6.0;
    }

    // Awkward mid-range gap that small future items may not exploit.
    if !is_new_bin && post_residual >= 25 && post_residual < 40 {
        score += 4.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate baseline: mildly attractive early, less so late.
    if is_new_bin {
        score += 6.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits; new bin is mandatory
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Global coupling: prefer bins whose residual diverges from the mean
    // (consume outliers, keep average residual available).
    score += 0.1 * (mean_residual - post_residual as f64);

    // Slight preference to keep many open bins from proliferating.
    if !is_new_bin {
        score -= 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), modulated by progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.5 * norm_pr * norm_pr * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (balance exploitation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = (pr - ns).abs() / cap;
        score += 8.0 * compat * compat;
        score -= 5.0 / (1.0 + compat);
    }

    // New-bin candidate: mild penalty so we prefer open bins unless residuals are poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0;
    }

    // Slight pressure against bin proliferation late in the stream
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: how "reusable" is the leftover space?
    // Classify post_residual by capacity fraction (mod-classes of 10/25/etc).
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty: leftover too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 25 {
        score += 12.0; // hard to fill
    } else {
        // Reusable space: reward proportionally, with harmonic modulation.
        score -= 8.0 * frac;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if leftover becomes dead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin should only win when item is large
    // (poor fit elsewhere) or few bins open. Penalize new bin for small items.
    if bin_residual == bin_capacity {
        let r = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - r); // small items: discourage new bin
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size > post_residual.min(bin_capacity - item_size) {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Slight preference to fill emptier bins first (balance residuals),
    // keeping some bins tight for future small items.
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Late-stream bias: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space relative to capacity: quadratic penalty on wasted fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    if waste_frac > 0.0 && waste_frac < 0.25 {
        score += waste_frac * 60.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post_residual blocks the next item but is nonzero (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 5.0;

    // Prefer bins with below-mean residual (more filled) when many bins are open.
    if open_bins_count > 2 {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // New-bin candidate: keep it moderately attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward near-exact match between post_residual and next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.9 * lookahead_gap;
        // Perfect 2-step match: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Very tight match bonus
        else if lookahead_gap <= 3.0 {
            score -= 12.0;
        }
        // Penalize leaving residuals the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: minimize waste directly
        score += 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // First-fit style preference for tight fits now
    score += 0.15 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strong penalty for opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin if placing here would strand a big residual vs next item
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Dead-space penalty: residuals too small for the smallest item (1)
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Late-stream consolidation: fewer wasted bins near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use leftover; penalize proportionally to waste
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * crowding;

    // Prefer bins below mean residual (fuller than average) when many bins open.
    if open_bins_count > 2 {
        score += 0.15 * ((bin_residual as f64) - mean_residual);
    }

    // Time horizon: early in stream, keep flexibility (favor larger post_residual slightly);
    // late in stream, squeeze bins hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 5.0 * tightness;

    // New-bin candidate: open a fresh bin only if this item is large relative to capacity
    // and no strong last-chance pressure exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else if large_item > 0.5 && next_item_size > 0 && next_item_size >= post_residual.max(1) as u32 {
            score -= 20.0; // large item, next item won't fit elsewhere nicely anyway
        } else {
            score += 35.0 + 10.0 * (1.0 - progress); // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (waste), with smooth non-linear penalty on mid-range dead space.
    let mut score = pr;

    // Non-linear coupling: mid residuals are worst (unusable dead space), penalize via
    // a smooth polynomial bump centered around x ~ 0.35-0.5.
    let bump = x * (1.0 - x); // peaks at x=0.5
    score += 30.0 * bump * bump * 4.0;

    // Stream progress coupling: later in the stream, waste matters more (less time
    // to recover residual), reward tight fits progressively.
    score -= (1.0 - x).powi(3) * (10.0 + 40.0 * progress);

    // Early stream: keep residuals large/flexible; penalize very tight fits mildly.
    score += (1.0 - progress) * x * x * 20.0;

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (x * cap - nxt).abs();
        score += 0.15 * gap;
        // Perfect next-item fit bonus
        if gap < 1.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual context: penalize bins far from the mean (fragmentation of the pool).
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    // Slight preference for fewer open bins (bin consolidation).
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class decomposition of post_residual (capacity = 100) ----
    // Class the leftover space into "harmonic" residue bands relative to C.
    let c = bin_capacity as f64;
    let frac = post_residual as f64 / c;              // capacity fraction left
    let q10 = (post_residual / 10) % 10;              // tens digit (0..9)
    let r10 = post_residual % 10;                     // unit residue class

    // Dead-space penalty: residues that are hard to fill (1..=9 units).
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 + 2.0 * (10 - post_residual) as f64;
    }
    // Harmonic sweet spots: exact quarter/half fills are highly reusable.
    if post_residual == bin_capacity / 2 || post_residual == bin_capacity / 4 || post_residual == (3 * bin_capacity) / 4 {
        score -= 12.0;
    }
    // Modulo-10 class bonus: multiples of 10 are friendlier for typical item sizes.
    if r10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += 0.8 * r10 as f64; // penalize awkward unit residues
    }
    // Tens-digit shaping: prefer keeping leftovers in the 20..50 "flexible" band.
    if q10 >= 2 && q10 <= 4 {
        score -= 5.0;
    } else if q10 >= 7 {
        score += 4.0; // very large leftovers waste a bin slot
    }

    // ---- Fractional coupling with mean residual ----
    let spread = frac - mean_residual / c;
    score += 8.0 * spread.abs();

    // ---- Lookahead: does the next item fit harmonically? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            let nxt_frac = nxt_post as f64 / c;
            // reward two-step tight packing; bonus if the chain lands on a multiple of 10
            score -= 10.0 * (1.0 - nxt_frac);
            if nxt_post % 10 == 0 {
                score -= 4.0;
            }
            if nxt_post <= 9 && nxt_post > 0 {
                score += 6.0; // chain creates dead space
            }
        } else {
            score += 5.0; // next item won't chain into this bin
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 0.5 * post_residual as f64;
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 {
        score -= 15.0; // strongly favor the only bin that fits
    } else if fitting_bins_count == 0 {
        score += 0.0; // only the new-bin candidate reaches here
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early in the stream or when open bins are crowded,
        // unattractive when the current item leaves a harmonically good leftover.
        let stream_pos = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = item_size as f64 / c;
        score = 40.0 - 20.0 * (1.0 - stream_pos) - 15.0 * (1.0 - tight_fit);
        if post_residual % 10 == 0 && item_size >= bin_capacity / 2 {
            score += 8.0; // item nearly fills a bin cleanly; prefer reusing open bins
        }
    }

    // ---- Stream-phase modulation: late in the stream, consolidate aggressively ----
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small gap
    // that few future items can use) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 34 {
        score += 8.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect-fit bonus: residual exactly consumed.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (1.0 - progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual well, reward this
    // placement; if post-residual is too small for the next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let waste = post - nxt;
            score -= 12.0 * (1.0 - waste / cap);
        } else if post > 0 {
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // New-bin candidate: only attractive when the current bin residual is
    // poor (large item, small residual mismatch) or mean residual is tiny.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing
        // options are.
        let mean_fit = mean_residual / cap;
        score = cap - post + 55.0 - 45.0 * (1.0 - mean_fit);
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative, must open
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            score -= 15.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Penalize leftover that is too big to be useful for next item.
        let gap = (post_residual - next_item_size) as f64;
        score += gap * 0.35;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; dead space penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare against mean residual: bins already tighter than average are preferred.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for keeping many bins consolidated as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate: make it costly unless it's genuinely better than poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin when current item is large and next item is large too.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post-residual), with non-linear sharpening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item can fit into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we place current item here poorly? mild penalty
            score += 5.0;
        } else {
            // Next item won't fit anywhere here; avoid leaving large dead space
            score += 8.0 * fit_ratio;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when good open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large relative to residual
        // landscape or few bins fit the item.
        let openness = open_bins_count as f64;
        let time_frac = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        // Prefer new bin if item is big and would leave small waste anyway, or if
        // mean residual across open bins is small (all bins nearly full).
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let reward = 55.0 * mean_tightness * (0.5 + 0.5 * scarcity) + 20.0 * (1.0 - time_frac);
        score -= reward;
        // Slight preference against new bins late in the stream.
        score += 10.0 * time_frac;
    } else {
        // Favor bins tighter than the average residual (good utilization).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Discourage very small post-residuals only if they exceed a "dead space" sweet spot
    // (perfect fit is fine; tiny waste is fine; mid-range waste is worst).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.35 * progress * progress)
        - 18.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - 0.5 * progress);

    // Smooth interaction: small residuals become more valuable as stream advances.
    score -= 25.0 * (1.0 - norm_post).powi(3) * progress;

    // Penalize new-bin candidate, more strongly early in the stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;
    if is_new_bin {
        score += 40.0 * (1.0 - 0.6 * progress) + 3.0 * open_bins_count as f64;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).powi(2);
        if post == next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - 0.4 * progress);
    }

    // Mild penalty for bins far from the mean residual (fragmentation avoidance).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into eighths.
    let eighth = bin_capacity / 8;
    let quarter = bin_capacity / 4;

    // Reward near-perfect fits: post_residual in the lowest harmonic class.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < eighth {
        score -= 60.0;
    } else if post_residual < quarter {
        score -= 20.0;
    }

    // Penalize dead space: leftover that no plausible item (>=1) can pair with.
    // Modulo-style classes: leftover in (quarter, half) is semi-usable,
    // leftover above half wastes the bin's "big half".
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.5;
    }

    // Harmonic coupling with lookahead: if next item fits exactly into
    // post_residual (perfect chord), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // classify the double-placement leftover
            if nxt_post < eighth {
                score -= 40.0;
            } else if nxt_post < quarter {
                score -= 15.0;
            } else if nxt_post > bin_capacity / 2 {
                score += 10.0;
            }
        } else {
            // next item won't fit here; small penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item is
    // large and no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0 - 40.0 * progress;
        // Opening a new bin is attractive for big items (harmonic class of item_size).
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If many bins are open and mean residual is high, prefer reusing them.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Tie-break: prefer fuller bins (smaller bin_residual) and fewer open bins.
    score += bin_residual as f64 * 0.05;
    score += open_bins_count as f64 * 0.3;

    // Mild preference to consolidate when mean residual is low.
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are small (unusable gaps)
    // are penalized super-linearly. Gap in 1..=10 is likely dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 8.0;
    }

    // Reward residuals that can still host a typical item (>= 10).
    if post_residual >= 10 {
        score -= 15.0;
    } else if post_residual > 0 {
        score += 30.0; // gap below minimum item size = dead space
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score += slack as f64 * 6.0; // would leave a bad gap for next item
            } else {
                score -= 20.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; few open bins -> opening new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure so it is only chosen when
        // all open bins would create severe dead space.
        score += pressure + 60.0 * progress;
    } else {
        score -= pressure * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — favor placing here to consolidate.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how close it is to useless.
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.3 * waste;
    }

    // Perfect-fit reward: residual nearly zero after placement.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean (tighter bins).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fits exist, especially early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
        // But if next item is huge and residual after placement would be large, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for fragmenting large-residual bins when many bins are open.
    if open_bins_count > 3 && post_residual > 0 && post_residual < item_size / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed residual is cheap.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space below typical smallest item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when it enables a good future fit
    // or current fits are all poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let lookahead_waste = if next_item_size > 0 {
            (bin_capacity as f64 - next_item_size as f64).max(0.0) * 0.15
        } else {
            0.0
        };
        // Opening new bins is penalized more as stream progresses (less time to amortize).
        let open_penalty = 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        score += open_penalty - lookahead_waste;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual.max(0.0);
        // Perfect-fit lookahead: reward fresh bin if next item pairs well with a full bin.
        if next_item_size >= 90 {
            score -= 25.0;
        }
    } else {
        // Lookahead synergy: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 45.0;
        } else if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        } else if next_item_size > post_residual as u32 {
            // Next item won't fit here; slightly penalize wasting this bin's future utility.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Mild preference for filling more-opened bins (keep fewer bins active).
    score += 0.05 * open_bins_count as f64;

    // Slight global balance: prefer bins with residual above mean (leave small bins for small items).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Smooth progress coupling: later in the stream, penalize wasted space more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward filling bins that leave little dead space relative to mean residual
    score -= 0.5 * (mean_residual - pr) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_norm);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let slack_after_next = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack_after_next * slack_after_next);
        } else {
            // Penalize blocking the next item when post_residual is small
            score += 3.0 * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead" classes (small, hard-to-fill remainders) should be penalized.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left over

    // Class the residual into coarse harmonic buckets (mod-style thresholds).
    let class = (post_residual / 10).min(10); // 0..10 integer division class
    // Dead-space classes: residuals 1..=9 are nearly unusable for items >=10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Sweet-spot classes: leftover that many item sizes can still use.
    match class {
        0 => score -= 8.0,          // perfect fit
        1 => score -= 4.0,          // 10-19: usable by small items
        2 | 3 => score -= 2.5,      // 20-39: decent
        4 | 5 => score -= 1.0,      // 40-59
        6 | 7 => score += 0.5,      // 60-79: large leftover, ok but loose
        _ => score += 1.5,          // 80+: very loose packing
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item consumes leftover
            let fill = next_item_size as f64 / post_f.max(1.0);
            score -= 12.0 * fill;
            // harmonic bonus if next item leaves another "good class" residual
            let next_post = post_residual - next_item_size;
            if next_post < 10 && next_post > 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual - post_residual) as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent harmonic fit. Penalize it mildly so good fits beat it,
    // but reward it when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // residual after placement in fresh bin
        // slight bias toward consolidating into existing bins
        score += 4.0 + 0.05 * open_bins_count as f64;
        // if mean residual of open bins is small (they are all tight), a new
        // bin is attractive
        score -= (mean_residual / cap).max(0.0) * 10.0;
    }

    // Tightness reward: filling more of the bin now is generally better.
    score -= (1.0 - frac) * 3.0;

    // Stream-progression coupling: late in the stream, prefer tighter packing
    // to avoid leftover bins; early, allow looser exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else {
        // Large leftover gaps are mildly penalized (wasted space).
        score += 0.15 * (post_residual as f64 - 30.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But allow new bin if next item is large and this fit is terrible.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, more so late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 + 10.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmented space.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/low waste strongly (non-linear).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0 + (5 - post_residual) as f64 * 4.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 60.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // small gap => next item fills bin nicely
            if gap <= 10.0 {
                score -= 25.0 - gap * 1.5;
            } else {
                score += gap * 0.3;
            }
        } else {
            // next item cannot fit here: mild penalty for leaving large residual
            let short = (next_item_size - post_residual) as f64;
            score += short * 0.15;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // prefer bins whose post residual is below average (tight packing).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // unless post_residual would be tiny-but-nonzero dead space.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score += 25.0; // avoid stranding 1..9 units
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only prefer opening a new bin when the item is large and would leave
    // an awkward residual in any existing bin.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit_everywhere = fitting_bins_count == 0;
        if big_item || poor_fit_everywhere {
            score -= 35.0;
        } else {
            // discourage opening new bins when existing bins fit decently
            score += 40.0;
        }
    }

    // Early in the stream, allow more bins to open (spreading items); later,
    // tighten packing to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Slight penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for opening a brand-new bin when decent fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Scale penalty by how many alternatives exist and how well the item
        // would otherwise fit (post_residual == capacity - item here).
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 60.0 + 25.0 * fit_quality + 2.0 * (open_bins_count as f64);
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If only one fitting bin exists, heavily discourage abandoning it.
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
        return score;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item would exactly fill the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally,
        // more so when post_residual is small (unusable sliver).
        let sliver = post_residual as f64;
        score += 8.0 * (1.0 - sliver / (next_item_size as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative tightness: compare post_residual against the mean residual of
    // open bins; leaving less than average behind is good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer filling bins that are already partially full (larger item fraction).
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_fraction;

    // Mild time-horizon modulation: early on, be slightly more conservative
    // about creating small residuals (long stream ahead to regret it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - fit_norm) * (1.0 - fit_norm));

    // Penalize near-perfect fills slightly less as stream matures (favor tight packing early)
    score -= 8.0 * (1.0 - fit_norm) * (1.0 - progress);

    // Dead-space penalty: small post_residual that can't fit typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.02 * (open_bins_count as f64 - mean_residual / 10.0).abs();

    // New-bin candidate: discourage unless current bin would leave awkward gap
    if bin_residual == bin_capacity {
        score = pr + 12.0 - 10.0 * (1.0 - fit_norm);
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it aligns with typical item sizes
    let pr = post_residual;
    if pr > 0 {
        // Modulo classes over common item granularity
        let m10 = pr % 10;
        let m20 = pr % 20;
        // Residuals that are multiples of 10 are more reusable
        score -= (10 - m10) as f64 * 0.3;
        if m20 == 0 { score -= 4.0; }
        // Exact small dead space is bad
        if pr < 10 { score += 25.0; }
        // Integer-division thresholds: large leftover chunks are valuable
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr >= half { score -= 8.0; }
        else if pr >= quarter { score -= 3.0; }
        // Pairing bonus: can next item fit exactly?
        if next_item_size > 0 && next_item_size <= pr {
            let after_next = pr - next_item_size;
            if after_next % 10 == 0 { score -= 6.0; }
            if after_next < 10 && after_next > 0 { score += 8.0; }
        }
    } else {
        // Perfect fill
        score -= 30.0;
    }

    // Fractional capacity coupling
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 { score -= 10.0; }
    else if fill_frac < 0.2 { score += 5.0; }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening unless current bins are nearly full
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        if mean_frac < 0.15 { score -= 5.0; } else { score += 12.0 + mean_frac * 20.0; }
    }

    // Progress scaling: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..=10)
    // are permanently unusable -> penalize them quadratically.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits (post_residual very small but item still fits).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tight-fit bonus: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 8.0 * (fill_ratio - 0.8);
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening/spreading into new bins.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap; if next item is larger than post_residual
    // while a tighter option exists, mildly penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 18.0;
        } else if next_item_size as u32 > post_residual && post_residual > 0 {
            score += 4.0;
        }
    }

    // Slight preference for bins below the mean residual (consolidate waste).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the bin afterwards.
            let after_next = post_residual - next_item_size;
            score -= (next_item_size as f64) * 1.5;
            if after_next == 0 {
                score -= 40.0; // perfect 2-item packing
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize dead space proportional to gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.3;
        }
    }

    // Penalize large post_residual relative to mean residual (wasting usable space).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Reward tight fits (small post_residual).
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight bias against opening new bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // or existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty so open bins win by default.
        let mut new_bin_penalty = 55.0;
        // Large items with fragmented open bins favor a fresh bin.
        new_bin_penalty -= 20.0 * item_ratio * fragmentation;
        // Later in the stream, avoid opening bins (less chance to fill them).
        new_bin_penalty += 30.0 * progress;
        // If no open bin fits well (post_residual huge in this call context), soften.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 60.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mildly prefer bins with lower residual than the mean (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Many open bins: encourage consolidation into emptier bins.
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global pressure: when many bins are open, penalize wasteful placements more.
    score += 0.02 * open_bins_count as f64 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit = item_size as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    // Tight-fit reward: strong non-linear discount as post_residual shrinks
    let tight = (-pr / bin_capacity as f64).exp();
    score -= 12.0 * tight * (0.5 + fit);
    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is more costly -> super-linear penalty
    let p = pr / bin_capacity as f64;
    score += p * p * (1.0 + 2.0 * progress) * 8.0;
    score += p * p * p * (1.0 + 3.0 * progress) * 6.0;
    // Penalize new bins, more so as the stream progresses and bins exist
    if is_new_bin {
        score += 4.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using an existing bin; extra reward if it's the only fitting bin
        score -= 2.0;
        if fitting_bins_count == 1 {
            score -= 6.0 + 4.0 * progress;
        }
    }
    // Lookahead: if next item fits the post-residual exactly-ish, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if nx <= pr {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post-residual too small for next item: penalize unusable sliver
            score += 3.0 * (1.0 - pr / (nx + 1.0));
        }
    }
    // Mild pull toward bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: small residues are "dead space" classes ---
    // Class 0: residue 0..=5  -> perfect closure, huge reward
    // Class 1: residue 6..=15 -> near-closure, strong reward
    // Class 2: residue 16..=30 -> medium dead zone
    // Class 3: residue >30     -> large residual, keep flexible
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    } else {
        // large residue: mild penalty proportional to how "unusable" it is
        // (residues that very few item sizes can use)
        let unusable = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 15.0 * unusable;
    }

    // --- Modulo coupling: does post_residual divide/match next_item_size harmonically? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect two-item closure chain
            score -= 250.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic match if slack is small or a divisor-like residue
            if slack <= 5 {
                score -= 120.0;
            } else if slack <= 15 {
                score -= 40.0;
            } else {
                score += (slack as f64) * 0.5;
            }
        } else {
            // next item cannot fit here: residue becomes dead space for lookahead
            score += 20.0;
        }
    }

    // --- Integer-division thresholds on bin fill fraction ---
    // Reward bins that cross harmonic fill levels (1/2, 3/4, 7/8 of capacity)
    let filled = bin_capacity.saturating_sub(post_residual);
    let quarter = bin_capacity / 4;
    if filled >= (7 * bin_capacity) / 8 {
        score -= 60.0;
    } else if filled >= (3 * bin_capacity) / 4 {
        score -= 25.0;
    } else if filled >= bin_capacity / 2 {
        score -= 8.0;
    }
    let _ = quarter;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Base cost of opening: proportional to stream progress (late in stream,
        // consolidation matters more) and current open-bin count.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin preserves full flexibility
        if next_item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
        // If mean residual across open bins is large, avoid spreading more
        if mean_residual > 40.0 {
            score += 25.0;
        }
    }

    // --- Mean-residual coupling: prefer bins near the mean (keeps balance) ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Residuals that can only fit tiny items are semi-dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0 + (25 - post_residual) as f64 * 0.6;
    }

    // Reward perfect and near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as i64) < (item_size as i64) / 4 {
        score -= 15.0;
    }

    // If the lookahead item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // lookahead would create dead space here; mild penalty
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 10.0; // still better to burn dead space than open a bin
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new bin (empty candidate) is relatively cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);
    score += pressure * 3.0;

    // New-bin candidate handling: empty bin has perfect flexibility; make it
    // attractive when existing fits are poor, but not when a good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        score = 30.0 + pressure * 4.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // If this is the last chance, opening a bin is fine (the fitting bin got -25).
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 15.0 * progress;
        // If mean residual across open bins is large, reuse them instead.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Tie-break: prefer bins with residual close to item (tight fit) among equals.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the residual left behind: chain placement possible.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 35.0 - slack * 0.5;
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.25;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins that deviate from the mean residual (prefer balanced fill).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for filling nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when all open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize small dead space (hard to reuse later)
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0;
        }
        // Reward tight fits relative to residual
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mildly penalize leaving large gap
            score += 5.0;
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation)
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Early in stream: slightly favor consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, avoid wasting space
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when item is huge relative to residual
    // or nothing reasonable fits; make empty-bin baseline moderately high.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin leaves room for lookahead pairing
        }
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // on wasted space, normalized to capacity.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth stream-progress coupling: as the stream advances, tighten the
    // packing more aggressively (dead space becomes costlier).
    score += 2.0 * progress * (pr * pr) / cap;

    // Fit ratio coupling: very tight fits (small post_residual relative to
    // residual) get a smooth reward via a saturating term.
    let fit_ratio = 1.0 - (pr / bin_residual.max(1) as f64);
    score -= 6.0 * fit_ratio * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item fits the post-residual smoothly,
    // reward this placement; penalize if next item is close to but exceeds it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = ni - pr;
        if gap <= 0.0 {
            // next item fits exactly into remaining space: smooth reward
            let exact = 1.0 - (gap.abs() / cap);
            score -= 8.0 * exact * exact;
        } else {
            // next item does not fit: penalize wasted space that just misses
            let miss = (gap / cap).min(1.0);
            score += 5.0 * miss * miss * (1.0 + progress);
        }
    }

    // Mean-residual coupling: when average residual across open bins is high,
    // discourage dumping into a bin that leaves large post-residual.
    score += 0.05 * mean_residual * (pr / cap);

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are
    // poor fits (large post_residual here) — smooth threshold via tanh-like term.
    if bin_residual == bin_capacity {
        let openness = (pr / cap - 0.35).tanh();
        score += 25.0 + 20.0 * openness;
    }

    // Mild pressure against bin proliferation.
    score += 0.1 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // residue classes modulo 10 (typical item granularity band).
    let r = post_residual % 10;
    // Residues that are "dead" (hard to fill by any future item 1..100
    // in practice): small nonzero leftovers are the worst.
    let dead_penalty = match r {
        0 => -6.0,           // perfectly aligned leftover
        1..=3 => 14.0,       // nearly-dead sliver
        4..=7 => 4.0,        // moderately usable
        _ => -2.0,           // 8..9 usable by small items
    };
    score += dead_penalty;

    // Integer-division threshold on post_residual: leftovers below the
    // smallest plausible item band are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item exactly fills the leftover,
    // this is a harmonic completion -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // leftover cannot host the next item anyway -> mild reward
            // scaled by how "sealed" the bin is.
            score -= 3.0 + (post_residual as f64) * 0.05;
        } else {
            // next item fits, but leaves another leftover: penalize
            // creating a chain of awkward remainders.
            let chain = post_residual - next_item_size;
            let chain_r = chain % 10;
            if chain_r >= 1 && chain_r <= 3 && chain < 10 {
                score += 12.0;
            } else {
                score += (chain as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it instead of opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual <= 5 {
            score -= 15.0; // near-perfect closure
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Opening a new bin is attractive when the item is huge relative
        // to capacity (harmonic class of item_size near capacity).
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 45.0 * (frac - 0.5) * 2.0;
        }
        // If existing bins are crowded (low mean residual), new bin is fine.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        // Few open bins early in the stream -> cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
        // If next item is large and this bin would be nearly full after
        // placement, opening fresh is good.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && frac > 0.6 {
            score -= 12.0;
        }
    } else {
        // Reward tightness of fit in existing bins (small post_residual
        // relative to item size means efficient packing).
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 10.0;
        // Penalize spreading across too many bins when residuals are high.
        if (mean_residual - post_residual as f64).abs() < 2.0 && open_bins_count > 3 {
            score -= 4.0;
        }
    }

    // Global pull: prefer bins whose residual is below the mean (compact bins).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    let min_useful = 10u32; // smallest useful gap
    if post_residual > 0 && post_residual < min_useful {
        score += 1000.0;
    }
    // Penalize gaps too small for the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 300.0 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) more aggressively.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 50.0;

    // Open-bins pressure: with many open bins, favor filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (bin_residual == bin_capacity) as i32 as f64 * 20.0;
    // General mild pressure proportional to open bins when fit is loose.
    score += pressure * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: make it less attractive unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if next item is huge and this item is small, opening a fresh bin
        // may preserve large residuals elsewhere; slight discount.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 120.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end with (near-)zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact 2-step match: post_residual equals next item -> chain fill.
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            // Proportional reward: closer the next item fits, the better.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * tightness;
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space that the next item cannot use,
        // scaled by how "wasted" the residual is relative to next item.
        let waste = post_residual as f64 - (next_item_size as f64 - 1.0).min(post_residual as f64);
        score += 0.5 * waste;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    let mean_diff = mean_residual - bin_residual as f64;
    score += 0.3 * mean_diff;

    // Last-chance bonus: if this is the only fitting bin, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // the item is huge relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 50.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 100.0; // large items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 30.0; // fresh bin can also host next item
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about leaving loose residuals (fewer chances to fix them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Slight penalty for fragmenting across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (super-linear penalty on wasted space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are fine actually -> invert
        score -= 45.0; // net: small post-residual is GOOD
    }
    // Medium dead space (10..30) is the true waste zone.
    if post_residual >= 10 && post_residual <= 30 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size <= bin_residual {
            // next item could have used pre-residual equally; neutral
            score += 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open and empty-ish.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress + open_bins_count as f64;
        // But allow new bin if mean residual across open bins is too small for item.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
        // If no open bin can fit, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Favor placing into bins whose residual is closest to item (best fit already via fit_ratio).
        // Slight preference for bins below mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Early stream: be greedy with filling, mild bonus for using existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, non-linearly
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * (1.0 + progress * progress * 3.0) * (1.0 - pr_norm * 0.5);
    score += coupling * cap * 0.5;

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= (cap - pr) * progress * 0.8;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (pr - nxt).min(20.0) as f64 * 0.6 * (1.0 - progress * 0.5);
        } else {
            score += (nxt - pr) * 0.4;
        }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15 * pr_norm;

    // New-bin candidate: keep neutral-ish unless current fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) - item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 5 harmonic bands.
    let band = (bin_capacity as f64 / 5.0) as u32;
    let class = post_residual / band; // 0..=4

    // Reward tight fits: post_residual in the smallest classes are good.
    score -= (4 - class.min(4)) as f64 * 6.0;

    // Dead-space penalty: residuals that are "awkward" (small but nonzero) are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make it unattractive unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If no open bin fits tightly, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize if it would have fit the pre-placement residual.
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Modulo-class harmonic logic: residuals divisible by common item sizes are reusable.
    if post_residual > 0 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 5.0; // clean multiple of 10
        } else {
            score += m as f64 * 0.4; // ragged residual penalty
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's already tight — favor it.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Integer-division threshold on next_item_size: big next items prefer clean residuals.
    if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small gaps
    // that few future items can use) is heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward filling large residuals (tightly packing existing space).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Penalty for leaving residual that exactly matches next item (waste of
    // a good future fit is fine, but mismatched leftovers are worse):
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Open-bins pressure: prefer bins that reduce fragmentation when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate unless it is genuinely better
    // (a new bin has maximal residual, so add pressure to prefer reusing open bins).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
        // Extra reward for near-perfect 2-item packing (little waste after both)
        let two_step_waste = post_residual - next_item_size;
        score -= 10.0 / (1.0 + two_step_waste as f64);
    }

    // Penalize large leftover dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter fits: small post-residual is already base score; boost exact fits
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Slight penalty for opening a new bin when many bins are open and it's early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be conservative; late, exploit tight fits.
    let progress = step_index as f64 / total_items as f64;

    // Penalize awkward tiny leftovers (dead space that few future items can use).
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if dead < 0.10 {
            score += (0.10 - dead) * 40.0; // small unusable gap is bad
        } else if dead > 0.5 {
            score -= (dead - 0.5) * 6.0; // large leftover keeps flexibility
        }
    } else {
        score -= 8.0 + 10.0 * progress; // perfect fill is excellent, more so late
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 12.0 - 14.0 * snug.min(1.0); // prefer next item fitting snugly too
    } else if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
        score += 5.0; // next item likely stranded here otherwise
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Fragmentation pressure: many open bins -> consolidate into fuller bins.
    score += (mean_residual - post_residual as f64) * 0.08 * (open_bins_count as f64).ln().max(1.0);

    // New empty bin candidate: expensive; only attractive when the item is huge
    // or every open bin is nearly full / the stream is early with room to grow.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 30.0 * fill_ratio * fill_ratio
            - 25.0 * (1.0 - progress)
            + 10.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    let mut score = pr + 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize last-chance bins slightly less when tight
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * tightness;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 6.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: prefer opening fresh bins early, penalize later
    if bin_residual == bin_capacity {
        score += 4.0 - 12.0 * progress + 0.5 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 / 25 define "usable" dead space.
    let r = post_residual;
    let class10 = (r % 10) as f64;
    let class25 = (r % 25) as f64;

    // Penalize residues that are awkward (small nonzero remainders are dead space).
    if r > 0 {
        score += (10 - class10.min(10.0 - class10)) * 0.4;
        if class25 < 5.0 { score += 3.0; }
        if r < 10 { score += 25.0; } // tiny unusable sliver
    } else {
        score -= 15.0; // perfect fit
    }

    // Lookahead coupling: does post_residual serve the next item?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            // Reward bins whose leftover after next item lands on a good harmonic class.
            let nxt_class = ((r - next_item_size) % 10) as f64;
            score -= 12.0 - slack * 0.15 - (10.0 - nxt_class) * 0.3;
        } else {
            // Next item won't fit here: leftover is final dead space.
            score += (r as f64) * 0.25 + 5.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 8.0;
    }

    // Integer-division thresholds on post_residual.
    let q = r / 20; // coarse capacity fraction
    score -= q as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    // (i.e., when mean residual is high but this item is small relative to it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // Opening is attractive if existing residuals are fragmented (high mean, poor fit).
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 100.0
            - fragmentation * 0.5
            - (openness.ln().max(0.0)) * 3.0
            + progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin cleanly serves both current and next item.
            if item_size + next_item_size <= bin_capacity {
                score -= 10.0;
            }
        }
    }

    // Slight tie-break toward fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    score -= (item_size as f64) * (item_size as f64) / (bin_capacity as f64) * 0.5;

    // Strict dead-space avoidance: penalize tiny unusable gaps (1..=9)
    // that almost no future item (min size 1..100 stream) can use efficiently.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0 + (10 - post_residual as i32) as f64 * 2.0;
    }
    // Also penalize awkward mid gaps that fit nothing likely (e.g. 91..99
    // only reachable for huge items is fine; but gaps < smallest plausible item are dead).
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here: slight penalty for stranding capacity
            score += 3.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // decent fits exist; encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Mean-residual coupling: bins far below mean residual are "wasted";
    // prefer bins whose residual is close to item need (avoid fragmenting fat bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral base so it only wins when all
    // open bins have bad fits (their scores inflated by dead-space penalties).
    if bin_residual == bin_capacity {
        score = 60.0 + pressure * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();

        if next <= post {
            // Next item fits here afterwards: strong reward, scaled by closeness.
            score -= 60.0 * (1.0 - diff / post.max(1.0));
            if diff == 0.0 {
                score -= 80.0; // perfect 2-chain: item + next item fill the bin
            }
        } else {
            // Next item cannot use the leftover: penalize dead space slightly more.
            score += 0.15 * post;
        }
    } else {
        // Last item: only care about current fit tightness.
        score -= 10.0;
    }

    // Relative residual coupling: bins with residual far below mean are precious;
    // wasting them is bad, using them well is good.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.05 * rel * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect closure of the current bin is always great.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: mildly discourage early in the stream (consolidate),
    // encourage when open bins are mostly full (mean residual small).
    if bin_residual == bin_capacity {
        let consolidation = mean_residual / bin_capacity as f64;
        score += 20.0 * (1.0 - consolidation) * (1.0 - progress);
        score -= 15.0 * consolidation;
        // If next item is large and won't fit anywhere useful, fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Slight preference to keep bin count low.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = (bin_residual - post_residual) as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 12.0 * (next_item_size as f64 - dead);
        }
        // Very small leftovers are near-wasted space.
        if dead < 10.0 {
            score += 8.0 * (10.0 - dead);
        }
    }

    // Lookahead: reward bins that can also absorb the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only chance for the next item.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin with residual closest to item size.
        let waste = post_residual as f64;
        score += 0.05 * (waste - mean_residual).abs();
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin costs a fixed overhead; accept only if no decent fit exists.
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Slight preference for consolidating into fuller bins.
        score += 0.05 * mean_residual;
    }

    // Time horizon: early on, tolerate imperfect fits to keep bins flexible;
    // late in the stream, pack tightly since fewer future items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mild penalty per open bin to discourage sprawl.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap;
    // smooth polynomial coupling: reward tight fits, penalize large residuals
    let tight = (1.0 - fit_frac).powi(3);
    let mut score = pr - 40.0 * tight;
    // stream-progress coupling: late in stream, prefer filling existing bins more aggressively
    let late = progress * progress;
    score -= late * 25.0 * tight;
    // lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    }
    // penalize when many bins compete but this one is a poor fit
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt() * fit_frac;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // mean-residual divergence penalty
    score += 0.3 * (pr - mean_residual).abs();
    // slight bias against opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 * (1.0 - late);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of common
    // item sizes (10, 20, 25, 50) are more reusable, so reward them.
    let pr = post_residual;
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 50] {
            let q = r / m;
            let rem = r % m;
            if q >= 1 {
                // exact multiple => perfectly reusable slot
                if rem == 0 { b += 6.0 * q as f64; }
                else { b += 2.0 * q as f64 - rem as f64 / m as f64; }
            }
        }
        b
    };
    score -= harmonic_bonus(pr);

    // Penalize tiny dead space that no realistic item (>=1, but practically
    // small items are rare) can use: post_residual in 1..=5 is wasted.
    if pr > 0 && pr <= 5 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let rem2 = pr - next_item_size;
            score -= 8.0;
            score -= harmonic_bonus(rem2);
            if rem2 <= 5 { score += 6.0; }
        } else {
            // next item won't fit here; slight penalty scaled by overflow gap
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: empty bin has residual == capacity. Give it a
    // baseline score so it wins only when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            - harmonic_bonus(pr.wrapping_sub(item_size)) * 0.0
            + (mean_residual - pr as f64).abs() * 0.0
            + 40.0
            - (next_item_size as f64) * 0.1;
        // Prefer opening new bins late in the stream less (fewer items left
        // to fill them => more waste risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If many bins are open, opening yet another dilutes residuals.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Fragmentation guard: bin residual far from any harmonic class
        // is penalized mildly, pushing selection toward aligned bins.
        let frac = bin_residual as f64 / bin_capacity as f64;
        score += (0.5 - (frac - 0.5).abs()) * 4.0;
        // Tight fits are good: small post_residual relative to item size.
        if pr < item_size / 2 {
            score -= 5.0;
        }
        // Slight preference to use bins with below-mean residual (consolidate).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Modulo-3 / modulo-7 harmonic tiebreakers on post_residual for subtle
    // diversity in class assignment.
    score -= (pr % 3) as f64 * 0.3;
    score -= (pr % 7) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual > 0 && post_residual < item_size {
        // Gap too small even for the smallest future item: dead space.
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item won't fit here; residual likely wasted
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        score += 20.0 + open_bins_count as f64 * 3.0 + progress * 15.0;
    } else {
        // Mild preference for tighter existing bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        // Prefer bins below mean residual (consolidating space).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size
        score -= 25.0 * (-gap / 12.0).exp();
        // Penalize leaving residuals that are small but unusable for next item
        if post_residual > 0 && (post_residual as i64) < (next_item_size as i64) {
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
        }
        // Bonus if next item fits exactly into current bin's residual chain
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0 * fit_ratio;
    }

    // Compare residual against mean residual across open bins
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred
        score += 35.0;
        // But if few bins fit or the item is large, opening a new bin is fine
        if fitting_bins_count <= 1 || item_size >= 60 {
            score -= 40.0;
        }
        // Early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover space: mild penalty
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Time horizon: early in stream, be selective (penalize mediocre fits);
    // late in stream, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage filling them rather than opening new ones.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Compare residual to mean residual: prefer bins below mean residual (fuller bins).
    score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity && item_size > 0 {
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 20.0 * (1.0 - progress) };
        score += escape_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += poly * 40.0 * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins early; allow late in stream
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - progress) + 5.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - norm_pr);
    }

    // Lookahead synergy: if next item fits exactly in post residual
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 20.0;
    }

    // Coupling with mean residual: prefer bins below mean (consolidating space)
    score += 0.5 * (pr - mean_residual);

    // Many open bins: mild preference for fuller bins to encourage closing
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Penalize residuals that fall into awkward harmonic bands (too small to fit min item,
    // too large to waste). Classes: (0,10] dead, (10,25] tight, (25,50] medium, (50,100] loose.
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= tenth {
        score += 30.0; // dead space below min item size
    } else if pr <= fifth {
        score += 5.0; // tight but usable
    } else if pr <= quarter {
        score += 12.0;
    } else {
        score += 3.0; // loose space, likely reusable
    }

    // Modulo-arithmetic coupling: does post_residual combine with next item nicely?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward exact-ish continuation.
            let combined = pr - next_item_size;
            score -= 20.0 + (combined as f64) * 0.3;
            if combined == 0 {
                score -= 25.0; // chains perfectly
            }
        } else {
            // Next item cannot follow here; penalize if this bin would strand space.
            score += (next_item_size - pr) as f64 * 0.25;
        }
        // Harmonic divisibility: residual divisible into plausible item sizes is valuable.
        let prf = pr as f64;
        if pr > 0 {
            for k in [2u32, 3, 4, 5] {
                if pr % k == 0 && pr / k >= 10 && pr / k <= 80 {
                    score -= 2.0;
                }
            }
        }
        let _ = prf;
    } else {
        // Last item: prefer fullest packing.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate logic: only open a new bin when current residual is harmonically bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if all open bins would leave bad harmonic classes, opening is attractive.
        let bad_fit = pr > tenth && pr < quarter && next_item_size > pr;
        if bad_fit {
            score -= 45.0;
        }
        // Prefer new bin early in stream when many items remain (amortization).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // Large items deserve fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Mean-residual coupling: when mean residual is high, spread load; when low, consolidate.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Open-bin count pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fills relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if next item is large and this placement leaves little room.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but allow if all existing fits are terrible (handled by their scores).
        score += 30.0 + pressure;
    } else {
        score -= pressure.min(20.0) * 0.5;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward when the next item could still fit into the post residual (keeps chain alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Penalize dead space below the minimum plausible next item: unusable gap.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Compare post residual against mean residual: prefer bins tightened toward the mean.
    let pr = post_residual as f64;
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless the item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit = next_item_size > 0 && item_size + next_item_size >= bin_capacity;
        let desperation = fitting_bins_count <= 1;
        if !(tight_fit || desperation) {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for leaving very small unusable residues.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-full fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly
    if post_residual > 0 {
        score += 0.15 * (post_residual as f64).powf(1.3);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be stranded (bigger than post_residual but smaller than bin_capacity), slight penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into bins below mean residual (more filled)
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be conservative (penalize opening new bins less,
    // keep flexibility); late in stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, more strongly when many bins already open
        score += 20.0 + 10.0 * progress - 2.0 * (open_bins_count as f64);
        // If item is large relative to capacity, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward more as stream progresses
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with a non-linear (quadratic) dead-space term
    let mut score = pr + 20.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins fully (reward small post_residual);
    // late in stream, weight residual waste more heavily.
    let coupling = (1.0 - progress) * (-8.0 * pr_norm) + progress * (12.0 * pr_norm * pr_norm);
    score += coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 3.0 * pr_norm * progress;
        }
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Mean residual context: bins far from mean residual get slight smoothing penalty
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: make empty bin attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        score = pr + 5.0
            - (fitting_bins_count as f64) * 2.0
            + 10.0 * pr_norm * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, or >= 50) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Reward tight fits: post_residual near zero is great.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic residue classes: post_residual % 10 == 0 means grid-aligned
    // leftover, highly reusable by future items (sizes are multiples of 10
    // in classic streams). Penalize odd/awkward leftovers.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 12.0;
    } else if rem10 <= 3 || rem10 >= 7 {
        score += 6.0; // awkward sliver
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            }
            // Harmonic class of slack after hypothetical next placement
            if slack % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; leftover must stand alone.
            // If leftover is large, that's fine; if medium, mild penalty.
            if post_residual < next_item_size && post_residual >= 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap - pr + 55.0 - fill * 10.0;
        // If item is large relative to capacity, opening a fresh bin is natural
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already well-filled (fill ratio bonus)
    score -= fill * 20.0;

    // Coupling with mean residual: if this bin's post-residual is well below
    // the mean, we're reducing average fragmentation — reward it.
    if pr < mean_residual {
        score -= (mean_residual - pr).min(40.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(40.0) * 0.2;
    }

    // Many open bins: encourage closing them out (tight fits) to reduce spread
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (1.0 - fill);
    }

    // Integer-division threshold: post_residual in [10, 25] is a "half-slot"
    // class — still useful for small items, mild reward.
    if post_residual / 10 == 1 {
        score -= 5.0;
    } else if post_residual / 10 == 0 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 {
        let dead = if post_residual <= 10 {
            60.0 + (10 - post_residual) as f64 * 8.0
        } else if post_residual < 20 {
            40.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit is highly desirable.
        score -= 100.0;
    }

    // Reward tight fits generally.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize bins whose residual is much larger than needed (wasteful use).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.2;

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage closing out nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize more when open-bin pressure is high.
        score += 25.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.05;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space confirmed unusable for the next item.
        score += 15.0;
    }

    // Prefer bins below the mean residual (spreading load evenly).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += diff * 0.8;
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item would fit snugly (leaves small dead space after both placements)
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 >= 0 && post2 < 10 {
            score -= 12.0;
        }
        // Next item cannot use this bin's residual at all: penalize wasted capacity
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Tightness reward: prefer bins that end with small residuals
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Relative-to-mean coupling: avoid leaving residuals far above mean (fragmentation risk)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 15.0;
        // If no open bin fits well (large post_residual elsewhere), allow new bin:
        // approximated via mean_residual being small relative to item_size
        if mean_residual < item_size as f64 * 1.1 {
            score -= 25.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // Lookahead: if next item is huge, a fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into post-residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // chain fit is good, reward more if chain is tight
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize wasting a large bin on a small item
            score += 0.15 * nx * (post / cap);
        }
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (moderate residuals);
    // late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * tightness;
    score += (1.0 - progress) * 0.05 * post;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with low residual; few open bins -> opening new bins is cheaper.
    let open_pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.02 * open_pressure * post;

    // New-bin candidate adjustment: opening a new bin is discouraged when existing
    // bins fit reasonably well, encouraged when the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // base cost of a new bin, offset if item is large or many bins are open
        score += 20.0 - 15.0 * item_frac;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin can chain similar items
        }
        if fitting_bins_count > 0 && progress < 0.5 {
            score += 6.0 * (1.0 - item_frac); // early on, reuse open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post * (1.0 + 0.9 * progress * norm_post * (1.0 - progress));

    let mut score = poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating small dead space that can't fit typical items
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post) / 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.4 + 0.6 * progress);
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // New-bin candidate calibration: keep it slightly worse than good fits
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * progress;
    }

    // Mild pressure toward consolidating many open bins
    score += 0.15 * open_bins_count as f64 * norm_post * (1.0 - progress);

    // Coupling with mean residual across open bins
    score -= 0.5 * (mean_residual / cap - norm_post) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but avoid perfect fits being over-weighted
    // relative to placements that leave a "useful class" of space.
    score = score * score * 0.02 + post_residual as f64 * 0.8;

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Dead space = post_residual < smallest item (assume 10 baseline, but items may be 1..100).
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        // unusable dead space: heavy penalty
        score += 500.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 120.0;
    } else {
        // Harmonic classes: post_residual mod 10 determines future fillability.
        // Class 0 (residual divisible by 10) is most reusable for typical streams.
        let r = post_residual % 10;
        score -= match r {
            0 => 25.0,
            1 | 9 => 2.0,
            2 | 8 => 5.0,
            3 | 7 => 8.0,
            4 | 6 => 10.0,
            _ => 12.0, // r == 5
        };
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 40.0 * fill_ratio;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        // dumping a small item into a big residual wastes capacity
        score += 15.0 * (1.0 - fill_ratio);
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        // but if it creates dead space, soften the reward
        if post_residual > 0 && post_residual < min_item {
            score += 200.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward scaled by how much room remains after
            let after_next = post_residual - next_item_size;
            if after_next < min_item {
                score -= 80.0; // chain of two perfect-ish fits
            } else {
                score -= 20.0;
            }
        } else {
            // next item does NOT fit here: if this bin is near-empty residual
            // it's fine, but if we're leaving a bin that could have held next item
            // while this bin becomes dead, penalize.
            if post_residual > 0 && post_residual < min_item {
                score += 100.0;
            }
            // harmonic compatibility: next_item_size class vs post_residual class
            let nr = next_item_size % 10;
            let pr = post_residual % 10;
            if nr == 0 && pr == 0 {
                score -= 10.0;
            }
        }
    } else {
        // last item of stream: any placement works, prefer filling existing bins
        if bin_residual < bin_capacity {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when
    // all open bins would produce bad fits (large post_residual or dead space).
    if bin_residual == bin_capacity {
        // new bin: baseline score = capacity minus item = residual left in fresh bin
        // penalize opening new bins mildly, more when many bins already open
        score += 70.0 + (open_bins_count as f64) * 3.0;
        // but if mean residual across open bins is small (they're all full-ish),
        // a new bin is natural: reduce penalty
        if mean_residual < 20.0 {
            score -= 60.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (fill the fullest bins first, classic best-fit behavior).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff.clamp(-50.0, 50.0) * 0.5;
    }

    // Integer-division threshold on post_residual: coarse utility classes
    let util_class = post_residual / (bin_capacity / 4).max(1);
    score += match util_class {
        0 => -30.0, // residual < 25: nearly full, great
        1 => 0.0,   // 25..50
        2 => 10.0,  // 50..75: half-empty bin left behind
        _ => 20.0,  // >= 75: mostly empty, poor choice unless new bin
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..100 range)
    // are wasted. Penalize gaps below the smallest useful threshold super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual) increasingly as fit approaches perfect.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else
    // or the current fit would create dead space. Otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        // opening a new bin leaves residual = C - item; score it by that leftover,
        // but add pressure so we don't open bins while decent fits exist.
        score = (bin_capacity - item_size) as f64;
        score += open_bins_count as f64 * 3.0;
        // if next item could fill the leftover of a fresh bin, slight bonus
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
        // if this bin would be nearly full, opening is fine
        if fit_quality < 0.15 {
            score -= 10.0;
        }
        // remove last-chance benefit conflict: new bin never gets last-chance bonus
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; small extra penalty scaled by open bin count for loose fits.
    if bin_residual != bin_capacity {
        let loose = post_residual as f64 / bin_capacity as f64;
        score += loose * (open_bins_count as f64) * 1.5;
    }

    // Lookahead: if the next item fits exactly into this bin's post_residual,
    // reward placing here strongly (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin; finishing it is good.
    let this_residual = post_residual as f64;
    if this_residual < mean_residual {
        score -= (mean_residual - this_residual) * 0.3;
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact / near-exact match with next item ---
    if next_item_size > 0 {
        let next_fits = (next_item_size as i64 - post_residual as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Perfect chaining: residual exactly equals next item size
            if post_residual == next_item_size {
                score -= 60.0; // ideal: bin closes perfectly on next step
            } else {
                // Partial credit decaying with mismatch
                score -= 25.0 * (1.0 - next_fits / 100.0);
            }
        } else {
            // Dead space for the next item: penalize proportionally
            score += 0.8 * next_fits;
        }
        // If next item cannot use the leftover at all, extra penalty
        if post_residual < next_item_size {
            score += 5.0;
        }
    } else {
        // Last item: minimize waste directly
        score = post_residual as f64 * 2.0;
    }

    // --- Tightness reward: bins that become nearly full are good ---
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // --- Relative to mean residual: prefer bins below-average residual (tighter) ---
    score += 0.5 * (post_residual as f64 - mean_residual);

    // --- Last-chance bin: strongly prefer using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + progress);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, cheaper only if current bins are very fragmented
        score = 100.0
            - 20.0 * mean_residual / bin_capacity as f64
            + 10.0 * (post_residual as f64 / bin_capacity as f64);
        // Late in stream, prefer closing existing bins over opening new ones
        score += 30.0 * progress;
        // If many bins fit the item, opening new is rarely worth it
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Small tie-break favoring fewer open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize wasting a large residual on a small item (dead space).
    let fill = item_size as f64 / bin_residual as f64;
    if fill < 0.5 {
        score += 8.0 * (0.5 - fill);
    }

    // Last fitting bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Extra reward if next item nearly fills the leftover space.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * next_fill;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // Slightly penalize leaving a sliver the next item can't use.
            score += 3.0;
        }
    } else {
        // Last item in stream: prefer tightest packing.
        score -= 5.0;
    }

    // Time horizon: early in stream, mildly prefer consolidating into open bins;
    // late in stream, weight residual waste more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Global residual pressure: if mean residual is high, encourage filling bins.
    score -= 0.05 * mean_residual;

    // Slight preference for fuller bins overall.
    score += 0.1 * (bin_residual as f64 - post_residual as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * progress) - pr_norm * (0.3 + 0.7 * (1.0 - progress));
    score += 40.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize leaving residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (post_residual - next_item_size).min(item_size) as f64 / bin_capacity as f64;
        } else {
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 3.0 * (open_bins_count as f64).ln() * mean_norm * (1.0 - progress);

    // New-bin candidate: prefer opening a fresh bin when existing fits are wasteful
    if bin_residual == bin_capacity {
        score -= pr + 8.0 * (1.0 - progress) - 4.0 * progress;
        if fitting_bins_count > 0 {
            let best_waste = pr.min(40.0);
            if best_waste < 12.0 {
                score += 20.0; // existing bins fit well; don't open new
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item-size blocks (5,10,20,25,50) are valuable.
    let post = post_residual;
    let mut harmonic_bonus = 0.0;
    if post > 0 {
        if post % 50 == 0 { harmonic_bonus += 12.0; }
        else if post % 25 == 0 { harmonic_bonus += 8.0; }
        else if post % 20 == 0 { harmonic_bonus += 6.0; }
        else if post % 10 == 0 { harmonic_bonus += 4.0; }
        else if post % 5 == 0 { harmonic_bonus += 2.0; }
        // Small unusable dead space is penalized harshly via integer-division thresholds.
        if post < 10 { harmonic_bonus -= 15.0; }
        else if post < 20 { harmonic_bonus -= 5.0; }
    } else {
        // Perfect fill is the best outcome.
        harmonic_bonus -= 25.0;
    }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly (or nearly) into post_residual,
    // strongly reward this placement (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            if slack % 10 == 0 { score -= 6.0; }
            score -= 4.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; slight penalty scaled by how far off it is.
            score += ((next_item_size - post) as f64) * 0.05;
        }
    } else {
        // Last item: prefer tightest fill.
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (mean residual low relative to typical item sizes) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit = mean_residual / cap;
        let new_bin_penalty = 8.0 + 20.0 * mean_fit + 10.0 * (1.0 - progress);
        score += new_bin_penalty;
        // If no open bin can fit, opening is inevitable-ish; soften penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Fraction-of-capacity threshold on post_residual: keep scores in a sane band.
    let frac = post as f64 / cap;
    score += 3.0 * (frac - (frac * 4.0).floor() / 4.0) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are effectively wasted capacity.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Perfectly tight fit is great; unusable sliver is penalized heavily.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (post residual close to zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward residuals that can still host a plausible future item
    // (align with next item size lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // This bin's leftover can't fit the next item: mild penalty,
        // stronger if it's a dead sliver.
        score += 5.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few open bins, opening a new bin is relatively cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * 1.5 + progress * 5.0;
    if bin_residual == bin_capacity {
        // Candidate new bin: baseline plus pressure; also compare against
        // mean residual — if open bins are mostly full, a new bin is fine.
        score = 55.0 + bin_pressure - mean_residual * 0.3;
        // If this item alone nearly fills a bin, new bin is attractive.
        if item_size >= 90 {
            score -= 20.0;
        }
    } else {
        // Fitting into an existing bin reduces open-bin pressure slightly.
        score -= bin_pressure * 0.15;
    }

    // Mild preference for bins with below-average residual (fuller bins),
    // classic best-fit flavor.
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with mild nonlinearity.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack / 10.0); // graded chain reward
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            score += 8.0 / (1.0 + overshoot / 10.0); // mild penalty for blocking chain
        }
    }

    // Compare post_residual against mean residual: leaving below-average waste is good.
    if mean_residual > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space (< 10) that likely becomes unusable,
    // unless it exactly matches the lookahead item.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // New-bin candidate: only attractive late in the stream or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        if next_item_size >= 70 {
            score -= 20.0; // big lookahead item may deserve fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), shaping time-dependent aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fit quality: 0 = perfect fill, 1 = item just barely fit.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let residual_norm = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (subtract more for smaller post-residual),
    // with a superlinear penalty on wasted space.
    score += residual_norm * residual_norm * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item could exactly use this bin's post-residual,
    // reward this placement; if the next item would be stranded by a large leftover,
    // penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fill
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; small leftover is less harmful.
            score += residual_norm * 5.0;
        } else {
            // Next item fits but leaves more fragmentation; penalize proportional
            // to the new dead space it would create.
            let chain_waste = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score += chain_waste * 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate,
    // prefer filling existing bins over opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost high; discount when pressure is high
        // (open bins are full-ish, so a fresh bin is reasonable) or when the
        // item is large and no tight fit exists.
        score = bin_capacity as f64 * 0.9;
        score -= pressure * 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits, must open
        } else if fit_ratio > 0.6 {
            score -= 10.0; // large items tolerate fresh bins
        } else {
            score += 15.0 * (1.0 - progress); // early on, avoid bin proliferation
        }
    } else {
        // Existing bin: reward when global residual is high (encourage closing gaps).
        score -= pressure * 10.0;
        // Mild bonus for bins that are already committed (low residual).
        score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;
    }

    // Small stochastic-free tiebreaker: prefer lower-index-equivalent via
    // residual ordering; tiny perturbation to break exact ties toward tighter bins.
    score += (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: waste grows super-linearly with residual
    let waste = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);
    score += 40.0 * waste;

    // Stream progress interaction: early on, tolerate imperfect fits; late, punish them
    let progress_coupling = (1.0 - t) * (1.0 - t) * 8.0 - t * t * 6.0;
    score += norm_pr * progress_coupling;

    // Reward tight fits (small post_residual) with smooth decay
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize leaving residual too small for next item, reward exact match
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 6.0 * fit_quality;
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mean residual context: prefer bins near the mean to keep bin states balanced
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Crowding pressure: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Perfect fit gets a massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that fall into "harmonic" small classes (likely reusable).
    match post_residual {
        0 => { score -= 50.0; }
        r if r <= quarter / 2 => { score -= 30.0; }   // tiny dead space, nearly full
        r if r <= quarter => { score -= 10.0; }
        r if r < half => { score += 15.0; }           // awkward half-ish leftover
        _ => { score += 25.0; }                        // large leftover: wasteful placement
    }

    // Modulo-arithmetic coupling: if post_residual is divisible by common item
    // size classes (10, 20, 25, 50), future items may exactly fill it.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use this bin's leftover; penalize large leftovers.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the item
    // is large relative to a fresh bin and open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // If item is big and open bins are nearly full on average, new bin is fine.
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.2 * (item_size as f64 / 100.0) {
            score -= 35.0;
        }
    }

    // Mild stream-phase adaptation: later in the stream, consolidate harder.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * 5.0;

    // Tie-break: prefer bins whose residual is close to the mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Unusable sliver: heavy penalty scaled by how useless it is.
            score += (10.0 - pr) * 8.0;
        } else if pr < 20.0 {
            // Likely dead space for typical item sizes.
            score += (20.0 - pr) * 3.0;
        } else {
            // Larger leftovers remain usable: mild reward for tight fits.
            score -= (bin_capacity as f64 - pr) * 0.15;
        }
    }

    // Perfect fit is strongly preferred.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // Next item fits after this placement: mildly reward.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Next item cannot use the sliver: penalize further.
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Default mild penalty so good existing fits win.
        score += 25.0;
        // But if the current bin is a poor fit (large dead space) and many bins are open,
        // opening a fresh bin becomes more attractive.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Early stream: be slightly more willing to open bins (build structure early).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= (1.0 - progress) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * (20.0 + 40.0 * progress);

    // 2-step lookahead: strongly reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much slack remains after it
            let after_next = post_residual as f64 - nr;
            score -= 30.0 * (1.0 - after_next / bin_capacity as f64);
            // extra bonus if after_next can chain with typical residuals
            if after_next <= mean_residual {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: penalize, especially if this creates dead space
            let dead = nr - post_residual as f64;
            score += 10.0 + dead.min(40.0);
        }
    }

    // Compare against mean residual: bins below mean residual are "tighter" than average,
    // favor packing into them to consolidate space.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when reasonable fits exist, more so late in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 15.0 + 10.0 * progress + open_f.min(20.0);
        // But allow a new bin if no open bin fits well (post_residual would be tiny/dead).
        if bin_residual >= item_size && post_residual < 10 && next_item_size > post_residual {
            score -= 30.0;
        }
    }

    // Small penalty for very small residual leftovers that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins well (post_residual small relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize small dead space that nothing can use (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size > bin_residual {
            // next item can't fit here anyway; mild bonus for consuming this bin
            score -= 5.0;
        } else {
            // next item fits now but not after placement: penalize blocking
            score += 10.0;
        }
    }

    // Time horizon: early in stream, be conservative (prefer new bins when fit is poor);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 0.5 + 1.5 * progress;
    score *= consolidation;

    // Many open bins: encourage closing them out (use existing bins).
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0) * 2.0;
    }

    // Global state coupling: prefer bins below mean residual (balance residuals upward).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5;
        if poor_fit || progress < 0.2 {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // in [0, 1]
    let prog_sq = progress * progress;
    let prog_cube = prog_sq * progress;

    // Base: raw post residual, weighted by progress (later => waste matters more)
    let mut score = post * (0.5 + 0.5 * prog_sq);

    // Smooth polynomial interaction: penalize large residuals early, reward tight fits late.
    score += 20.0 * norm_post * (1.0 - norm_post) * (1.0 - progress);
    score -= 15.0 * norm_post * norm_post * prog_cube;

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness * (0.3 + 0.7 * progress);

    // Mean residual coupling: penalize bins far below mean residual (avoid fragmentation).
    score += 0.3 * (mean_residual - post).abs() * (1.0 - prog_sq);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 * (1.0 - post / cap);
    }

    // New-bin candidate: mildly penalize opening new bins early, less late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 5.0 * prog_cube;
    }

    // Slight penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * prog_sq;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class A: perfect fit -> strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: tiny dead space (<=10% capacity) -> reward
    else if post_residual <= bin_capacity / 10 {
        score -= 50.0;
    }
    // Class C: dead zone 11..30% -> penalize (hard to fill)
    else if post_residual <= bin_capacity * 3 / 10 {
        score += 40.0;
    }
    // Class D: mid zone 31..60% -> mild penalty
    else if post_residual <= bin_capacity * 6 / 10 {
        score += 10.0;
    }
    // Class E: large residual (>60%) -> mildly favorable
    else {
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: leftovers that match common item sizes
    // (small items 1..=20 are common in unknown streams)
    let common_mods: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    for &m in common_mods.iter() {
        if post_residual >= m && post_residual % m == 0 {
            score -= 15.0; // residual is exactly fillable by a future common item
            break;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // next item fits; residual class after next placement
            let pr2 = post_residual - next_item_size;
            if pr2 <= bin_capacity / 10 {
                score -= 30.0;
            } else {
                score += (pr2 as f64) * 0.2;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to dead space
            score += (next_item_size as f64 - pr) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin gives a decent fit and item is large
        let item_frac = item_size as f64 / cap;
        if fitting_bins_count > 0 {
            // some open bin fits: make new bin less attractive unless item huge
            score += 60.0 * (1.0 - item_frac);
        } else {
            // no open bin fits: new bin is the only option
            score -= 100.0;
        }
        // late in stream, prefer filling existing bins slightly more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual deviates badly from mean, nudge
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for tighter bins overall (best-fit baseline)
    score += frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but typical small item threshold) are pure waste. Penalize gaps
    // that are too small to ever be useful with a superlinear penalty.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (small post_residual) more aggressively.
    if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 15 {
        score -= 3.0;
    }

    // Penalize leaving a gap that exactly wastes a large chunk without fitting
    // the lookahead item: if next item can't use post_residual, it's dead space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.5;
    }
    // Reward if lookahead item fits into the resulting residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; add mild penalty scaled by open_bins_count so
    // new bins are avoided unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: empty bin gets a baseline cost so it only wins when
    // existing fits are poor (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + open_bins_count as f64 * 0.05;
        // Allow new bin if current open bins are nearly full on average.
        if mean_residual < 12.0 {
            score -= 25.0;
        }
    }

    // Slight tie-break: prefer bins with residual close to item_size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to fill
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Tightness of current placement: small post_residual relative to capacity is good
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Compare residual against mean residual across open bins:
    // leaving residual far above the mean wastes space; penalize
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: if this is the only bin that fits, favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        // if next item pairs with a fresh bin, soften the penalty
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Early in stream, prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_efficiency = next_item_size as f64 / bin_capacity as f64;
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (1.0 + lookahead_efficiency);
    }
    // Penalize post-residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deadness = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 8.0 * deadness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter fits: penalize large wasted fraction relative to mean residual.
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 4.0 * fit_ratio;

    // Global state coupling: when bins are plentiful and residuals are high,
    // be pickier; when bins are scarce, be more permissive.
    let scarcity = 1.0 / (1.0 + open_bins_count as f64);
    score -= 3.0 * scarcity * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;

    // Time horizon: early in the stream, be conservative (penalize fragmentation);
    // late in the stream, exploit remaining space aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 2.0 * ((bin_capacity - post_residual) as f64 / bin_capacity as f64);

    // Mean-residual anchoring: bins already far below average residual are
    // "used up"; prefer bins whose post-residual stays near the mean.
    score += 1.5 * (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score = bin_capacity as f64 * 0.85;
        // If the item nearly fills a fresh bin, opening is very good.
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.7 { score -= 30.0 * (fill - 0.7); }
        // If lookahead also fits nicely in the fresh bin, encourage opening.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in stream, opening new bins is less costly than fragmentation.
        score -= 10.0 * progress;
        // Many open bins with large residuals: prefer reusing them.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 8.0 * p2 * (post / cap);
    score -= 6.0 * p3 * (post / cap) * (post / cap);
    // Smooth dead-space penalty: quadratic in post_residual, modulated by progress
    let dead = (post / cap).max(0.0);
    score += 12.0 * dead * dead * (0.5 + 0.5 * progress);
    // Tight fit reward (small post residual), stronger late in stream
    score -= 10.0 * (1.0 - dead).max(0.0) * (1.0 - dead) * (0.3 + 0.7 * p2);
    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }
    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 7.0 * fit_quality * fit_quality;
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }
    // Mean residual deviation: penalize bins far from mean (smooth coupling)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;
    // Mild preference against spreading across many open bins late
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * progress;
    // New-bin candidate: smooth penalty so it is chosen only for large items
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - item_size as f64 / cap) - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fractions of capacity
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward residuals in harmonically useful classes: 0, 1/4, 1/2, 3/4
    let harmonics = [0.0f64, 0.25, 0.5, 0.75];
    let mut harmonic_bonus = 0.0f64;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.02 {
            harmonic_bonus = 12.0 * (1.0 - d / 0.02);
        }
    }
    score -= harmonic_bonus;

    // Penalize tiny dead space (unusable slivers): post_residual in 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: divisibility classes
    if post_residual % 10 == 0 {
        score -= 6.0; // residual aligns with item granularity decade
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Perfect fit
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / cap;
            // reward if next item leaves another harmonic residual
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 8.0;
            }
            // penalize if next item won't fit anywhere else well
            let _ = nxt_frac;
        } else {
            // next item cannot go here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly early, more when many open bins have slack
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 18.0 + 20.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits, must open
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (frac);

    // Penalize leaving residuals smaller than the minimum item size (1..100 unknown, use ~10 heuristic guard)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving a gap that is just barely too small for the lookahead item
    // (would have been nice to keep room for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening them
    // rather than spreading; when few are open, be more selective.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-average residual (tighter bins) for good fits.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 5.0 * fitting_bins_count as f64 };
        score += pressure;
        // Late in the stream, opening a fresh bin is cheaper than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post-residual, this is a perfect pairing -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits into leftover space: reward closeness of fit.
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item would not fit here; penalize wasted residual,
            // scaled by how much space is stranded.
            let stranded = post_residual as f64;
            score += 0.5 * stranded;
            // Extra penalty if the stranded space is small (unusable dead space).
            if stranded < 10.0 {
                score += 25.0;
            }
        }
    }

    // Penalize bins whose residual is already far below the mean
    // (they are nearly full; prefer spreading load into emptier bins
    // unless the fit is very tight).
    let mean_gap = mean_residual - bin_residual as f64;
    if mean_gap > 0.0 {
        score += 0.15 * mean_gap;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // well (many fitting bins => prefer reusing one of them).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Open bins exist that fit: make new bin unattractive.
            score += 70.0 + 10.0 * fitting_bins_count as f64;
        } else {
            // Must open a new bin anyway; slight preference baseline.
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild bonus for using bins when many are open (limit bin proliferation).
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize leaving dead space that no plausible item (>=1, typical small) can use.
    if post_residual > 0 {
        score += 0.6 * (post_residual as f64).powf(1.4);
    }

    // Perfect or near-perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 - 0.15 * slack_after_next as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: if many bins are open with large mean residual, prefer
    // filling existing bins over opening new ones.
    if open_bins_count > 0 {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score -= 4.0 * mean_tight;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 1.2 + 10.0;
        // Worth opening a new bin if existing bins are all poor fits
        // (item barely fits somewhere) or no bins fit at all.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            // Large item with few options: opening fresh bin is often better
            // than fragmenting a partially-filled bin.
            score -= 30.0;
        }
        // Late in stream, discourage spreading into new bins.
        score += 20.0 * progress;
        // If next item is small, a fresh bin has good future utility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mild preference for keeping number of open bins low when residuals are small.
    if open_bins_count > 3 && post_residual > 0 && post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * prn) * (1.0 + progress);

    // Smooth non-linear coupling: large residuals are less wasteful early, worse late
    score += 40.0 * prn.powi(2) * (0.5 + progress);

    // Reward tight fits with a smooth sigmoid-like term
    let tightness = 1.0 - prn;
    score -= 30.0 * tightness.powi(3);

    // Last-chance bonus (only one fitting bin): smooth cubic reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: penalize if next item fits poorly in the resulting residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild pull toward bins near the mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for consolidating when many bins are open
    score += 0.5 * open_bins_count as f64 * prn;

    // New-bin candidate handling: neutral-ish, slightly penalized early, competitive late
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that commonly pair with
    // small items (1..=20) are "usable"; large odd residues are dead space.
    let r = post_residual;
    let class = match r {
        0 => 0.0,              // perfect fit — golden
        1..=20 => 5.0,         // highly reusable residue class
        21..=40 => 15.0,       // moderately reusable
        41..=60 => 30.0,       // marginal
        _ => 50.0,             // dead-space class
    };
    score += class;

    // Integer-division threshold: residue divisible by 10 packs cleanly
    // with the 10..80 grid; reward it.
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    } else if r % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let nxt_res = r - next_item_size;
            score -= 15.0;
            // penalize leaving an awkward residue after the follow-up item
            if nxt_res % 10 != 0 && nxt_res < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot follow here; slight penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alt = (mean_residual - item_size as f64).abs() > 25.0;
        if poor_alt || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
    } else {
        // Prefer tighter existing bins: reward small bin_residual relative to mean.
        score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.4;
    }

    // Perfect fit dominates everything.
    if r == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size ~1..10) are pure waste.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // unusable sliver: heavy penalty proportional to how "full" the bin is
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 40.0;
    } else {
        // prefer tight-but-usable fits: reward small usable residuals
        score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Reward bins whose residual closely matches the item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward if next item exactly fills the leftover
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover too small for next item: mild penalty, encourages saving space
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already plentiful on average.
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "lone" tight bin — using it keeps mean residual high for others.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive late in the stream or when item is
    // large and no open bin is tight; penalize mildly so open bins win by default.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 1.5;
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Slight stream-progression modulation: early on, be conservative with
    // opening bins; late, allow more freedom (score noise-free deterministic).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        // Perfect chain fit: post_residual == next_item_size -> strong reward.
        let gap = (post - nxt).abs();
        score -= 12.0 * (-gap / 8.0).exp();
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit here, mildly penalize leaving a big unusable gap.
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that deviate upward from the mean residual (wasteful bins).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Tight fits are good: reward small post_residual relative to item size.
    if post_residual <= 5 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make empty bin slightly costly
    // so it's chosen only when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        // If lookahead chains perfectly into a fresh bin (item + next <= capacity), allow it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit into the post-residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain possible: reward proportional to how well next item uses leftover
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer minimizing post_residual
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless no good option
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If many bins fit the item, discourage new bin
        if fitting_bins_count > 1 {
            new_bin_penalty += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, allow new bins more freely (horizon effect)
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty *= 0.5 + progress;
        // If mean residual is high, open bins are fragmented; new bin less bad
        new_bin_penalty -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // Large items relative to capacity favor fresh bins
        new_bin_penalty -= (item_size as f64 / bin_capacity as f64) * 15.0;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins whose residual is close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference to fill bins with more items already (fewer open bins)
    score += 0.02 * open_bins_count as f64;

    // Slight penalty for very large leftover gaps that likely become dead space
    if post_residual > 50 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: minimize post residual, with non-linear shrink of large residuals
    let mut score = post * (1.0 + 0.8 * (post / cap).powi(2));

    // Reward tight fits: smooth coupling of fill ratio with progress
    let fill = item / cap;
    score -= 30.0 * fill.powi(3) * (0.5 + progress);

    // Penalize dead space that no future item can use (post < 10)
    if post < 10.0 && post > 0.0 {
        score += 15.0 * (1.0 - post / 10.0);
    }

    // Lookahead: reward if next item fits in the post residual (chaining)
    if nxt > 0.0 && nxt <= post_residual as f64 {
        let chain_fit = 1.0 - (post - nxt) / cap;
        score -= 20.0 * chain_fit * (1.0 + progress);
    } else if nxt > post_residual as f64 {
        // penalize residuals that block the next item slightly
        score += 5.0 * (nxt - post) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize mildly, more when many bins are open and residuals are usable
    if bin_residual == bin_capacity {
        let avg_usability = 1.0 - (mean_residual / cap).powi(2);
        score += 10.0 + 8.0 * avg_usability * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer bins below mean residual (concentrate filling)
        score += 4.0 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits: post residual in "dead zone" (very small) is great
    if post_residual <= 4 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize residuals that no future item (min size 1, typical >=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Harmonic class via integer division thresholds on post_residual
    let class = post_residual / 25; // 0..4 harmonic class of residual size
    score -= match class {
        0 => 15.0,           // 0..24: near-full bin, excellent
        1 => 5.0,            // 25..49: decent
        2 => 0.0,            // 50..74: neutral
        _ => -3.0,           // 75..100: mostly empty, prefer fresh fill
    };

    // Modulo arithmetic on residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) remain "harmonic" and reusable
    if post_residual > 0
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0)
    {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use this bin's remainder; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: avoid opening a new bin if this one fits reasonably
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when it will be well used
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a good existing fit,
        // but better than fragmenting many bins
        score += 12.0;
        // Late in stream or many open bins: prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
        // If next item is large and no open bin is roomy, new bin is fine
        if next_item_size >= 60 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild preference for filling bins below mean residual (balance avoidance)
    score -= (mean_residual - pr) * 0.05;

    // Small tie-break favoring earlier bins implicitly via residual ordering
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    if post_residual > 0 {
        // Smallest plausible item is 1, but small gaps (< ~10) are effectively dead space.
        if post_residual < 10 {
            score += 40.0 + 4.0 * (10 - post_residual) as f64;
        } else if post_residual <= 20 {
            // Moderate gap: partially wasted potential, mild penalty.
            score += 0.35 * (20 - post_residual) as f64;
        }
    }

    // Reward very tight fits (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize new bins) and prefer filling bins with larger residual first.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive when few bins open or item is huge.
        let big_item_bonus = if item_size > 50 { 15.0 } else { 0.0 };
        score += 55.0 + 12.0 * open_bins_count as f64 - big_item_bonus - 20.0 * progress;
    } else {
        // Slight preference for bins whose residual deviates from mean (harmony bonus).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 8.0 / (1.0 + dev);
    }

    // Lookahead: if the next item can exactly use the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit in the leftover: leftover likely dead space.
        score += 6.0;
    }

    // Prefer filling bins with small residual (larger item_size relative to residual).
    score -= 0.25 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.4 * waste;
    }

    // Reward residual that can still fit the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Penalize post_residual close to mean residual (indiscriminate placement);
    // prefer bins whose resulting residual deviates usefully.
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already quite full (tight packing).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Penalize new-bin candidate slightly so it is chosen only when clearly better.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits well, opening a new bin is fine.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity consumed by placing the item here
    let fill = item_size as f64 / bin_capacity as f64;

    // Tight fits are excellent: strongly reward small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 * (-tightness).exp();

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward filling bins deeply early, but near the end prefer conserving residual
    score -= fill * (1.0 - progress) * 20.0;
    score += fill * progress * 5.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next fits but leaves more fragmentation: mild reward scaled by fit quality
            let nxt_fit = (post_residual - next_item_size) as f64 / (post_residual as f64 + 1.0);
            score -= 18.0 * (1.0 - nxt_fit);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    score += pressure * 4.0;

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a decent fit (large item relative to residuals) or stream is early
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // cheaper to open a new bin when item is large and would leave tiny residuals elsewhere
        let waste_elsewhere = (bin_residual - item_size) as f64; // == post_residual for new bin too
        if next_item_size > 0 && next_item_size > waste_elsewhere {
            score -= 30.0;
        }
        if progress < 0.15 {
            score -= 10.0;
        }
        // if many bins fit already, opening new is wasteful
        if fitting_bins_count > 2 {
            score += 15.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    }

    // Small dynamic noise-free tiebreaker keyed on step progression for deterministic diversity
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Core: quadratic waste penalty (dead space grows quadratically in cost)
    let mut score = norm_post * norm_post * 120.0 + norm_post * 40.0;

    // Smooth non-linear coupling with stream progress:
    // late in stream, tighten fits more aggressively (larger effective penalty slope)
    let late = progress * progress;
    score += late * norm_post * 60.0;

    // Reward filling a bin nearly full (post_residual near 0) with a smooth valley
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * tightness * 30.0;

    // Lookahead: bonus if next item fits into post_residual (smooth exponential affinity)
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap);
        score -= 25.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by overflow amount
        let overflow = (next_item_size as f64 - post) / cap;
        score += 15.0 * overflow * overflow;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize by remaining capacity, more so early when
    // consolidation into existing bins is cheap; relax slightly late in stream
    if bin_residual == bin_capacity {
        let base = 90.0 - 25.0 * progress;
        // also discourage hoarding bins when many are already open
        score = base + 0.5 * open_bins_count as f64 + norm_post * 30.0;
    }

    // Mild alignment with mean residual: prefer bins whose post-residual
    // moves the mean toward compactness (smooth interaction)
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_post - mean_norm) * (norm_post - mean_norm) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small, hard-to-fill" residue classes are penalized, since dead space
    // in classes that few future items can fill is wasted capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Integer-division thresholds: classify post_residual into harmonic bands.
    let band = post_residual / 10; // 0..=10 bands
    let band_penalty = match band {
        0 => -6.0,   // near-perfect fit: reward strongly
        1 => -3.0,   // excellent fit
        2 => -1.0,
        3 => 0.5,
        4 => 1.5,
        5 => 2.5,    // half-empty: mediocre
        6 => 3.0,
        7 => 4.0,
        8 => 5.0,
        9 => 6.0,
        _ => 0.0,    // full bin (no placement effect) — neutral
    };
    score += band_penalty;

    // Non-linear coupling: penalize residuals that are "lonely" — no small
    // item class (1..10) can fill them exactly. Use modulo arithmetic:
    // residuals where pr % k == 0 for small k are more reusable.
    let mut divisibility_bonus = 0.0;
    if post_residual > 0 {
        for k in 2..=10u32 {
            if post_residual % k == 0 {
                divisibility_bonus += 0.4;
            }
        }
    }
    score -= divisibility_bonus;

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or nearly, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 8.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow into this bin: mild penalty proportional
            // to how far off it is, scaled by how much capacity fraction remains.
            let over = (next_item_size - post_residual) as f64;
            score += 1.5 * (over / cap) * (0.5 + frac);
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 5.0 * (1.0 - frac);
    }

    // New-bin candidate handling: a fresh empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when current fits are all poor (large post
        // residuals relative to capacity) — i.e. when mean residual is high
        // and this item would leave a big hole.
        let poor_fit_pressure = (pr / cap).powi(2) * 20.0;
        // Base cost of a new bin: encourage consolidation early, allow new
        // bins later in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_cost = 8.0 + 6.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        // If mean residual across open bins is large, new bin is more attractive.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = new_bin_cost + poor_fit_pressure * (1.0 - fragmentation) - 4.0 * fragmentation;
    }

    // Slight preference for tighter bins overall (best-fit flavor) via
    // coupling with mean residual.
    score += 0.5 * (pr - mean_residual).signum() * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible future item (>=10)
    // are pure waste; penalize them super-linearly.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) <= dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Non-linear coupling: moderate gaps that can't host the lookahead item are risky.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > dead_threshold as u32 {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual context: penalize bins deviating from fleet mean residual (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor and fleet is fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 20 { 1.0 } else { 0.0 };
        score += 55.0 - 30.0 * poor_fit * mean_residual / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose residual after placement
    // matches the next item size well (chained packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        if post_residual as i64 == next_item_size as i64 {
            score -= 150.0;
        }
        // Penalize leaving residual that is too small for the next item
        // (dead space), unless it is near zero.
        if post_residual < next_item_size && post_residual > 8 {
            score += 0.8 * (post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins that are already well-filled
    // (residual below average) to consolidate waste.
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // opening fresh bin can help future big items
        }
    }

    // Progression: as stream advances, be slightly more conservative
    // about spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), non-linearly amplified.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Lookahead cannot fit here -> residual likely wasted.
            let waste = (next_item_size as f64 - post_residual as f64).min(40.0);
            score += 0.35 * waste;
        } else {
            // Lookahead fits into the post-residual: chain reward.
            let slack = (post_residual as f64 - next_item_size as f64).min(30.0);
            score -= 0.5 * (30.0 - slack) * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where the item fits most snugly anyway.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already relatively full (large used fraction).
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used_frac;

    // Slight preference to keep mean residual spread balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, be greedier about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Penalize having too many open bins when residual is small (fragmentation).
    if post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: make it moderately attractive only when
    // the item fits poorly everywhere else. A fresh bin leaves residual
    // equal to capacity - item_size; score it neutrally-high so tight fits win.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // fresh bin can also host the lookahead item
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // no open bin fits: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.9 * pr_norm) * (0.7 + 0.6 * progress);

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= 12.0 * (1.0 - pr_norm).powi(3) * fit_norm;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // Lookahead coupling: penalize leaving residuals that cannot host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (pr / nxt).ln().max(0.0) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual interaction: prefer bins deviating from the mean when crowded
    score += 2.5 * ((pr - mean_residual) / cap).abs() * (open_bins_count as f64).ln().max(1.0) * progress;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - 0.5 * progress) + 4.0 * (open_bins_count as f64).ln().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" classes.
    let post_class = post_residual % 10;
    // Small residues (0,1,2) mean near-perfect fill; reward them.
    if post_class == 0 {
        score -= 30.0;
    } else if post_class <= 2 {
        score -= 15.0;
    } else if post_class >= 8 {
        // Large residue class: leftover space is awkward; penalize.
        score += 12.0 + 2.0 * post_class as f64;
    }

    // Integer-division thresholds on post_residual: classify leftover size.
    let leftover_class = post_residual / 10; // 0..=9
    score += leftover_class as f64 * 3.0;

    // Lookahead coupling: can next_item_size fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains into this bin: strong reward, scaled by tightness.
            let tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 20.0 + 25.0 * tightness;
            // Harmonic match: same class residues chain well.
            if next_item_size % 10 == post_class {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this leftover: penalize dead space proportionally.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * dead * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimizing residual as much as possible.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin starts with high base cost.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 + 55.0;
        // Opening a new bin is attractive when open bins are crowded (low mean residual)
        // or many bins already fit the item elsewhere.
        let crowd_bonus = if mean_residual < 25.0 { 20.0 } else { 0.0 };
        let mut nb = base + 2.0 * post_residual as f64 - crowd_bonus;
        if next_item_size > 0 && next_item_size <= post_residual {
            // A fresh bin can chain the next item: reduce its cost.
            nb -= 18.0;
        }
        if fitting_bins_count == 1 {
            nb += 25.0; // prefer squeezing into the last fitting bin instead.
        }
        // Late in stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * progress;
        score = nb;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (size >= 1, but practically small gaps < 10 are near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates far below the mean (they are the scarce space);
    // prefer consuming bins with large residual only if the fit is tight.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage opening another one.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well (this call would only be lowest when others are bad),
        // allow new bin when item is large relative to capacity.
        if item_size > 70 {
            score -= 20.0;
        }
    } else {
        // Slight reward for using existing bins as open_bins_count grows.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Lookahead: if the next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits but not quite, penalize creating that near-miss gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 10.0;
    }

    // Late in the stream, prioritize closing bins out (perfect fits) even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills this bin afterwards.
            let diff = (post - next_f).abs();
            score -= 18.0 * (1.0 - diff / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item cannot reuse this residual: penalize proportionally to waste.
            score += 6.0 * (next_f - post) / next_f;
        }
        // Coupling with mean residual: prefer bins that deviate usefully from average.
        score += 0.25 * (post - mean_residual);
    }

    // Penalize creating tiny dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow opening when all fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, consolidate tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (low post residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // if post residual is small enough to be "dead" (< smallest item), extra reward.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64));
        } else if post_residual < 10 {
            score -= 6.0; // near-perfect closure
        } else {
            // dead space that likely can't host next item: mild penalty scaled by size
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and can fit;
    // the penalty fades if the item is large relative to mean residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let base_penalty = if open_bins_count > 0 { 30.0 } else { 0.0 };
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += base_penalty - 0.3 * mean_gap;
        // late in the stream, opening fresh bins is less costly (fewer future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins with above-average residual (drain the spread).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score -= 12.0 * norm_pr * norm_pr * (1.0 - t);
    score += 8.0 * norm_pr * t;
    // penalize large dead space non-linearly
    score += 0.02 * pr * pr / cap;
    // reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 30.0) * (-gap / 30.0);
    } else {
        score -= 5.0 * norm_pr;
    }
    // crowd penalty relative to mean residual
    score += 0.1 * (pr - mean_residual) * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division thresholds
    let post = post_residual;
    let post_class = post / 10;              // integer-division class
    let post_mod = post % 10;                // fine residue

    // Penalize dead space in awkward harmonic classes (residuals that few items fit)
    // Classes with residual < 10 are near-wasted; classes 1..=9 are "harmonic slots"
    if post == 0 {
        score -= 30.0; // perfect closure: excellent
    } else {
        // dead-space penalty grows when residual is small but nonzero
        if post < 10 {
            score += 25.0; // unusable sliver
        } else {
            // reward residuals that are harmonic with common item sizes (multiples of 10)
            if post_mod == 0 {
                score -= 12.0;
            } else if post_mod <= 3 || post_mod >= 8 {
                score += 6.0; // awkward fractional fit
            }
            // mid-range classes (post_class 3..=5, i.e. 30..59) are prime slots
            if post_class >= 3 && post_class <= 5 {
                score -= 10.0;
            } else if post_class >= 7 {
                score += 4.0; // large leftover means we barely helped this bin
            }
        }
    }

    // Lookahead coupling: does post_residual still admit next_item_size?
    if next_item_size > 0 {
        if post >= next_item_size {
            // reward leaving room for the next item, scaled by how snugly it fits
            let slack = (post - next_item_size) as f64;
            score -= 8.0 + 0.15 * slack;
            // harmonic bonus: post - next leaves a multiple-of-10 residue
            if (post - next_item_size) % 10 == 0 {
                score -= 7.0;
            }
        } else {
            // this bin dies for the next item; penalize unless post==0 (closed)
            if post > 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (low mean residual) and many bins are open.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // cheaper to open when existing bins are nearly full
        score -= 0.5 * (100.0 - mean_residual);
        // cheaper when many bins already open (amortization of consolidation loss)
        score -= 0.3 * open_bins_count as f64;
        // early in stream, opening bins is fine; late, avoid fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // slight preference for tighter existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // prefer bins whose residual was already low (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space" — penalize them nonlinearly.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect fill of the bin (item exactly fills residual).
    if post_residual == 0 && bin_residual == item_size {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // penalize candidates less when bin count is low (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    score += pressure;

    // New-bin candidate (empty bin): discourage unless this bin is the last
    // chance or the fit is poor everywhere / next item needs the space.
    if bin_residual == bin_capacity {
        let last_chance = fitting_bins_count == 1;
        let poor_fit = (post_residual as f64) > 0.7 * bin_capacity as f64;
        let next_needs = next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity;
        if last_chance || (poor_fit && !next_needs) {
            score -= 18.0;
        } else {
            score += 12.0 + 4.0 * progress;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post residual too small for next item: mild penalty proportional to gap
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., fuller bins) to compact usage.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly (minimize wasted space non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness * tightness;

    // 2-step lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.8 * (next_item_size as f64) - 0.5 * pair_waste;
    } else if next_item_size > 0 {
        // Next item can't follow here: penalize small dead space more than large residual.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // tiny unusable sliver
        }
        score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // Relative-to-mean residual: prefer bins with below-average residual (tighter bins).
    score += 0.35 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it enables a clean 2-item chain,
    // otherwise penalize (avoid bin proliferation).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0; // fresh bin can host this item plus the next one
        } else {
            score += 55.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Slight early-stream bias toward filling existing bins to build tight packs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize tiny unusable leftovers that no typical item can fill.
    if post_residual > 0 && post_residual < 12 {
        score += 10.0;
    }

    // Lookahead coupling: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * (1.0 - progress);

    // Global residual state: if mean residual is small, keep bins tight.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate logic: only open a new bin when the item is large
    // relative to available fits and stream is early/mid.
    if bin_residual == bin_capacity {
        let waste_penalty = 2.5 * (bin_capacity - item_size) as f64;
        let open_benefit = 3.0 * open_bins_count as f64;
        let last_chance_pressure = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        score += waste_penalty + open_benefit - last_chance_pressure - 10.0 * progress;
    }

    // Mild time-horizon modulation: later in the stream, be greedier about tight fits.
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let item = item_size as f64 / cap;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized residual, modulated by progress
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - norm_post;
    score -= 40.0 * tightness * tightness * tightness;

    // Dead-space coupling: penalize residuals too small for typical future items
    let dead_zone = if norm_post > 0.0 && norm_post < 0.1 { (0.1 - norm_post) * 10.0 } else { 0.0 };
    score += 25.0 * dead_zone * dead_zone;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt as f64 {
            score += 15.0 * (1.0 - post / nxt.max(1.0));
        } else {
            score -= 10.0 * (1.0 - nxt / (post + 1.0));
        }
    }

    // New-bin candidate handling: encourage opening a new bin when mean residual is low
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 20.0 * mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for bin proliferation late in stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible into fine classes.
    // Perfect fits (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for small, unusable residuals.
        let pr = post_residual as f64;
        let small = pr / cap; // fraction of capacity wasted
        score += (small * small) * 120.0;

        // Harmonic classes via integer division on post_residual:
        // class 0: residual <= 9  (almost dead)
        // class 1: residual in 10..=19 (rarely reusable)
        // class 2: residual in 20..=49 (sometimes reusable)
        // class 3: residual >= 50 (healthy)
        let class = if pr <= 9.0 { 0 } else if pr <= 19.0 { 1 } else if pr <= 49.0 { 2 } else { 3 };
        score += [60.0, 35.0, 12.0, 0.0][class];

        // Modulo arithmetic: residuals near capacity/2 or capacity/3 are classic
        // "harmonic" sweet spots that pair with common item sizes.
        let half = cap / 2.0;
        let third = cap / 3.0;
        let d_half = (pr - half).abs();
        let d_third = (pr - third).abs();
        score -= (1.0 - d_half / half).max(0.0) * 8.0;
        score -= (1.0 - d_third / third).max(0.0) * 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize leaving residual that invites waiting.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual across
    // open bins. Only attractive when open bins are nearly full (mean residual low)
    // or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Reward opening when existing bins are tight.
        score -= (cap - mean_residual) / cap * 55.0;
        // Early in the stream, prefer consolidation (fewer bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 25.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 30.0 + 10.0 * fitting_bins_count as f64;
        }
    }

    // Prefer fuller bins: tie-break on how much of the bin is already used.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 20.0;

    // Slight preference to balance bin count late in stream.
    if open_bins_count > 1 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically small gaps < ~15) are waste.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Heavily penalize tiny unusable gaps.
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_threshold as u32 {
            score -= 45.0 - gap as f64;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for the lookahead item: dead space penalty.
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is fine; later, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If the new bin would fit the next item too, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    } else {
        // Using existing bins reduces open-bin pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (filling emptier bins less,
    // keeping balanced residuals for future items is less important than
    // killing dead space, so keep weight small).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled against mean residual.
    score -= (bin_residual as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how well it pairs.
            score -= (post_residual - next_item_size) as f64 * 0.9;
            // Bonus for a near-perfect two-item pairing (post_residual ~ next_item_size).
            let pair_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= (bin_capacity as f64 - pair_gap) * 0.05;
        } else {
            // Next item does NOT fit this bin after placement: penalize leaving
            // dead space that is smaller than the lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Penalize bins far from the mean residual (outliers) mildly.
    score += (post_residual as f64 - mean_residual).abs() * 0.08;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish score so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        // A fresh bin has residual == capacity; make it attractive only if
        // current item is large relative to capacity, otherwise slightly worse.
        score = post_residual as f64 + 12.0 - (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Late-stream consolidation: favor reusing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: minimize post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, residual likely dead space anyway
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; slight penalty for wasting the slot
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize using a bin whose residual is far above average (better bins exist).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.5;
    }

    // New-bin candidate handling: baseline cost of opening a bin, reduced late in stream
    // or when few bins fit the item (fragmented state).
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0;
        new_bin_score -= 30.0 * t; // later in stream: opening fresh bins is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 10.0; // fresh bin always accommodates lookahead
        }
        score += new_bin_score;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Slight reward for placing larger items into emptier bins early.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (item_size as f64 / bin_capacity as f64) * (1.0 - t) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * 0.5;
    score += poly * cap * 0.8;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - gap) * cap * 0.6;
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space
        score += pr * 0.25 * (0.5 + progress);
    }

    // Penalize opening a new bin, more so later in the stream
    if bin_residual == bin_capacity {
        score += cap * (1.0 + 1.5 * progress) + open_bins_count as f64 * 2.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.9;
    }

    // Mild alignment with mean residual: prefer bins close to mean to keep balance
    score += ((pr - mean_residual) / cap).abs() * cap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps that are multiples of common
    // item sizes are reusable, odd gaps are dead space.
    let pr = post_residual;
    if pr > 0 {
        // Reward gaps in "friendly" residual classes (multiples of 10/20/25/50)
        if pr % 10 == 0 {
            score -= 12.0;
            if pr % 20 == 0 { score -= 6.0; }
            if pr % 50 == 0 { score -= 8.0; }
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            // odd / prime-ish gap: penalize proportionally to smallness
            score += (cap * 0.15) * (1.0 - pr as f64 / cap);
        }
        // Integer-division thresholds: tiny unfillable slivers are dead space
        if pr < 10 {
            score += 30.0 + (10 - pr) as f64 * 2.0;
        }
    }

    // Lookahead coupling: does the next item fit exactly into the post gap?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect pair
        } else if next_item_size <= pr {
            let gap2 = pr - next_item_size;
            if gap2 % 10 == 0 { score -= 18.0; }
            if gap2 < 10 { score += 8.0; }
        } else {
            // next item won't fit here: mild penalty for tight class bins
            score += 4.0;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it unattractive unless current bin would leave
    // a nasty small gap or bin pool is huge.
    if bin_residual == bin_capacity {
        let tight = (pr < 10 && pr > 0) || (next_item_size > 0 && next_item_size > pr && pr > 0);
        score = cap + if tight { 0.0 } else { 25.0 };
        if open_bins_count > 8 { score -= 10.0; }
    }

    // Progress-scaled tie-break toward fuller bins
    score -= (post_residual as f64 / cap) * (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 6.0; // dead-space wedge penalty
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // hard penalty for tiny gaps
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.25;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for the next item: dead space confirmed
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless fit is poor.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral residual (full capacity), apply pressure
        // plus a mild bonus only when the stream is early.
        score = score * 0.5 + pressure + 20.0
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    } else {
        score -= pressure * 0.5;
        // Prefer bins tighter than average residual (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to item size).
    let tightness = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 1.0 };
    score -= 30.0 / (1.0 + tightness);

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when existing bins can fit the item,
        // but allowed when fits are scarce or residuals are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_penalty = 60.0;
        if fitting_bins_count == 0 {
            open_penalty -= 70.0; // no alternative: must open
        } else if fitting_bins_count <= 2 {
            open_penalty -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        open_penalty += 40.0 * progress;
        // Many open bins with large mean residual => consolidate rather than open.
        if mean_residual > item_size as f64 * 1.5 {
            open_penalty += 15.0;
        }
        score += open_penalty;
    } else {
        // Prefer bins whose residual is close to item_size (best-fit flavor).
        score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

        // Lookahead: reward bins whose post-residual can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 8.0; // would strand unusable space before next item
        }

        // Mild preference for bins below mean residual (balance load).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Encourage using few bins overall: with many open bins, slight consolidation bias.
    if open_bins_count > 10 {
        score += 0.5 * (open_bins_count as f64 - 10.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger post-residuals (bins can still be filled later).
    // Later: penalize wasted space quadratically/cubically since remaining
    // opportunities to fill gaps shrink.
    let w = 1.0 - progress;
    let poly = pr * pr * (1.0 / (2.0 * cap)) * (0.5 + 0.5 * progress * progress);
    let cubic = pr * pr * pr * (1.0 / (3.0 * cap * cap)) * progress;
    score += poly + cubic;

    // Reward tight fits, more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= tightness * item_size as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: if the next item could fit into the resulting residual,
    // reward leaving exactly that space (smooth gaussian-like match).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let norm = diff / cap;
        score -= 6.0 * (-norm * norm * 8.0).exp();
    } else {
        // Last item: prefer fullest possible packing.
        score += pr * 0.5;
    }

    // Mild diversity preference: bins far from the mean residual keep the
    // residual distribution spread, which helps future fits.
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 - progress);

    // Slight penalty when many bins are open and progress is low: encourage
    // consolidation into fewer bins early.
    score += (open_bins_count as f64).ln().max(0.0) * w * 0.3;

    // New-bin candidate handling: empty bin has pr == cap.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when this is a late stream or the
        // post-residual in existing bins would be badly wasted.
        score = cap * (0.9 + 0.4 * progress) - 2.0 * progress * (cap - pr);
        if fitting_bins_count <= 1 {
            score += 50.0; // never open a new bin when it's the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space) super-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5 - post_residual) as f64 * 40.0;
    } else if post_residual <= 10 {
        score -= 100.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Harmonic classes: bin residual modulo capacity-fraction classes.
    // Residuals in coarse classes (multiples of 25) are more reusable.
    let post_class = post_residual % 25;
    if post_class == 0 && post_residual > 0 {
        score -= 60.0; // clean class boundary residual
    } else if post_class > 20 {
        score += 20.0; // awkward sliver in this class
    }

    // Integer-division thresholds on post_residual: bins whose post residual
    // can still hold a "small" item (<= 20) remain attractive.
    let small_slot = post_residual / 20;
    if small_slot >= 1 {
        score -= small_slot as f64 * 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 500.0;
        } else {
            score -= (next_item_size as f64) * 0.5 - gap as f64 * 0.2;
        }
    }
    // Penalize if next item does NOT fit but would fit an empty bin,
    // making this placement fragment the stream.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly.
        score += 120.0 + open_bins_count as f64 * 5.0;
        // But if no open bin gives a decent fit (post_residual large & wasteful),
        // the penalty effectively shrinks relative to bad fits.
        if item_size >= bin_capacity / 2 {
            score -= 60.0; // big items pair well in fresh bins
        }
        // Early stream: allow more bins since future structure unknown.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Prefer bins below mean residual (consolidate emptier bins? no — prefer
    // filling fuller bins): penalize bins with residual above mean.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 10.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 10.0;
    }

    // Mild pressure against bin sprawl as open bins accumulate.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate gaps.
    if post_residual > 0 {
        let dead = 20.0f64.min(post_residual as f64);
        score += dead * dead / 20.0; // quadratic blow-up for tiny gaps
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward using a tight bin when it's the last fitting bin (avoid new bin).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // If this is the empty new-bin candidate (residual == capacity),
    // penalize opening a new bin unless the fit is genuinely bad elsewhere.
    if bin_residual == bin_capacity {
        let is_last_resort = fitting_bins_count <= 1;
        let poor_fit = (bin_capacity as f64 - post_residual as f64) < 0.5 * mean_residual.max(1.0);
        score += if is_last_resort && poor_fit { -10.0 } else { 40.0 };
    }

    // Lookahead: if the next item would fit exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 5.0; // gap likely unusable for the next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward near matches (next item nearly fits the leftover)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits in the leftover: bonus decaying with the gap
            score -= 20.0 * (1.0 - gap / 100.0).max(0.0);
        } else {
            // leftover too small for next item: penalize dead space severity
            score += 0.3 * gap;
        }
    }

    // Penalize very small unusable leftovers (dead space), unless perfect match above
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    // Compare against mean residual: bins with much larger residual than average
    // are "wasted" if we leave them barely dented; prefer filling below-average bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score; only attractive
    // when the item is large (would leave big unusable space elsewhere) or no good fit exists.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 15.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if item_size >= 70 {
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 40.0;
        }
    }

    // Slight late-stream pressure to close out bins rather than open new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward high fill level of the chosen bin (low post_residual relative to capacity)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead: if the next item can also fit into the resulting residual,
    // this bin's leftover space remains useful -> reward.
    if next_item_size > 0 && !is_new_bin {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else {
            // Residual becomes dead space too small for the next item
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (post_residual as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item;
    // failing to use it forces opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    // Many open bins with high mean residual -> fragmentation pressure;
    // prefer consolidating into existing bins rather than opening more.
    if !is_new_bin {
        score -= mean_residual * 0.05;
    } else {
        // New-bin candidate: penalize mildly so it only wins when existing
        // fits leave large dead space (its raw post_residual is already high).
        score += (item_size as f64) * 0.25 + 5.0;
        // Early in the stream, opening bins is cheaper; late, discourage it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins whose residual is exactly consumed
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: minimize wasted space, with super-linear penalty on small residuals.
    let mut score = post * (1.0 + 0.02 * post / cap);

    // Smooth non-linear coupling of residual waste with stream progress:
    // late in the stream, dead space matters more.
    score *= 1.0 + 0.35 * progress * (post / cap);

    // Reward tight fits (small post_residual) more strongly as progress grows.
    score -= 12.0 * (1.0 - post / cap).powi(3) * (0.5 + progress);

    // Penalize leaving residual that cannot fit the lookahead item (smoothly).
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 6.0 * (nx - post) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (post / nx).min(2.0) * 0.5;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins, more so when decent fits exist
    // and many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mild preference for bins below mean residual (balancing load smoothly).
    score += 0.05 * (post - mean_residual).max(-30.0).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bucket into capacity fractions
    let frac = post_residual as f64 / cap;
    if frac < 0.05 {
        score -= 30.0; // near-perfect fill, excellent
    } else if frac < 0.15 {
        score -= 12.0; // good fill
    } else if frac < 0.30 {
        score -= 2.0;
    } else if frac < 0.50 {
        score += 6.0; // moderate dead space
    } else {
        score += 18.0; // large dead space penalty
    }

    // Modulo class: residuals that are multiples of common small item sizes
    // are more reusable. Reward residuals divisible by 10 (typical item granularity).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 10.0; // tiny unusable sliver
    }

    // Lookahead: penalize if residual cannot fit the next item but a slightly
    // larger residual would have; reward if next item fits exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 5.0 - (slack as f64).min(10.0) * 0.3;
            if slack == 0 {
                score -= 15.0; // perfect pair with lookahead
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // Tie-break toward bins below mean residual (fill emptier bins less,
    // keep tight bins tight): prefer placing into bins with small residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large and no good fit exists; otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        score += 22.0;
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Late-stream tightening: as stream progresses, prefer perfect fills more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead_zone = bin_capacity as f64 * 0.10; // gaps <= ~10 units are dead space
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post_residual as f64 + 1.0) * 12.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using bins with large residual (consume the fattest space first),
    // penalize dipping into already-tight bins.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Open-bin pressure: fewer open bins -> prefer existing bins; many open bins -> allow spreading.
    score += (open_bins_count as f64 - 3.0) * 1.5;

    // Last chance: this is the only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if (gap as f64) <= dead_zone {
            score += 8.0; // placing here would strand next item's fit
        }
    }

    // New-bin candidate: prefer it only when it avoids creating dead space elsewhere
    // (empty bin residual = capacity is naturally high-scored by base term, add mild bias).
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
    }

    // Slight stream-progress term: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the next item also fits snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect two-item fill bonus
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // exact 2-item match: extremely desirable
            }
        } else {
            // Next item cannot follow: penalize proportionally to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Compare residual against mean residual across open bins
    let res = post_residual as f64;
    if res < mean_residual {
        // Below-average residual = tighter packing, reward it
        score -= 0.5 * (mean_residual - res);
    } else {
        // Above-average residual = loose fit, penalize mildly
        score += 0.2 * (res - mean_residual);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are very full or none fit well
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fullness > 0.7 {
            score -= 10.0; // bins nearly full, opening fresh bin is fine
        } else {
            score += 20.0; // discourage opening new bins early
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin can host both current and next items
        }
    }

    // Mild pressure to consolidate as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 5.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / 100.0);
        }
    } else {
        // Last item: any bin works, prefer fullest fill.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin gets a baseline score; discourage opening
    // a new bin when a decent fit exists, encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
        // If mean residual across open bins is small (fragmented), opening new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Slight preference for filling existing bins as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 {
        score -= 0.2 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals more),
    // later, allow tighter packing (post_residual valued less).
    let flexibility = post_norm * post_norm * (1.0 - progress);
    score += 40.0 * flexibility;

    // Cubic term: dead space below next item size is unusable -> strong penalty
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 60.0 * gap * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 - post_norm);
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate signal)
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap - 0.5).abs();
        score += 25.0 + 30.0 * (1.0 - item_norm) + 20.0 * spread;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild reward for using bins far below mean residual (balancing)
    score -= 10.0 * ((mean_residual - post) / cap).max(0.0);

    // Smooth progress-driven tightening: as stream advances, prefer filling existing bins
    score -= 20.0 * progress * item_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction classes: harmonic quantization of post_residual
    let q = post_residual / 10; // integer division thresholds (0..10)
    score += (q as f64) * 2.0;

    // Reward near-perfect fits strongly
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty: unusable residue (too small for typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic modulo classes on post_residual: divisible-by-5 residues pair
    // well with common item sizes (multiples of 5/10)
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap == 0 {
            score -= 45.0;
        } else if next_gap <= 10 {
            score -= 18.0;
        } else {
            score -= (next_gap as f64) * 0.3;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residue: penalize proportional to wasted fraction
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        score = 100.0 - (mean_residual / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild pressure against bin proliferation
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // (min item size is 1, but tiny gaps rarely match future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins tighter than the average
    // (placing into a loose bin wastes its flexibility).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // slightly favor compacting into existing bins.
    if fitting_bins_count > 0 {
        score -= 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing decent bins win.
        let mut new_bin_score = post_residual as f64 + 12.0;
        // But if placing here would leave a bad gap in every existing bin
        // (all fitting bins would end with tiny residuals), opening a new
        // bin is better: estimate via post_residual being large & clean.
        if post_residual >= 20 {
            new_bin_score -= 6.0;
        }
        // Last-chance bin: if only one open bin fits, avoid starving it
        // unless the fit is excellent.
        if fitting_bins_count == 1 && post_residual > 0 {
            new_bin_score -= 4.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            new_bin_score -= 3.0;
        }
        score = new_bin_score;
    } else {
        // Lookahead synergy: reward leaving a gap that exactly fits next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving a gap the next item cannot use at all.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
        // Last-chance bin: strong reward to use it rather than open a new bin.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    // Mild stream-progression term: early on, be slightly conservative
    // about wasting bins; later, compact aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post residual near zero)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (post_residual as f64 - next_item_size as f64).abs() * 0.5;
        } else {
            // penalize dead space the next item cannot use
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.6;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of waste
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        score += 45.0 - 40.0 * crowding;
    }

    // Late in stream, tighten up: prefer tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (1) is worthless; scale penalty super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize leaving residual that is too small to be useful for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 12.0;
        } else {
            // Residual usable by next item: mild reward proportional to fit quality.
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Global slack pressure: when mean residual across bins is high,
    // encourage using existing space rather than opening new bins.
    let slack = mean_residual / bin_capacity as f64;
    score -= slack * 3.0;

    // Time horizon: early in the stream, be more liberal about opening new bins
    // (long future benefits from good structure); late in the stream, cram.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more late in the stream, less early.
        score += 4.0 * progress;
        // Opening a new bin is attractive when the item is large and nothing fits well.
        if item_size > bin_capacity / 2 {
            score -= 2.0 * (item_size as f64 / bin_capacity as f64);
        }
    } else {
        // Late in stream: extra reward for using open bins.
        score -= 3.0 * progress;
    }

    // Discard tiny dead space: if post_residual is nonzero but smaller than
    // half the smallest item, add a sharp penalty.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, tighten residual preference more aggressively
    let progress_gain = 1.0 + 1.5 * t * t;
    score *= progress_gain;

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * t);

    // Penalize dead space that no typical item could use: if post_residual is small
    // but nonzero relative to item sizes, it is wasted
    if post_residual > 0 {
        let min_item = 1.0 / cap;
        score += (norm_pr / (norm_pr + min_item)).ln() * 2.0;
    }

    // Lookahead coupling: if next item fits into the post-residual, reward strongly (smooth)
    if nxt > 0.0 {
        let fit_next = (pr - nxt).max(0.0) / cap;
        let smooth_fit = (fit_next * cap / 10.0).tanh();
        score -= 8.0 * smooth_fit * (1.0 - (pr - nxt).abs() / cap);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Prefer bins with residuals close to the mean (balanced packing), smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight penalty for many open bins to encourage consolidation early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: neutral-ish baseline with mild penalty so it only wins when
    // all open bins fit poorly (their scores will be inflated by dead space)
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * item + 5.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli
    let r4 = (post_residual % 4) as f64;
    let r5 = (post_residual % 5) as f64;
    let r10 = (post_residual % 10) as f64;

    // Reward residuals that lie in "usable" harmonic classes (multiples of common sizes)
    if post_residual % 10 == 0 {
        score -= 12.0; // perfectly aligned with decade item sizes
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        // penalize awkward remainders proportionally
        score += r10 * 0.8 + r5 * 0.4;
    }

    // Small residue penalty: post_residual in 1..10 is near-dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + (10 - post_residual) as f64 * 1.5;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Integer-division thresholds: classify post_residual into coarse bands
    let band = post_residual / 25; // 0..4
    score += band as f64 * 3.0; // larger leftover space mildly worse

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res % 10 == 0 {
                score -= 10.0;
            } else if nxt_res < 10 {
                score += 8.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize less if this bin is nearly full anyway
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // last item: strongly prefer zero residual
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets baseline score tied to capacity
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive if existing bins fit poorly
        score = (bin_capacity - item_size) as f64 * 1.1 + r10 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let nr = bin_capacity - item_size - next_item_size;
            if nr % 10 == 0 { score -= 12.0; }
        }
        // discourage opening new bins when many bins are open and mean residual is healthy
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.3;
    }

    // Progress modulation: late in stream, tighten up (prefer filling existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;
    if bin_residual < bin_capacity {
        score -= 4.0 * progress; // slight bias toward existing bins late
    }

    // Mean-residual deviation: prefer bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum item size of 1..=10 zone) are heavily penalized.
    let dead_zone: f64 = if post_residual > 0 && post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 6.0
    } else if post_residual == 0 {
        -15.0 // perfect fit reward
    } else {
        0.0
    };
    score += dead_zone;

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Penalize bins whose residual is far above the item (loose fit),
    // favoring best-fit behavior naturally via post_residual, but add
    // extra coupling when residual is large yet item is small.
    if post_residual > item_size {
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (4.0 - 3.0 * fill) * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * fill;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward;
    // if next item cannot fit post_residual but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 100.0 - 12.0 * fill;
        // If several bins fit the item, opening new bin is wasteful.
        if fitting_bins_count >= 1 {
            score += 25.0 * fitting_bins_count as f64;
        }
        // Last-chance case: no open bin fits? fitting_bins_count counts
        // open bins that fit; if 0 (only new bin viable), make it cheap.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early stream: opening bins is cheap.
        score -= 20.0 * (1.0 - progress);
        // Big items deserve fresh bins.
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (concentrate waste in fewer bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: perfect chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: prefer tight leftover after chain
            let chain_residual = post_residual - next_item_size;
            score -= 200.0 - chain_residual as f64;
        } else {
            // next item cannot follow: penalize proportionally to overshoot
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: small residual vs average is good
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 100.0;
        }
    }

    // Penalize large dead space that nothing (min size 1..) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in stream: consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) with a non-linear boost
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // low-utility zone
    }

    // Lookahead (k=2): if the next item fits exactly in the post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0; // keeps a viable chain alive
        } else {
            // next item won't fit here: post_residual becomes dead weight
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 18.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, mild penalty to preserve flexibility for other bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Time horizon: early in the stream, be conservative about filling bins tightly
    // (leave room); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state coupling: if mean residual across open bins is high,
    // we have slack overall -> prefer filling existing bins more tightly.
    if mean_residual > (item_size as f64) {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    } else {
        // bins are nearly full overall; opening new capacity may be warranted
        score += 5.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only attractive when nothing good exists among open bins, or stream is early
    // and open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // Base penalty so new bins are opened only when justified
        score += 45.0;
        // If open bins are nearly full (low mean residual), new bin is more acceptable
        score -= 35.0 * (1.0 - congestion);
        // If this bin is the only fitting option, opening is fine
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins
        score += 15.0 * progress;
        // If next item is large and current bins are congested, new bin gives room
        if next_item_size >= 60 && congestion < 0.3 {
            score -= 10.0;
        }
    }

    // Mild penalty for very large items into already-crowded bins count of bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly;

    // Penalize large dead space late in the stream (quadratic in progress)
    score += 12.0 * norm_pr * progress * progress;

    // Reward tight fits: cubic term in post_residual
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.05 * gap * (1.0 - progress);
        if pr >= nxt {
            score -= 4.0 * (1.0 - gap / cap);
        }
    }

    // Mild pressure from number of open bins vs mean residual
    let mr = mean_residual / cap;
    score += 0.5 * (open_bins_count as f64).sqrt() * (norm_pr - mr).abs();

    // New-bin candidate: prefer it only when residuals are large and stream is early
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress) * (1.0 - norm_pr);
        score += 25.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r == 0 {
        score -= 500.0; // perfect fit is always best
    } else {
        if r % 10 == 0 { score -= 12.0; }
        if r % 20 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 10.0; }

        // Dead-space penalty: residuals below the smallest plausible item
        // (harmonic class floor) are nearly unusable.
        if r < 10 {
            score += 60.0;
        } else if r < 25 {
            score += 18.0;
        }

        // Integer-division thresholds: how many "average" items still fit.
        let avg_item = 30.0f64;
        let fits_count = (r as f64 / avg_item).floor();
        score -= fits_count * 5.0;

        // Lookahead coupling: if the next item fits exactly in the post
        // residual, strongly reward; if it cannot ever fit, mild penalty.
        if next_item_size > 0 {
            if next_item_size == r {
                score -= 80.0;
            } else if next_item_size <= r {
                score -= 15.0;
                // harmonic bonus: next item leaves a class-aligned residual
                let rr = r - next_item_size;
                if rr % 10 == 0 { score -= 6.0; }
                if rr == 0 { score -= 40.0; }
            } else {
                score += 8.0;
            }
        }

        // Last-chance bin: strongly favor using the only bin that fits.
        if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
            score -= 45.0;
        }

        // New-bin candidate handling: opening a new bin wastes the mean
        // residual of all open bins; penalize proportionally, but allow it
        // when open bins are nearly full anyway.
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let waste = mean_residual * (open_bins_count as f64).sqrt();
            score += waste * 0.5;
            // late in the stream, prefer consolidating into open bins
            score += (1.0 - progress) * 5.0;
            if fitting_bins_count == 0 {
                score -= 100.0; // no alternative: must open
            }
        }

        // Prefer tighter bins when several fit: closeness of fit reward.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead". Penalize them extra hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // unreachable, but guard
    }
    // Dead zone: gap below a typical small item threshold (e.g. < 10) is wasted.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward tight fits (small relative slack).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (gap slightly below next size), mild penalty.
    if next_item_size > post_residual && next_item_size - post_residual <= 8 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, consolidation is natural anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the mean (avoid stranding outliers),
    // but only mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: empty bin. Make it attractive only when the fit into
    // open bins would be poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin; adjusted by how badly existing fits are.
        score = bin_capacity as f64 * 0.9
            + 0.5 * (open_bins_count as f64)
            - if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // If no open bin fits well (this call's comparison happens against open bins
        // that also fit), open a new bin when existing fits leave big dead space:
        // emulate by checking whether the item is large relative to capacity.
        if item_size >= 70 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_quality = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize dead-end placements, more so if post_residual is small.
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean-residual coupling: prefer bins below mean residual (tighter bins fill first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer filling existing bins over opening new ones, scaled by stream maturity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress; // new-bin candidate penalty
    } else {
        score -= 5.0 + 10.0 * progress;
    }

    // Penalize very large residuals left in already-open bins (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // near-perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize leaving residual that can't fit the next item,
    // reward residual that exactly accommodates it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 6.0;
            }
        } else {
            // Residual wasted relative to lookahead item.
            let waste = (next_item_size - post_residual).min(item_size);
            score += waste as f64 * 0.3;
        }
    }

    // Penalize bins far below mean residual (fragmenting large spaces),
    // unless the item fills them well.
    let deviation = bin_residual as f64 - mean_residual;
    if deviation > 0.0 {
        score += deviation * 0.05;
    }

    // Progress-based horizon: early in stream, conserve big bins;
    // late in stream, prefer closing bins out (favor higher residual use).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64 - item_size as f64) * 0.02;
    score -= progress * post_residual as f64 * 0.05;

    // Mild pressure to reuse open bins instead of opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic waste penalty: small residuals are fine, large ones are bad.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Smooth cubic coupling of waste with stream progress: tighten up over time.
    score += 12.0 * progress * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect-fit reward (smooth, not piecewise).
    score -= 40.0 * (-pr as f64 / 4.0).exp();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward residuals that can still fit the next item.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 15.0 * fits_next * (-gap / 20.0).exp();
        // Penalize leaving exactly a next-item-sized hole only mildly (good chaining).
        score -= 5.0 * fits_next;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins early / when open bins have plenty of room.
        score += 80.0 + 120.0 * (1.0 - progress) + 60.0 * avg_pressure;
        // But if nothing fits well (large post_residuals elsewhere), relax via smooth term.
        score -= 45.0 * (avg_pressure * (1.0 - avg_pressure)).min(0.25) * 4.0;
    } else {
        // Mild preference for filling existing bins as stream progresses.
        score -= 10.0 * progress;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.8 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10
    let r = post_residual;
    let class = r % 10;
    // Residuals that are "harmonically useful" (small, or divisible into common sizes)
    let usefulness = match class {
        0 => 1.6,           // perfectly divisible -> great for future items
        5 => 1.2,           // half-class
        2 | 4 | 6 | 8 => 0.8, // even classes moderately reusable
        1 | 3 | 7 | 9 => 0.3, // odd primes of space, hard to fill
        _ => 0.0,
    };
    score -= usefulness * (r as f64).sqrt();

    // Integer-division thresholds on post_residual: tiny residual = perfect packing
    if r <= 2 {
        score -= 40.0;
    } else if r <= 5 {
        score -= 25.0;
    } else if r <= 10 {
        score -= 12.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if r >= next_item_size {
            score -= 8.0 + 0.3 * (r - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize large leftover waste
            score += 0.15 * (r as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if item is huge and would leave a bad class residual anyway, opening is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Progress-scaled tie-break: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins whose residual deviates below mean (concentrate filling)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward preserving this bin; otherwise penalize blocking it.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64
            && (post_residual as f64 - next_item_size as f64) < 10.0 {
            score -= 20.0; // sets up a near-perfect next placement
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 10.0; // blocks the next item; creates dead space
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow slightly looser fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.5);
    score += 3.0 * bin_pressure * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., mean residual is small relative to item) or item is large.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 + 10.0;
        if decent_fit_exists && fitting_bins_count > 0 {
            score += 45.0; // keep using existing bins
        } else {
            score -= 10.0; // opening a fresh bin is reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead credit: next item fits into the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Penalize dead space that the next item cannot use (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Tight fits are good: small post_residual relative to item size.
    score -= 6.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good targets; bins looser than average should absorb large items.
    if bin_residual as f64 > mean_residual {
        score -= 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score += 3.0 * ((mean_residual - bin_residual as f64) / bin_capacity as f64);
    }

    // New empty bin candidate: only attractive when no good fit exists,
    // i.e. item barely fits nowhere or lookahead needs a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0);
        if poor_fit {
            score -= 40.0;
        } else {
            score += 55.0;
        }
    }

    // Late in the stream, favor consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }
    // If next item cannot use the post-residual at all, penalize slightly.
    if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Crowded state: open bins mostly full -> new bin is cheap.
        if pressure < 1.5 || mean_residual < item_size as f64 * 0.6 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 20.0 + 15.0 * (1.0 - progress);
        }
    }

    // Mild preference to fill bins that are already mostly full (low residual).
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    // Global fragmentation control: penalize bins far below mean residual
    // (they would become isolated fragments).
    if bin_residual != bin_capacity {
        let diff = mean_residual - post_residual as f64;
        if diff > 15.0 {
            score += 0.3 * diff;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    let mut score = post;

    // Non-linear penalty on unusable residual, scaled by stream progress.
    let waste_curve = x * x * (1.0 + 3.0 * progress) - 0.5 * x * x * x;
    score += 30.0 * waste_curve * cap;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (1.0 - x) * (1.0 - x) * 20.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 15.0 * snug * snug;
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Scarcity: penalize when many bins compete, reward last-chance bins.
    if fitting_bins_count > 0 {
        score += 4.0 * (fitting_bins_count as f64).ln() * (1.0 + progress);
    }
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: avoid bins deviating strongly from the pack average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.3 + progress);

    // New-bin candidate: prefer opening a fresh bin only when the item is large
    // relative to capacity or the stream is early and open bins are many.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score -= 12.0 * size_frac * size_frac;
        score += 10.0 * openness * (1.0 - progress);
        score += 6.0 * x; // fresh bin has max residual; waste_curve already covers, extra nudge
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "dead space classes".
    let post = post_residual as i64;
    let residue = post % 10;
    // Perfect-fit classes (residue 0) are harmonically ideal -> reward strongly.
    if residue == 0 {
        score -= 25.0;
    } else if residue <= 2 || residue >= 8 {
        // Near-harmonic classes: small dead space either way.
        score -= 8.0;
    } else {
        // Mid classes (3..7): awkward gaps, penalize.
        score += 6.0 + (5 - residue) as f64;
    }

    // Integer-division thresholds: how many unit-10 slots remain after placement.
    let slots = post / 10;
    if slots == 0 {
        // Bin essentially sealed -> good (no future temptation), reward.
        score -= 12.0;
    } else if slots <= 2 {
        // Tiny leftover that only fits small items: mild penalty.
        score += 3.0 * slots as f64;
    }

    // Lookahead harmonic check: can next item land harmonically in post_residual?
    if next_item_size > 0 && post > 0 {
        if (post % next_item_size as i64) == 0 && next_item_size as i64 <= post {
            // Next item would exactly fill this bin: strong reward.
            score -= 20.0;
        } else if next_item_size as i64 > post {
            // Next item can't fit here anyway; leftover is dead for lookahead.
            score += 5.0;
        } else {
            let next_left = post - next_item_size as i64;
            if next_left % 10 == 0 {
                score -= 10.0;
            } else if next_left < 10 {
                score -= 4.0;
            } else {
                score += (next_left % 10) as f64;
            }
        }
    } else if next_item_size == 0 {
        // Last item: minimize waste directly.
        score -= 15.0;
    }

    // Last-chance bin: prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual here would be bin_capacity - item_size).
    if bin_residual == bin_capacity {
        let fresh_waste = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin unless item is large and fresh leftover is harmonically clean.
        let clean = (bin_capacity as i64 - item_size as i64) % 10 == 0;
        let pressure = if open_bins_count == 0 { 40.0 } else { 0.0 };
        if clean && item_size >= 50 {
            score += fresh_waste - 10.0 + pressure;
        } else {
            score += fresh_waste + 15.0 + pressure;
        }
    }

    // Mean-residual coupling: avoid dumping into bins far from the mean unless it seals them.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight late-stream tightening: as stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 40.0;
    }

    // Penalize large leftover that is still below typical small-item range (10..20 dead zone)
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin, unless current item is large
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let large_item_bonus = if item_size > 70 { -18.0 } else { 0.0 };
        score += base_penalty + large_item_bonus;
    }

    // Slight preference for tighter fits overall
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for the next item => strongly favor this bin.
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // Next item still fits afterwards: mild reward scaled by closeness.
            score -= 25.0 / (1.0 + diff);
        } else {
            // Next item would not fit: penalize leaving a residual that blocks it.
            score += 10.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        }

        // Also reward post_residual close to a "nice" residual (small leftovers).
        if post_residual <= 10 {
            score -= 8.0; // tight fill is good
        }
    }

    // Relative to mean residual: prefer bins whose residual is below average
    // (i.e., fuller bins) to consolidate occupancy.
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins are open and stream is late.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item leaves a very large residual in a new bin (small item),
        // discourage even more; if item is huge, new bin is relatively fine.
        score += (100 - item_size.min(100)) as f64 * 0.05;
    }

    // Small penalty for large dead space relative to capacity.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.0; // no-op guard

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose post-residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * (post_residual as f64 + 1.0);

    // Penalize dead space that no plausible future item can use.
    // Assume typical items are >= 10; residuals below 10 are pure waste.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item fits almost exactly afterwards.
        let post2 = post_residual - next_item_size;
        if post2 < 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin will be closed after placement; slight penalty unless it's a near-perfect fit.
        if post_residual > 0 {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin is good.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * (1.0 - progress);
        // Opening a new bin is more attractive when open bins are fragmented.
        if open_bins_count > 0 {
            score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        // If the item is large, starting fresh gives flexibility for future items.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    } else {
        // Prefer using existing bins when many are open (limit bin proliferation).
        score -= 0.05 * open_bins_count as f64;
    }

    // Global fragmentation pressure: if mean residual is high, prefer bins with
    // residual close to the mean (consolidate usage patterns).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild preference for bins whose residual is just above item size (exact-ish fits).
    let slack = bin_residual - item_size;
    if slack <= 5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // 0..1
    let coupling = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 30.0 * coupling * (0.5 + progress);

    // Penalize large post residuals more as stream progresses (dead space matters late)
    score += 8.0 * pr_norm * pr_norm * pr_norm * progress;

    // Reward tight fits (small post residual) with smooth falloff
    score -= 15.0 * (1.0 - pr_norm).powi(6);

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // but relax penalty when open bins have poor fits (large mean residual)
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 20.0 - 15.0 * mean_norm * mean_norm;
    }

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * pr_norm;
    }

    // Mild penalty for proliferating open bins early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual can host common
    // small item classes (divisors of capacity) are more valuable to keep.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that are "dead zones": too small for typical items.
    let min_item = 1.0;
    if (pr < min_item) && post_residual > 0 {
        score += 500.0;
    }

    // Classify post_residual by integer division thresholds (harmonic bands).
    let band = post_residual / 10; // 0..=10 bands of width 10
    let band_bonus = match band {
        0 => -50.0,               // near-perfect fill
        1 => -20.0,               // still useful for tiny items
        2 | 3 => 0.0,
        4 | 5 | 6 => 5.0,         // mid residuals, moderate value
        _ => -10.0,               // large residual keeps flexibility
    };
    score += band_bonus;

    // Reward residuals exactly divisible into harmonic fractions of capacity
    let residual_f = post_residual as f64;
    for k in [2u32, 3, 4, 5] {
        let frac = bin_capacity as f64 / k as f64;
        if (residual_f - frac).abs() < 0.5 {
            score -= 15.0;
        }
    }

    // Modulo logic: residuals that are multiples of common item sizes (10, 20, 25)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: value scales with how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 60.0 * snug;
        } else {
            // next item cannot use this residual: penalize tight leftovers
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.8 * gap;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let large_item = item_size as f64 > 0.5 * cap;
        if large_item && (fitting_bins_count == 0 || mean_residual < item_size as f64) {
            score -= 120.0 + 40.0 * progress;
        } else {
            score += 80.0 + 20.0 * pressure;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    // to consolidate space, keep roomy bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Slight preference to fill older/more-filled bins as stream progresses.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for next step).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain useful for the next item.
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; make new bins less attractive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += pressure * 3.0;
        // Still allow opening when no good fit exists elsewhere.
        if fitting_bins_count <= 1 {
            score -= pressure * 2.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild global tightness coupling: when mean residual is low, conserve space
    // by favoring bins with tighter fits (smaller post_residual already does this,
    // but scale it with stream progression).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near matches of next item into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match strongly favored
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus for near-perfect chain (slack <= 5)
            if slack <= 5.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot chain here; penalize by leftover gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: minimize post residual aggressively
        score -= 8.0;
    }

    // Penalize post_residual that is small but unusable (dead space below min item size 1..)
    if post_residual > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are better targets
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer tight bins, keep new-bin less attractive
    if open_bins_count > 3 {
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize so it's only chosen when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * item_size as f64;
        // Late in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: penalize leftover space (best-fit core), scaled super-linearly.
    let mut score = post_residual as f64;
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into the post residual,
    // this bin remains useful — reward that continuation.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Post residual too small for the next item: dead-space risk grows
            // the smaller the leftover relative to typical item sizes.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Make opening a new bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin, but discourage it when good fits exist
        // or when the stream is near its end.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0;
        score -= 20.0 * (1.0 - progress);
        // With many open bins and high mean residual, prefer reusing space.
        score += open_bins_count as f64 * 0.8;
        score += mean_residual * 0.3;
    }

    // Mild preference for bins whose residual is close to the item
    // (tight packing among competing bins).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    // Encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with mild non-linear sharpening.
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Stream-progress coupling: as stream advances, tighten preference for tight fits.
    let t = progress.clamp(0.0, 1.0);
    score += 12.0 * t * (pr / cap).powi(3) * cap.sqrt();

    // Dead-space penalty: post-residual too small to fit a typical next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let unusable = (nxt - pr).max(0.0);
        score += 0.8 * unusable * (1.0 - unusable / cap);
    }

    // Reward last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * t;
    }

    // Penalize spreading residual far from mean (fragmentation).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish, penalized when good fits exist.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - t) - 2.0 * fitting_bins_count as f64;
    }

    // Slight preference for bins whose fill matches item size (smooth coupling).
    score -= 0.05 * (item_size as f64) * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual (mod-10 buckets) ----
    let post_class = post_residual % 10;
    // Residuals whose class is "unusable" (small non-zero remainders) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_class == 1 || post_class == 2 {
        score += 12.0; // nearly-unusable class
    } else if post_class == 0 {
        score -= 8.0; // perfectly divisible residual is highly reusable
    }

    // ---- Lookahead coupling: does the next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Next item won't fit here: leftover risks becoming dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 100.0);
        }
        // Harmonic pairing: next item leaves a divisible residual too?
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else {
        // Last item: prefer dumping into existing bins, never open a bin.
        score -= 25.0;
    }

    // ---- Integer-division threshold on tightness of the current fit ----
    let slack_quarter = (post_residual as f64 / (bin_capacity as f64 / 4.0)) as u32; // 0..4
    score += match slack_quarter {
        0 => -15.0, // very tight fit, excellent
        1 => -5.0,
        2 => 0.0,
        3 => 5.0,
        _ => 10.0,  // mostly empty after placement
    };

    // ---- Last-chance bin: strongly favor using the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (spread risk) or when the item is large
        // and would leave existing bins with awkward residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 60.0;
        if large_item {
            score -= 10.0;
        }
        // Later in the stream, avoid proliferating bins; make new bins costly.
        score += 45.0 * progress;
        // If many bins are open with slack, discourage a new one.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // ---- Mild preference to consolidate when many bins are open ----
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / 100.0) * 4.0;

    // ---- Mean-residual attraction: prefer bins near the mean (balance) ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // but a perfect fit (post_residual == 0) is maximally rewarded.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score += 300.0; // dead space: residual too small for any item (min size 1..100 range)
    } else if post_residual <= 20 {
        score += 60.0;
    }

    // Reward tight fits relative to item size.
    let tightness = (post_residual as f64) / (item_size as f64).max(1.0);
    score += tightness * 40.0;

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual: mild penalty proportional to gap
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when this bin's
    // residual would become dead space or the fit is loose and bins are many.
    if bin_residual == bin_capacity {
        // New empty bin: baseline cost = full capacity minus item; add open-bin pressure
        // so with many open bins we prefer reusing.
        score = (bin_capacity - item_size) as f64 + (open_bins_count as f64) * 8.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size && post_residual >= next_item_size {
            score -= 50.0; // new bin can also host the lookahead item
        }
    } else {
        // Existing bin: reward reuse more as open_bins_count grows.
        score -= (open_bins_count as f64) * 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (consolidate small residuals into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Early stream: be slightly greedy toward reusing bins to build dense packs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 20.0 * (post_residual == 0 as u32 as bool) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact 2-step lookahead match — post_residual equals next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: this bin will be exactly filled next step
        } else if post_residual >= next_item_size {
            // next item fits; reward closeness of the two-step remainder
            let two_step = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - two_step / bin_capacity as f64);
        } else {
            // next item does NOT fit here; penalize dead space that blocks lookahead
            score += 15.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Tight fit reward: small post_residual is valuable (Best-Fit flavor)
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative-to-mean coupling: prefer bins whose residual is below mean
    // (concentrating fill in already-low bins keeps other bins large)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize new-bin opening unless it enables a perfect lookahead chain
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (post_residual == next_item_size
            || (post_residual >= next_item_size && post_residual - next_item_size < 10)) {
            score -= 55.0; // new bin justified by exact 2-step chain
        }
        // late in the stream, avoid spreading into new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for many open bins (consolidation pressure)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    let dead_zone = (post_residual as f64 / 12.0).powi(2);
    score += 3.0 * dead_zone;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for exact chained fit.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // Post-residual becomes dead space relative to lookahead.
            score += 2.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so tight fits in open bins win, but not huge.
        score += 6.0;
        // Open new bins early in the stream or when open bins are nearly full on average.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 12.0;
        }
        if progress < 0.15 {
            score -= 4.0;
        }
    } else {
        // Slight preference for filling fuller bins (best-fit bias).
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fullness;
    }

    // Global fragmentation pressure: if mean residual is small, avoid wasting space.
    if mean_residual > 0.0 {
        let frag = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Discourage leaving residuals in the awkward 1..=9 band.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild penalty on large residuals (keep bins flexible).
    // Late: strongly reward small residuals (tight packing matters).
    let prn = pr / cap; // normalized post residual in [0,1]
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += w_early * 8.0 * prn * (1.0 - prn) * cap * 0.05;
    score -= w_late * 6.0 * prn * prn * cap * 0.05;

    // Tight fit reward: smooth gaussian-like kernel around post_residual near 0.
    let tight = (-(prn * prn) / 0.02).exp();
    score -= 12.0 * tight;

    // Lookahead: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (-(diff * diff) / 0.01).exp();
    } else if next_item_size > 0 {
        // next item cannot fit here; mild penalty proportional to wasted potential
        score += 0.02 * prn * cap * (1.0 - progress);
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize placing into a bin whose residual is far below mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild new-bin preference when many bins are open and fit is poor.
    if bin_residual == bin_capacity {
        score += 0.5 * prn * cap * (1.0 - progress) - 2.0 * w_late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (e.g. 10, 20, 25, 50) are "reusable" classes.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 {
                h += 4.0;
            }
        }
        if r == 0 {
            h += 20.0; // perfect closure
        }
        h
    };
    score -= harmonic_bonus(post_residual);

    // Penalize small dead space that few item sizes can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            let chain = post_residual - next_item_size;
            score -= harmonic_bonus(chain) * 0.5;
        } else {
            // next item cannot use this residual: penalize wasted potential
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin has post_residual = capacity - item
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large relative
        // to capacity (harmonic fraction thresholds) and few bins fit it.
        let frac = item_size as f64 / bin_capacity as f64;
        let q = (item_size * 4) / bin_capacity; // integer division quarter-class
        let mut new_bin_score = 30.0;
        if frac >= 0.75 {
            new_bin_score -= 20.0;
        } else if q == 1 {
            new_bin_score -= 6.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // discourage hoarding bins when many open bins have slack
        new_bin_score += mean_residual * 0.15;
        new_bin_score += open_bins_count as f64 * 0.8;
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        return new_bin_score;
    }

    // Prefer tight fits among open bins: reward small post_residual nonlinearly
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 10.0;

    // Mild penalty for bins far from the mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are nearly worthless.
    if post_residual < 10 {
        score += 60.0; // unusable dead space penalty
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else {
        // Diminishing penalty for larger residuals; tight fits rewarded.
        score -= 8.0 * ((bin_residual as f64) / (bin_capacity as f64));
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins can fit the item
        // and existing residuals are large (bad fits elsewhere).
        score += 45.0 + 4.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // lookahead item may need a fresh bin anyway
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= 2.0 * (open_bins_count as f64).min(10.0);
        // If the next item fits exactly in the post-residual, big reward.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            // Next item won't fit here anyway; small residual is fine.
            score -= 5.0;
        }
    }

    // Mild stream-progression term: early on, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_quality = 1.0 - (post - nxt) / 100.0;
            score -= 30.0 * match_quality * match_quality;
        } else {
            // Next item cannot fit here; penalize proportionally to leftover dead space.
            score += 0.5 * (post - nxt).min(post);
        }
    }

    // Favor bins whose residual is tighter than average (good fits).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate mildly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            // Perfect pair start in a fresh bin is attractive.
            score -= 45.0 * (1.0 - ((bin_capacity - item_size - next_item_size) as f64) / 100.0);
        }
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: dynamic time horizon.
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Tight-fit reward: the fuller the bin relative to its residual, the better.
    let fit_ratio = item_size as f64 / (bin_residual.max(1) as f64);
    score -= fit_ratio * 20.0;

    // Lookahead coupling (k=2): penalize residuals that the next item cannot use
    // (fragmentation), reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // Dead space relative to lookahead: scaled penalty, grows late in stream.
            score += (nxt - post_residual as f64) * (1.0 + 1.5 * t);
        } else {
            // This bin remains useful for the next item.
            score -= 4.0 + 2.0 * t;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: discourage opening a new bin when open bins fit,
    // especially late in the stream when consolidation matters most.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 15.0 * t;
        // Extra penalty if other bins can also fit the item.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is tighter than the global mean (large-residual
    // bins stay flexible for big future items).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Mild pressure toward fewer open bins.
    score += open_bins_count as f64 * 0.05;

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let p = progress;
    let coupling = norm_post * norm_post * (0.5 + 2.0 * p * (1.0 - p)) + norm_post * p * p;
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 30.0 * p);

    // Lookahead: reward residual that can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap) * (1.0 + p);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 8.0 * norm_post * (0.5 + p);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * p;
    }

    // Penalize opening new bins, more so later in the stream and with few bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * p + 2.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins relative to mean residual.
        score -= 0.05 * (mean_residual - post).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the leftover space: bucket of width 10 (capacity fractions).
    let class = post_residual / 10;
    // Dead-space penalty grows super-linearly for small leftovers (unusable slivers).
    let dead = match class {
        0 => 45.0, // post_residual 0..9 : perfect packing, reward heavily
        1 => 18.0, // 10..19 : usable only for small items
        2 => 8.0,
        3 => 3.0,
        4 => 0.0,
        5 => -2.0, // mid leftovers are actually flexible
        _ => 0.0,
    };
    score += dead;

    // Exact-fit harmonic bonus: post_residual divisible by small classes (10, 20, 25, 50)
    if post_residual % 50 == 0 && post_residual > 0 { score -= 12.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 8.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 5.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let bonus = if gap == 0 { 30.0 } else if gap <= 10 { 15.0 } else { 5.0 };
        score -= bonus * (1.0 + (post_residual as f64 / bin_capacity as f64));
    }
    // Penalize leaving a residual that the next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 && !is_new_bin {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many fitting bins: slight preference for the fullest (best fit) — post_residual already encodes this.

    // Progress-aware aggression: late in the stream, consolidate more tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // item is large (would leave big unusable crumbs elsewhere) or nothing fits well.
    if is_new_bin {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut penalty = 30.0;
        if large_item { penalty -= 12.0; }
        if fitting_bins_count == 0 { penalty -= 40.0; }
        // If open bins have large mean residual, prefer filling them instead of new bin.
        penalty += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
        score += penalty;
    }

    // Small tie-breaker on residual to keep determinism and prefer fullest bin.
    score -= (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    let useful_threshold = 10u32; // below typical item sizes, gap is near-dead
    if post_residual > 0 && post_residual < useful_threshold {
        score += 40.0 * (useful_threshold - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap exactly matching the next item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if the gap cannot hold the next item but is close to it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open,
    // penalize placements that fragment the mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit;
    // make the fresh bin moderately costly so it wins only in bad-fit situations.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item fill: bin closed exactly
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer bins where the pair leaves minimal dead space
            score -= 40.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // Penalize large leftover after the pair
            score += 0.35 * next_post as f64;
        } else {
            // Next item cannot follow into this bin: leftover is dead space
            score += 0.25 * post_residual as f64;
            // Slight bonus if leftover is small anyway
            if post_residual < 10 {
                score -= 8.0;
            }
        }
    } else {
        // Last item: just close as tightly as possible
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Tight-fit reward relative to current residual (best-fit flavor)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Compare against mean residual: filling below-mean-residual bins is valuable
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits poorly
    // in every open bin or the stream is early and consolidation is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred
        score += 15.0;
        // Poor fit elsewhere (large post_residual among open bins) justifies new bin
        if next_item_size > 0 && next_item_size < post_residual {
            // new bin still allows 2-step packing; mild discount early on
            score -= 20.0 * (1.0 - progress);
        }
        if post_residual == 0 {
            score -= 100.0; // exact-capacity item: always open fresh bin
        }
    }

    // Encourage consolidation when many bins are open
    score -= 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (dead space below the minimum item size).
    let min_size = 1.0f64;
    if (post_residual as f64) < min_size * 10.0 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Scarce fitting options generally: reward this bin more when alternatives are few.
    if fitting_bins_count >= 2 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score += 5.0 * pressure;

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, consolidate into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses.
        score += 10.0 + 40.0 * t;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward more late in the stream (consolidation).
        score -= 10.0 * t;
    }

    // Mild preference for bins with residual close to the mean (balanced usage).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let residual_norm = pr / cap;
    let smooth = progress * (1.0 - progress) * 4.0;
    // non-linear polynomial coupling of post_residual with stream progress
    score -= smooth * residual_norm * residual_norm * cap * 0.5;
    score += (1.0 - smooth) * residual_norm * pr * 0.3;
    // reward tight fits with a cubic term
    score -= (1.0 - residual_norm).powi(3) * fit_ratio * cap * 0.8;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * fit_ratio;
    }
    // lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let gap = pr as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 0.4 * gap / cap;
        } else {
            score += 0.25 * (-gap) / cap;
        }
    }
    // mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * residual_norm * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual modulo capacity fractions (C=100 -> quarters).
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    // Residuals near a quarter boundary are more reusable by typical items.
    let boundary_dist = class.min(quarter - class) as f64;
    score += boundary_dist * 0.15;

    // Dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Waste proportional to how close it came to fitting next item.
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.4;
        // Last-chance bin: strongly prefer using it despite imperfect fit.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual stays usable: reward, more so late in the stream.
        score -= 5.0 + 5.0 * progress;
    }

    // Harmonic threshold on integer division: residual bands.
    let band = post_residual / quarter.max(1);
    score += band as f64 * 2.0; // prefer fuller bins (smaller band index)

    // Avoid spreading across too many open bins when residuals are large.
    if (post_residual as f64) > mean_residual {
        score += 1.5;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual >= 0 && fitting_bins_count == 1 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0);
        if poor_fits {
            score -= 30.0;
        } else {
            score += 25.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Penalize moderate dead space proportionally.
    if post_residual >= 10 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.5;
    }

    // Open bins pressure: discourage proliferating bins unless this is a new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins would leave bad dead space.
        if post_residual > 20 && open_bins_count > 0 {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Mild pressure against many open bins relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.1 + 0.2 * progress);

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced usage).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // mild penalty if next item cannot fit into post_residual
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating tiny unusable residuals (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Relative-to-mean adjustment: prefer bins with residual near mean (balanced packing)
    let prog = step_index as f64 / total_items.max(1) as f64;
    score += 0.25 * (post_residual as f64 - mean_residual) * (1.0 - prog);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin is a poor fit
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let poor_fit = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 25.0 };
        score += 20.0 + 0.3 * waste + poor_fit;
        // more open bins -> slightly favor consolidation over opening
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit signal: strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.35 * tightness * (item_size as f64);

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_waste = post_residual - next_item_size;
        score -= 0.25 * (combo_waste as f64).max(0.0);
        // Extra reward if the pair nearly fills the bin.
        if post_residual - next_item_size <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving a medium-sized hole that
        // neither the next item nor likely future items can use.
        let hole = post_residual as f64;
        if hole > 0.0 && hole < 10.0 {
            score -= 2.0; // tiny hole is fine (dead space anyway)
        } else if hole >= 10.0 && hole < item_size as f64 {
            score += 3.0; // awkward mid hole
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Penalize spreading across too many bins when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 3.0 * (1.0 - progress); // consolidate late in the stream
    }

    // Discourage using bins far above the mean residual when many bins are open
    // (keeps residuals balanced for future flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so
    // that any reasonable fit into an existing bin wins, but a very poor fit
    // (large post_residual) in existing bins loses to a fresh bin.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening new bins is wasteful; raise the penalty.
        score += 10.0 * progress;
        // If only a few bins are open early, a fresh bin is more acceptable.
        score -= 2.0 * (open_bins_count as f64).min(5.0);
    }

    // Slight preference for bins with more residual used relative to capacity.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening
    let pr = post_residual as f64;
    let tight = (pr / cap).powf(2.0 + 2.0 * progress);
    let mut score = pr * (1.0 + tight);

    // Penalize leaving residuals that are too small to be useful for typical items
    let dead_zone = if pr < 10.0 { (10.0 - pr) * 1.5 } else { 0.0 };
    score += dead_zone;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * snug * (1.0 + progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 8.0 * progress;
    }

    // Slight preference for filling bins in bins with larger residuals (avoid fragmenting many bins)
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Mild penalty for proliferating bins when many are open
    score += 0.02 * open_bins_count as f64 * tight;

    // New-bin candidate: make it attractive only when the item is large relative to residual
    // or very late in the stream; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.0 - item_frac) * (1.0 + 0.5 * (1.0 - progress)) + open_pressure - 5.0 * item_frac * progress;
        if fitting_bins_count > 0 {
            score += 8.0; // discourage new bin if any open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (divisible into common small item sizes) deserve a bonus.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = 0.0;
        for s in [50u32, 25, 20, 10, 5] {
            if pr % s == 0 {
                reusable += 6.0;
            }
        }
        if pr % 2 == 0 { reusable += 1.0; }
        score -= reusable;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Fraction-of-capacity coupling: residual as fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 15.0; // quadratic penalty on large leftovers

    // Integer-division threshold on post_residual: leftovers below the
    // smallest item size are dead space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // next item won't fit here; mild penalty
        }
        // Harmonic check: post_residual divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, keep it usable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins
    // would leave bad dead space. New bin has full residual.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But late in the stream, opening fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
    }

    // Prefer filling bins below mean residual (consolidate slack).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min item size ~1, but practically small gaps) are waste.
    // Penalize gaps that are unusable for the lookahead item too.
    if post_residual > 0 {
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // gap cannot fit the next item -> likely dead space
                score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
            } else {
                // gap usable by next item -> reward proportional fit
                score -= 3.0 * (next_item_size as f64 / post_residual as f64);
            }
        }
        // Absolute dead-space band: tiny leftovers are almost always waste
        if post_residual <= 10 {
            score += 12.0;
        } else if post_residual <= 20 {
            score += 5.0;
        }
    } else {
        // perfect fill
        score -= 25.0;
    }

    // Reward tight fits relative to item size
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // unless the fit is very tight.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline plus pressure
        score += 20.0 + 3.0 * open_bins_count as f64;
        // if mean residual is large, open bins can still absorb items -> open new bin less
        score += 0.4 * mean_residual;
    } else {
        score -= 0.05 * open_bins_count as f64;
    }

    // Early in stream, slightly prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact pairings (post_residual == next_item_size)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // perfect fit for next item: strong bonus
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement: mild bonus scaled by tightness
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize, worse if gap is small (near miss)
            score += 5.0 + 15.0 * (1.0 - gap / 30.0).max(0.0);
        }
    }

    // Tight fit now: reward small post_residual
    let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Compare against mean residual: prefer bins below-mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // allow new bin if no open bin fits well (large item)
        if item_size > 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: strongly reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0; // near-perfect fill, dead space unlikely usable anyway
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0; // residual remains usable
        } else {
            // residual becomes dead space for the next item
            score += 4.0 + 0.06 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the one that wastes least relative to mean residual
        score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // Penalize opening new bins, more aggressively later in the stream
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // Exception: if no open bin leaves a usable residual and item is large,
        // a fresh bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size && item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate into bins already below mean residual
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor tight fits less aggressively);
    // later, dead space becomes increasingly costly.
    let p1 = 1.0 - progress;
    let coupling = 0.4 + 1.6 * progress * progress + 0.8 * progress * p1;
    score += coupling * norm_pr * cap * 0.01;

    // Penalize bins that cannot fit the next item's complement well:
    // reward post_residual that is either ~0 or large enough for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (pr / (pr + nxt)).ln().abs().min(1.0);
        } else if pr > 0.0 {
            score += 2.0 * (1.0 - pr / nxt) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Mild preference for using already-open bins over opening new ones
    // (new empty bin has bin_residual == bin_capacity, so norm_pr == 1 there).
    if bin_residual != bin_capacity {
        score -= 1.0 + 0.5 * (open_bins_count as f64).ln();
    } else {
        score += 0.5 + 2.0 * progress;
    }

    // Smooth tie-break toward bins below mean residual (consolidation)
    score += 0.3 * (mean_residual - pr) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item sizes), penalize dead space.
    let post = post_residual;
    if post > 0 {
        let mut harmonic_bonus = 0.0f64;
        // Check divisibility by small harmonic classes (10, 20, 25, 50)
        if post % 50 == 0 { harmonic_bonus -= 18.0; }
        else if post % 25 == 0 { harmonic_bonus -= 12.0; }
        else if post % 20 == 0 { harmonic_bonus -= 9.0; }
        else if post % 10 == 0 { harmonic_bonus -= 6.0; }
        else if post % 5 == 0 { harmonic_bonus -= 3.0; }
        // Dead-space penalty: residuals in awkward ranges (1..10)
        if post < 10 { harmonic_bonus += 15.0; }
        score += harmonic_bonus;

        // Integer-division threshold: how many "average items" still fit
        let avg_item = 40.0f64;
        let slots = (post as f64 / avg_item).floor();
        score -= slots * 4.0;
    } else {
        // Perfect fit is best possible
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post >= next_item_size {
        score -= 20.0;
        if post == next_item_size { score -= 15.0; }
        // Harmonic match: next item aligns with post_residual class
        if post % next_item_size.max(1) == 0 { score -= 8.0; }
    } else if next_item_size > 0 && post > 0 && post < next_item_size {
        // Next item won't fit here; penalize stranding residual
        score += (next_item_size - post) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowdedness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Prefer new bin when mean residual is low (open bins nearly full)
        score += 55.0 * crowdedness;
        // Early in stream, opening bins is cheaper; late, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable
        if next_item_size > 60 { score -= 12.0; }
    }

    // Mild penalty for spreading across many bins when residuals are large
    if mean_residual > 50.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that cannot fit even the smallest plausible next item is waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space: nearly worthless
        } else if post_residual < 25 {
            score += 25.0; // small gap: low utility
        } else if post_residual < 50 {
            score += 5.0; // moderate gap: still usable
        } else {
            score -= 10.0; // large residual: bin stays flexible, reward
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 80.0;
    }

    // Prefer bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Lookahead coupling: reward leaving room for the next item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item would not fit here but fits nowhere else either.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and prefer filling existing ones; when few bins, be less aggressive.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 35.0 * pressure + 0.5 * mean_residual;
        // But if no existing bin fits well (this call's bin is virgin and item large),
        // soften the penalty so a fresh bin can win.
        if item_size > 60 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight reward scaled by pressure to consolidate.
        score -= 2.0 * pressure;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer future items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual exactly (or nearly) matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let gap = post - nxt;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64); // next item still fits
        } else {
            let gap = nxt - post;
            score += 0.8 * gap; // next item won't fit; penalize wasted leftover
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 5.0;
    }

    // Tight-fit reward: small post_residual is good.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins tighter than average get priority.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        score -= 20.0 * pressure;
        score -= 5.0 * early * (open_bins_count as f64).ln().max(0.0);
        // Penalize opening a new bin when an open bin gives a tight fit.
        if post_residual < 20 {
            score += 30.0;
        }
    }

    // Dead-space penalty: residuals too small for typical items are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small leftover slivers that are likely dead space (<= 10 unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward residuals that can still host the next item, penalize residuals
    // just barely too small for it (near-miss waste).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size >= post_residual.saturating_sub(4) {
            score += 18.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when the best
    // available fits are poor (large post_residual relative to capacity) or when the
    // open-bin pool is bloated with large mean residual.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 15.0 + 40.0 * pressure;
        if mean_residual > 30.0 && fitting_bins_count > 0 {
            score += 10.0;
        }
        // Late in the stream, mildly discourage proliferating bins.
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress;
    } else {
        // Mild bonus for using already-open bins to keep pool small.
        score -= 4.0;
    }

    // Global state coupling: when mean residual across open bins is high, prefer
    // placements that reduce dispersion (place into bins with residual above mean).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (best fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;
    // Early in stream: tolerate larger residuals (they may fill later); late: punish dead space
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += 30.0 * quad * progress_weight;
    score -= 15.0 * cubic * (1.0 - progress);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 40.0 * (-norm_pr * 6.0).exp();

    // Perfect fill bonus
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 * (-gap / cap);
        }
    }

    // Penalize bins far from mean residual (encourage residual homogenization)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight preference for consolidating into fewer bins
    score += 2.0 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: modulo-10 residue bands of post_residual
    let residue_class = post_residual % 10;
    let dead_penalty = match residue_class {
        0 => -3.0,          // perfectly reusable class
        1 | 2 => -1.5,      // near-perfect
        9 => 1.0,           // almost-round but off-by-one: worst dead space
        3 | 4 => 0.5,
        _ => 2.0,           // mid-band fragments
    };
    score += dead_penalty;

    // Integer-division thresholds: exact fill tiers
    let fill_tier = post_residual / 10; // 0..10
    score -= (10 - fill_tier) as f64 * 0.8;

    // Reward tight fits strongly (harmonic fraction of capacity)
    let fit_fraction = item_size as f64 / cap;
    if fit_fraction > 0.85 {
        score -= 6.0;
    } else if fit_fraction > 0.5 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item exactly matches post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 + 3.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 1.5; // next item cannot use this leftover anyway
        }
        // modulo harmony: next item shares residue class with leftover
        if next_item_size % 10 == post_residual % 10 && next_item_size > 0 {
            score -= 1.0;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64;
        // open new bin early in stream or when mean residual is high (fragmented bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress) * (mean_residual / cap).min(1.0);
    }

    // Penalize bins far below mean residual (they are the fragmented ones)
    score += ((mean_residual - bin_residual as f64) * 0.05).max(0.0);

    // Slight preference for already-open bins as stream progresses
    score += 0.01 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Threshold grows with item size scale.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == next_item_size && next_item_size > 0 {
        // Exact setup for the lookahead item.
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can still host the next item: mild reward.
        score -= 5.0;
    } else if next_item_size > 0 {
        // Residual cannot host next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline; penalize slightly so we only open
    // a new bin when no existing bin offers a decent fit, but reward it when
    // open bins are nearly full (high mean residual => low pressure to open).
    if bin_residual == bin_capacity {
        score += 10.0;
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        if mean_residual < 20.0 {
            score -= 15.0; // open bins are crowded, new bin is fine
        }
    }

    // Open-bin pressure: many open bins favors tighter packing into existing ones.
    score += open_bins_count as f64 * 0.15;

    // Slight preference for larger residual bins early in the stream
    // (keeps flexibility), fading as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Strong reward if next item exactly fills the remaining space (2-step lookahead match)
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() == 0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after that
            score -= 25.0 - 0.15 * (post - nxt);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 0.10 * (nxt - post);
        }
    }

    // Reward tight fits now (small post_residual)
    score -= 0.5 * (1.0 - post / cap) * (1.0 - post / cap) * 20.0;

    // Penalize unusable dead space: post_residual smaller than min item size (1..100 unknown, assume >= 10 typical)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a new bin only if current bins have poor fits
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slight penalty so it's used only when beneficial
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            // fresh bin fits both current and next item comfortably
            score -= 10.0;
        }
        if mean_residual < 0.5 * cap && fitting_bins_count > 0 {
            // open bins are roomy; discourage new bin
            score += 20.0;
        }
    } else {
        // favor bins whose residual is close to mean (keep balance) mildly
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: be slightly more conservative with bin openings
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual gets a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect chaining: this bin becomes exactly reusable for the next item.
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins that deviate strongly from the mean residual (fragmentation control),
    // more so early in the stream when consolidation matters.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Make the empty bin moderately attractive for large items
    // but discourage it when plenty of fitting bins exist.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        // Empty-bin score: prefer it for big items, discourage when many alternatives.
        score = base
            - 0.5 * item_size as f64
            + 4.0 * fitting_bins_count as f64
            + 10.0 * progress; // later in the stream, favor filling existing bins
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // room to chain the next item in a fresh bin
        }
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: penalize leftover space quadratically (dead space is worse the larger it is).
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (moderate leftovers OK); late, squeeze hard.
    let progress_coupling = (0.5 + progress) * pr * norm_pr;
    score += progress_coupling;

    // Reward tight fits: subtract for small post_residual via a smooth saturating term.
    let tightness = (-norm_pr * 6.0).exp();
    score -= 25.0 * tightness * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (item / cap);
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving a nearly-useless gap.
        score += 6.0 * norm_pr * (1.0 - norm_pr);
    }

    // New-bin candidate handling: an empty bin has no dead-space cost yet;
    // penalize opening new bins when decent fits exist, more so later in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 55.0 + 25.0 * progress + 3.0 * open_f.sqrt();
        // But if all open bins would leave huge waste, opening fresh is OK.
        let waste_gap = mean_residual - item;
        if waste_gap > 0.0 {
            let rel = (waste_gap / cap).min(1.0);
            score -= 70.0 * rel * rel;
        }
    }

    // Mild preference to fill bins with larger residuals among comparable fits.
    score -= 0.05 * bin_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or large classes) are more useful.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> perfectly reusable for coarse streams.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: divisible by 5 -> half-reusable.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: prime-ish / awkward residual -> penalize dead space harder.
    else {
        score += 2.0;
    }

    // Integer-division thresholds: post_residual in harmonic bands of capacity.
    let band = post_residual * 4 / bin_capacity; // 0..3 quartile band
    match band {
        0 => score += 12.0,          // tiny leftover: nearly full bin, great but fragile
        1 => score -= 6.0,           // 25-50% left: very reusable
        2 => score -= 1.0,           // 50-75% left: decent
        _ => {}                      // 75-100% left: neutral, bin barely used
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Harmonic match: next item shares a divisor class with post_residual
            let g = gcd_u32(next_item_size, post_residual);
            if g > 1 {
                score -= 6.0 + (g as f64).ln() * 4.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: open a fresh bin only when it is genuinely better.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; the empty bin naturally has max post_residual.
        score += 5.0;
        // But if no open bin fits well (mean residual small vs item), ease opening.
        if (mean_residual < item_size as f64) && fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // Tight-fit reward: item fills bin almost exactly.
    if post_residual <= 2 {
        score -= 10.0;
    }

    // Slight preference for fuller bins overall (waste minimization).
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

fn gcd_u32(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd_u32(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Penalize leaving gaps that cannot fit even the smallest future item,
    // but reward gaps that can still hold typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Dead-space penalty scaled by how tight the fit was.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when few bins fit.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.1;
        if open_bins_count == 0 {
            score = 0.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && mean_residual < 25.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item could exactly fill the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit into post_residual, slight penalty for wasted pairing.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // Mild preference for bins below mean residual (balances load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — quadratic penalty on waste
    score = (post_residual as f64).powi(2) * 0.02 + post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits perfectly in the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 800.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly
            score -= 300.0 * (nxt / (post_residual as f64));
        } else {
            // next item will NOT fit here: penalize leftover that becomes dead space
            score += 60.0 + 0.5 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (mean_residual - res);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: only attractive when nothing decent is open
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + 250.0 - 150.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening a fresh bin leaves room for the next item too
            score -= 120.0;
        }
    }

    // Mild pressure against hoarding many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: residual small relative to item
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 50.0 / (1.0 + tightness);

    // Last chance: only this bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only open a new bin when item fits poorly everywhere
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 120.0;
        // If next item is large and this item leaves big residual that can host it, new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
        // Penalize new bins more when many bins already open (avoid bin explosion)
        score += open_bins_count as f64 * 5.0;
        // Later in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // If the item nearly fills a fresh bin, opening is fine
        if item_size >= bin_capacity * 9 / 10 {
            score -= 150.0;
        }
    }

    // Lookahead: residual after placement that can host next item is valuable; otherwise waste
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to next item: small residual is better
            score += (post_residual as f64) * 0.3;
        }
    }

    // Prefer bins whose residual deviates below the mean residual (more "committed" bins)
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.4;

    // Penalize leaving large awkward residuals (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // small residual is fine, nearly full
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are increasingly valuable as the stream progresses.
    let t = norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * t * t + 25.0 * t * t * t * (1.0 + progress);

    // Reward near-perfect fits with a smooth quadratic bonus.
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize post_residual that cannot host the lookahead item (dead space),
    // with smooth coupling to the size of the mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 50.0 * gap * (1.0 + gap) * (1.0 + progress);
        } else {
            // mild reward if lookahead fits snugly
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // more strongly early in the stream; relax late when residual fragmentation dominates.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 30.0 * (1.0 - progress) - 20.0 * fragmentation * fragmentation;
        if next_item_size > 0 && item_size as f64 / cap > 0.6 {
            score -= 15.0; // large items fit fine in a fresh bin
        }
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class: reward post_residuals that are "usable" sizes.
    // Class residuals by integer division into bands of 20.
    let band = post_residual / 20;
    score -= 8.0 * (band as f64).recip().max(0.0);

    // Modulo arithmetic: post_residual divisible by small numbers tends to be
    // fillable by common item sizes; reward divisibility classes.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        else if r % 5 == 0 { score -= 3.0; }
        if r % 20 == 0 { score -= 3.0; }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 60.0;
    }

    // Lookahead: does next_item_size fit in post_residual?
    if next_item_size > 0 && next_item_size <= r {
        let next_fit_tightness = (r - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - next_fit_tightness);
        // Harmonic pairing: item + next divides capacity nicely.
        if (item_size + next_item_size) % 100 == 0 { score -= 15.0; }
        if (item_size + next_item_size) % 50 == 0 { score -= 8.0; }
    } else if next_item_size > r {
        // Dead space for the lookahead item: penalize.
        score += 6.0 * ((next_item_size - r) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty grows with number of open bins relative to stream progress,
    // discouraging bin proliferation late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + progress);

    // Pull toward mean residual: prefer bins near the average fill state.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by how bad existing fits are.
        let best_possible_waste = if fitting_bins_count > 0 {
            // approximate: minimal waste among open bins unknown; use item size class
            (bin_capacity - item_size) as f64 / bin_capacity as f64
        } else {
            1.0
        };
        score += 30.0 - 25.0 * best_possible_waste;
        // Early in stream, opening bins is cheaper (need bins anyway).
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
