            score -= 6.0;
        }
        // Penalize leaving a gap just below the next item size (near-miss dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // what the item consumes (balanced packing).
    let mean_dev = (bin_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportionally tighter chains; dead space after next item is penalized.
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 10.0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot use the residual: residual is likely dead space.
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // Extra penalty if the leftover would be unusable small dead space.
            if post_residual < 10 {
                score += 80.0;
            }
        }
    }

    // Coupling with mean residual: prefer bins below-average residual (tighter bins)
    // so looser bins stay available for larger future items.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; escalate with number of open bins and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 + 30.0 * open_bins_count as f64 + 150.0 * progress;
        // But if the item is large and would leave a big residual elsewhere anyway,
        // a fresh bin is fine (post_residual here equals capacity - item).
        if item_size >= 60 {
            score -= 120.0;
        }
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 60.0;
        }
    }

    // Mild preference for filling bins with larger residual when few bins open
    // (consolidation), and for tighter bins when many are open.
    if open_bins_count > 4 {
        score += (res_f / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect-fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large dead space (residuals too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 3.0; // still usable
    } else if post_residual > 60 {
        score += 4.0; // wasteful placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 7.0;
        }
    }

    // New-bin candidate handling: open a new bin when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are not opened frivolously
        score += 12.0 + (open_bins_count as f64) * 0.4;

        // If this item leaves large residual in every fitting bin (poor fits),
        // opening a new bin becomes attractive: reduce the penalty.
        let fit_quality = if bin_residual >= item_size {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else {
            0.0
        };
        if fitting_bins_count > 0 {
            // poor existing fits -> post_residual here is capacity - item_size
            let new_bin_post = (bin_capacity - item_size) as f64;
            if new_bin_post < mean_residual {
                score -= 10.0; // existing bins are on average worse than a fresh one
            }
            if new_bin_post as f64 > mean_residual * 1.5 {
                score += 5.0; // existing bins still have plenty of room; keep using them
            }
        }
        let _ = fit_quality;

        // Early in stream, be slightly more willing to open bins (builds a pool)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 4.0;
        }
    } else {
        // Slight preference for bins with below-mean residual (consolidate space)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Late in stream: prioritize closing bins out, penalize spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && !is_new_bin {
        score -= 3.0 * (1.0 - (bin_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: quadratic reward shrinking with post_residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 2.5 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 3.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize proportionally.
        score += 1.5 * (post_residual as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more when open bins have room and stream is early.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But open a new bin if no tight option exists: compare with mean residual waste.
        score += 0.02 * mean_residual;
    }

    // Penalize bins whose residual deviates strongly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Late stream: prefer filling existing bins aggressively.
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes (10..80)
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    score += residue_class * 0.6;

    // Divisibility classes: exact-halve / exact-third residuals are reusable
    if pr > 0 {
        if cap as u32 % pr == 0 { score -= 4.0; }
        if pr % 2 == 0 { score -= 1.5; }
        if pr % 5 == 0 { score -= 1.0; }
        if pr % 3 == 0 { score -= 0.5; }
    }

    // Perfect fit: near-zero waste is excellent
    if pr == 0 { score -= 60.0; }
    else if pr <= 5 { score -= 25.0; }

    // Lookahead coupling: post_residual that can host next item is valuable
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match of (pr - next_item_size) again
            let rem = pr - next_item_size;
            score -= 8.0 + ((rem % 10) as f64) * 0.3;
            if rem == 0 { score -= 12.0; }
        } else {
            // dead space relative to lookahead: penalize gap size
            score += ((next_item_size - pr) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless
    // the item is large and would leave a well-structured residual
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= bin_capacity * 3 / 4 { score -= 12.0; }
        if next_item_size > 0 && next_item_size <= post_residual { score -= 6.0; }
        // opening bins early in the stream is cheaper (more future use)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    } else {
        // reward using existing bins, scaled by how full they already are
        let used_frac = 1.0 - (bin_residual as f64) / cap;
        score -= used_frac * 10.0;
    }

    // Mean residual context: if open bins are generally tight, preserve space
    if mean_residual < (item_size as f64) * 1.5 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Integer-division threshold on post_residual: tiny slivers are dead space
    if pr > 0 && pr < 10 { score += 8.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up item are "unusable" and get heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-usable gaps: moderate penalty scaled by how unusable they are
        // relative to the next item's size.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 20.0;
        } else {
            score += 5.0;
        }
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap that can still serve the next item: mild reward proportional to fit quality.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading; prefer
    // compacting into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin that should be closed out first.
    let res = bin_residual as f64;
    if mean_residual > 0.0 && res < mean_residual {
        score -= 10.0 * (mean_residual - res) / mean_residual;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit (e.g. item barely fits anywhere) or when the
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0 + open_bins_count as f64 * 0.5;
        // If the item would leave a big gap in ANY existing bin context, opening
        // a new bin becomes more attractive (post_residual here == capacity - item).
        if post_residual >= 30 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating; early, allow expansion.
        score += 15.0 * progress;
        // If many bins fit, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: lower score for small post_residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0 * tightness;
    }

    // Relative-to-mean coupling: prefer bins with residual near/below mean
    // (avoid leaving large outliers open).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_residual as u32 {
            score -= 5.0;
        }
    }

    // Late-stream pressure: consolidate into open bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins that become nearly full.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 60.0 * tightness * tightness;

    // Exact-fill bonus: residual zero is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual,
    // penalize residual that is "almost" but not enough for next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 20.0 * (1.0 - gap / 15.0); // dead space trap
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin for a single item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how much
    // usable capacity already exists in open bins.
    if bin_residual == bin_capacity {
        let usable = mean_residual * (open_bins_count as f64);
        score += 40.0 + 0.5 * usable;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // But if item is huge relative to typical residual, new bin is fine.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 70.0;
        }
    }

    // Mild penalty for wasting space relative to mean residual:
    // prefer placing into bins whose residual is near the item size.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * residual_gap;

    // Prefer bins with below-average residual (tighter bins first).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Slight preference to keep number of open bins from exploding early.
    if open_bins_count > 10 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fills are rewarded more as the stream progresses.
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Smooth quadratic penalty on wasted residual, modulated by progress.
    score += 6.0 * prn * prn * (1.0 + progress);

    // Lookahead: reward residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let kernel = (-diff * diff / 400.0).exp();
        score -= 8.0 * kernel;
    }

    // New-bin candidate: penalize mildly, less when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 10.0 - 8.0 * scarcity * (1.0 - progress);
    }

    // Last-chance bin bonus (exactly one fitting bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Deter spreading across many open bins (smooth in count).
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Coupling with mean residual: prefer bins deviating below mean late in stream.
    score += 2.0 * (pr - mean_residual) / cap * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo bands of capacity/10.
    let band = bin_capacity / 10; // 10
    let class = post_residual % band;
    let level = post_residual / band; // 0..=10

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward using bins whose residual is small relative to capacity (tight packing).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize post_residual classes that are awkward: very small nonzero residuals
    // (1..=9) are dead space since min item is 1... but tiny slivers are useless.
    if class > 0 && class < 4 {
        score += 25.0 * (4 - class) as f64;
    }
    // Residuals in mid classes are reusable; reward level >= 5 (half-full remainder).
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportional leftover after that.
            let nn = post_residual - next_item_size;
            score += 0.3 * nn as f64;
            score -= 20.0;
        } else {
            // next item won't fit here: post_residual becomes dead space; penalize.
            score += 0.5 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it competitive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes (capacity - item) immediately; neutral base plus
        // pressure from number of open bins (prefer consolidating when few bins).
        score = (bin_capacity - item_size) as f64 + 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
        if open_bins_count as f64 > mean_residual * 0.5 {
            score += 20.0; // many bins with slack: discourage opening another
        }
    } else {
        // Existing bin: reward if its residual is below mean (it's the tightest).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Stream progression: early on, be greedy for tight fits; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * tightness;
    score += progress * 3.0 * level as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1, but tiny gaps < 10 are effectively dead)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize residuals that cannot accommodate the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // lookahead-friendly
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and discourage spreading).
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 20.0 + 5.0 * open_pressure;
    } else {
        score -= 3.0 * open_pressure.min(10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // leaves others stranded; prefer bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for tighter fits overall.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-exact fills: quadratic penalty on post_residual relative to capacity.
    let fill_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fill_ratio * fill_ratio;

    // Reward tight fit relative to the item size (perfect fit bonus).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can exactly fill the post-residual,
    // this bin is a perfect pipeline — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits after this one: mild reward proportional to remaining fit.
            let pair_ratio = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * pair_ratio;
        } else {
            // Next item won't fit in this bin's leftover: penalize large dead space.
            score += 8.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high,
    // prefer consolidating into existing bins rather than spreading.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.15 * mean_gap;

    // Early in the stream, be more exploratory: slightly favor new bins to build
    // a diverse pool; later, consolidate tightly.
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // If many open bins, penalize leaving bins with tiny unusable residuals.
    if open_bins_count > 3 {
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // dead space penalty
        }
    }

    // Prefer bins whose residual is just above the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / item_size.max(1) as f64;
    score += 10.0 * snug;

    // New-bin candidate handling: only attractive when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = fitting_bins_count as f64;
        let bad_state = mean_residual / bin_capacity as f64;
        // Open a new bin only if fitting options are scarce or residuals are very tight.
        if fitting_bins_count <= 1 || bad_state < 0.15 {
            score -= 20.0;
        } else {
            score += 10.0 + 5.0 * fragmentation;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Normalize post residual and residual
    let prn = pr / cap;
    let rn = bin_residual as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, keep bins tight (small post_residual); later, tolerate slack less.
    let progress_weight = 0.5 + 2.0 * progress * (1.0 - progress) * 2.0; // peaks mid-stream
    let coupled = base * (1.0 + 0.6 * progress * prn * prn * 4.0);

    // Reward near-perfect fits with a smooth quadratic term (dead-space penalty)
    let dead_space_penalty = 1.5 * prn * prn * cap * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can host the next item
    let lookahead_bonus = if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        -6.0 * fits_next * (0.3 + tightness) * (1.0 - 0.5 * progress)
    } else {
        0.0
    };

    // Last-chance bin: strong reward to use it rather than open a new bin
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // Slight preference for bins tighter than average (smooth)
    let mean_coupling = (mean_residual - pr) * 0.15 * (1.0 + progress);

    // Mild penalty for spreading across many bins late in stream
    let bin_spread = (open_bins_count as f64).ln() * 0.3 * progress;

    // New-bin candidate: neutral-ish score scaled by progress; opening new bins is
    // penalized slightly more as stream progresses to consolidate items.
    let new_bin_bias = if rn >= 0.999 { 3.0 + 4.0 * progress + 2.0 * prn } else { 0.0 };

    let mut score = coupled + dead_space_penalty + lookahead_bonus + last_chance + mean_coupling + bin_spread + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    }

    // Harmonic classes on post_residual (mod 10): dead-space class analysis.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,          // round residual, reusable by many sizes
        1 | 2 | 3 => score += 8.0,   // slivers, mostly dead space
        4 | 5 => score -= 4.0,       // mid-small, fits typical small items
        6 | 7 => score += 2.0,
        8 | 9 => score += 5.0,
        _ => {}
    }

    // Integer-division thresholds: residual in "large item" band is valuable.
    if (pr / 10) >= 4 {
        score -= 10.0; // >=40 residual remains broadly useful
    } else if (pr / 10) == 0 && pr > 0 {
        score += 15.0; // <10 residual is nearly dead
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain-friendly: reward, scaled by how much would remain after next
            let next_post = pr - next_item_size;
            score -= 25.0 + (next_post as f64) * 0.3;
            if next_post == 0 {
                score -= 60.0; // perfect two-item chain
            }
        } else {
            score += 5.0;
        }
    } else {
        // Last item: closing bins cheaply is great.
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: penalize opening a new bin when it would be wasteful.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 120.0;
        // But if the item is large and existing residuals are small/fragmented,
        // a fresh bin may be better: reduce penalty.
        let mean_r = mean_residual;
        if item_size >= 60 && mean_r < item_size as f64 {
            score -= 100.0;
        }
        // Late in the stream, avoid spawning bins with tiny expected future use.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If only one bin fits and it leaves a huge residual, fresh bin is fine.
        if fitting_bins_count == 1 {
            let best_alt_residual = bin_residual; // placeholder reference to capacity scale
            let _ = best_alt_residual;
            score -= 30.0;
        }
        // Never let a new bin beat a perfect fit.
        if item_size == bin_capacity {
            score -= 500.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.5;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a
    // good consolidation target (keeps big holes for big items).
    let resid_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    score += (resid_frac - mean_frac) * 20.0;

    // Modulo coupling on item_size and residual: harmonic pairing bonus.
    if pr > 0 && (item_size % pr == 0 || pr % item_size.max(1) == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat residual < 10 (or < next_item_size when known) as unusable dead space.
    let dead_threshold: u32 = if next_item_size > 0 && next_item_size <= bin_capacity {
        next_item_size.min(20)
    } else {
        10
    };
    if post_residual < dead_threshold {
        // Proportionally harsh penalty for creating unusable gaps.
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Reward nearly-perfect fits (post_residual close to 0 but not dead).
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate and loosely-filled bins).
    let pressure = open_bins_count as f64 * 0.35;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when existing
        // bins would leave large dead space.
        score += 15.0 + pressure;
    } else {
        // Slight reward for using an existing bin, stronger when bins are scarce.
        score -= 8.0 - pressure.min(6.0);
    }

    // If this is the only bin that fits the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size <= 5 {
            score -= 20.0;
        } else {
            score -= 3.0;
        }
    }

    // Align with mean residual: bins far below mean residual waste capacity elsewhere.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Early in the stream, be slightly more willing to open bins (long horizon ahead).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: reward proportionally to how well it packs.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
            // Bonus if both placements nearly exhaust the bin.
            if post_residual - next_item_size <= 5 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large awkward gaps.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 10.0 + gap as f64;
            } else {
                score += 20.0 + (gap as f64).min(60.0) * 0.3;
            }
        }
    } else {
        // Last item: prefer zero waste absolutely.
        score -= 150.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: leaving below-average residual
    // is good (bin becomes compact), above-average residual is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild penalty for spreading across many open bins early in the stream;
    // encourage consolidation when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    // New-bin candidate: only attractive if current item is huge relative to a fresh
    // bin and no open bin fits well (handled implicitly by score comparisons).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        // If next item is small, a fresh bin wastes potential pairing space.
        if next_item_size > 0 && next_item_size < item_size {
            score += 10.0;
        }
    }

    score
}
